INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('doenca-arterial-coronariana', 'Doença Arterial Coronariana', 'cardiovasculares', 'Cardiovasculares', 0, 0, 'ATVB (Arteriosclerosis, Thrombosis, and Vascular Biology) 2015', 'Fatores de risco cardiovascular se acumulam de forma desproporcional em populações negras devido a estresse crônico (weathering) e acesso desigual à prevenção.', NULL, NULL, NULL);
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('diabetes', 'Diabetes Tipo 1 e 2', 'metabolicas', 'Metabólicas', 1, 1, 'CDC 2021', 'Adultos negros têm probabilidade ~60% maior de serem diagnosticados com diabetes tipo 2 em comparação a adultos brancos não hispânicos.', '8º lugar', 'No DF, diabetes caiu do 3º lugar (2014) para o 8º lugar (2024) nas causas de morte — pode indicar melhora no controle (acesso a insulina/antidiabéticos pelo SUS) ou subnotificação como causa associada. Dados ainda não estratificados por raça/cor no boletim agregado.', 'Estudo Pop. Negra DF 2015–2024 · Indicador 14 (estratificação racial pendente)');
