INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('diabetes-juvenil', 'Diabetes Tipo 1 (Juvenil)', 'metabolicas', 'Metabólicas', 0, 0, 'SEARCH for Diabetes in Youth Study 2021', 'Crianças e adolescentes negros com diabetes tipo 1 apresentam piores desfechos glicêmicos, associados a barreiras de acesso a insulina e tecnologia de monitoramento.', NULL, NULL, NULL);
