INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('doenca-renal-cronica', 'Doença Renal Crônica', 'renais-geneticas', 'Renais e Genéticas', 0, 0, 'Science / Genovese et al. 2010', 'Identificação do gene APOL1 (variantes G1/G2), mais frequente em afrodescendentes, como fator de risco para doença renal crônica.', NULL, NULL, NULL);
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('progressao-doenca-renal', 'Progressão da Doença Renal', 'renais-geneticas', 'Renais e Genéticas', 0, 0, 'JCI / Friedman & Pollak 2011', 'Variantes do gene APOL1 associadas a maior risco de progressão para diálise — encaminhamento precoce a nefrologista muda o desfecho.', NULL, NULL, NULL);
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('insuficiencia-renal', 'Insuficiência Renal', 'renais-geneticas', 'Renais e Genéticas', 0, 0, 'NEJM / Parsa et al. 2013', 'Confirmação da associação entre APOL1 e doença renal terminal. Combinado a hipertensão mal controlada e menor acesso a nefrologia, resulta em maior taxa de diálise precoce na população negra. A fila para transplante renal também carrega viés racial documentado.', NULL, NULL, NULL);
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('depressao', 'Depressão', 'saude-mental', 'Saúde Mental', 1, 1, 'JAMA Psychiatry / Williams et al. 2022', 'Pessoas negras com depressão têm menor probabilidade de receber tratamento adequado e maior probabilidade de terem o quadro subdiagnosticado por racismo institucional em saúde.', NULL, NULL, NULL);
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('ansiedade', 'Ansiedade', 'saude-mental', 'Saúde Mental', 0, 0, NULL, NULL, NULL, NULL, NULL);
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('tept', 'TEPT (Transtorno de Estresse Pós-Traumático)', 'saude-mental', 'Saúde Mental', 0, 0, NULL, NULL, NULL, NULL, NULL);
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('uso-substancias', 'Uso de Substâncias', 'saude-mental', 'Saúde Mental', 0, 0, 'SAMHSA 2021 + SENAD (Grau de Pureza de Cocaína em 4 Estados) + gov.br/MJ-OBID + Fiocruz + Jornal da USP/Brasil de Fato sobre a Lei 11.343/2006', 'Além do acesso desigual a tratamento (SAMHSA 2021), a adenda v4.1 documenta uma dupla disparidade no Brasil: (1) substâncias consumidas em contextos de baixa renda tendem a ter maior grau de adulteração/mistura do que as consumidas por quem tem alta renda, ampliando o dano por dose; (2) a aplicação da política de drogas é racialmente desigual — pessoas negras cumprem, em média, mais tempo de prisão pela mesma infração.', NULL, NULL, NULL);
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('asma', 'Asma', 'respiratorias', 'Respiratórias', 1, 1, 'CDC 2020', 'Crianças negras têm taxa de mortalidade por asma ~7x maior que crianças brancas, associada a maior exposição ambiental e menor acesso a tratamento contínuo.', NULL, NULL, NULL);
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('covid-19', 'COVID-19', 'respiratorias', 'Respiratórias', 0, 0, 'NEJM Review 2023', 'Populações negras tiveram taxas de hospitalização e mortalidade por COVID-19 desproporcionalmente mais altas, refletindo comorbidades prévias e desigualdade de acesso a cuidados críticos.', NULL, NULL, NULL);
