INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('tuberculose', 'Tuberculose', 'respiratorias', 'Respiratórias', 0, 0, 'Literatura epidemiológica nacional — associação com pobreza e acesso desigual', 'Tuberculose está associada a aglomeração domiciliar, desnutrição e menor acesso a diagnóstico/tratamento oportuno — condições mais prevalentes em contextos de vulnerabilidade social.', '58,3%', 'No DF, 58,3% dos casos novos de tuberculose em 2025 ocorreram em pessoas pardas, com tendência de aumento na incidência entre 2021 e 2025.', 'Estudo Pop. Negra DF 2015–2024 · Indicador 15 (Boletim de Tuberculose 2026, SES-DF)');
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('miomas-uterinos', 'Miomas Uterinos', 'mulher-negra', 'Saúde da Mulher Negra', 1, 1, 'FEBRASGO / ACOG — leiomiomas uterinos', 'Mulheres negras têm prevalência de miomas 2 a 3 vezes maior, com início mais precoce, tumores maiores e mais numerosos, sintomas mais graves e maior taxa de histerectomia em comparação a mulheres brancas.', NULL, NULL, NULL);
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('parto-prematuro', 'Parto Prematuro', 'mulher-negra', 'Saúde da Mulher Negra', 0, 0, NULL, NULL, NULL, NULL, NULL);
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('mortalidade-materna', 'Mortalidade Materna', 'mulher-negra', 'Saúde da Mulher Negra', 1, 0, 'Estudos nacionais e internacionais de saúde materna', 'Mulheres negras têm risco de 2 a 3 vezes maior de morte materna em comparação a mulheres brancas, mesmo controlando por renda e escolaridade — indicando peso do racismo institucional no cuidado obstétrico.', '1,39×', 'No DF (2010–2019), a Razão de Mortalidade Materna (RMM) em mulheres pretas foi 92,7 por 100.000 nascidos vivos, contra 66,7 em brancas — 39% maior. Mulheres pardas isoladamente (45,1) aparecem abaixo de brancas, um paradoxo que o estudo atribui a incompletude/subnotificação racial nos registros de óbito.', 'Estudo Pop. Negra DF 2015–2024 · Indicador 8 (SIM+SINASC, Relatório de Mortalidade Materna 2018–2019)');
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('sifilis-congenita', 'Sífilis Congênita', 'mulher-negra', 'Saúde da Mulher Negra', 0, 0, 'Doença evitável com pré-natal adequado (testagem + tratamento oportuno)', 'A sífilis congênita é totalmente evitável com testagem e tratamento no pré-natal — sua persistência reflete falhas de acesso e continuidade do cuidado obstétrico.', '78,2%', 'No DF (2024), 78,2% dos casos de sífilis congênita ocorreram em filhos de mães negras (pretas+pardas) — sobre-representação em relação aos 57,8% da população, refletindo menor cobertura/qualidade de pré-natal e barreiras de acesso a testagem.', 'Estudo Pop. Negra DF 2015–2024 · Indicador 10 (Boletim de Sífilis Congênita 2025, SES-DF)');
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('anemia-falciforme', 'Anemia Falciforme', 'raras-autoimunes', 'Raras e Autoimunes', 1, 1, 'Parceria técnica ABRADFAL (Associação Brasiliense das Pessoas com Doença Falciforme)', 'Doença genética com alta prevalência na população negra brasileira; tema prioritário do App em parceria formal com a ABRADFAL.', NULL, NULL, NULL);
