INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('cancer-mama', 'Câncer de Mama', 'oncologicas', 'Oncológicas', 0, 0, 'Literatura oncológica — subtipo triplo-negativo', 'Mulheres negras têm maior incidência do subtipo triplo-negativo (mais agressivo) e maior mortalidade por câncer de mama, mesmo com incidência geral similar ou menor.', NULL, NULL, NULL);
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('cancer-prostata', 'Câncer de Próstata', 'oncologicas', 'Oncológicas', 0, 0, 'Literatura oncológica nacional/internacional', 'Homens negros têm risco ~1,7x maior de desenvolver câncer de próstata e cerca de 2x mais chance de morrer da doença em comparação a homens brancos.', NULL, NULL, NULL);
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('cancer-colorretal', 'Câncer Colorretal', 'oncologicas', 'Oncológicas', 0, 0, 'Literatura oncológica nacional/internacional', 'População negra apresenta maior incidência e mortalidade por câncer colorretal, associadas a diagnóstico tardio e menor acesso a exames de rastreamento.', NULL, NULL, NULL);
