INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('hiv', 'HIV/AIDS', 'outras', 'Outras', 0, 0, 'Literatura epidemiológica nacional', 'População negra apresenta maior incidência de novos diagnósticos de HIV e menor acesso contínuo a tratamento antirretroviral, refletindo barreiras estruturais de acesso à saúde.', '70,3%', 'No DF (2024), 70,3% das notificações de HIV/AIDS foram de pessoas pretas ou pardas — sobre-representação em relação aos 57,8% da população, associada a menor acesso a testagem, PrEP e TARV, além de estigma (racismo + homofobia + serofobia).', 'Estudo Pop. Negra DF 2015–2024 · Indicador 16 (SINAN+SIM, Boletim HIV/AIDS 2024)');
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('prevencao-hiv-prep', 'Prevenção do HIV (PrEP)', 'outras', 'Outras', 0, 0, 'Lancet HIV 2022', 'Redução de desigualdades na incidência de HIV quando o acesso à Profilaxia Pré-Exposição (PrEP) é ampliado. PrEP é direito garantido pelo SUS — disponível gratuitamente na rede pública.', NULL, NULL, NULL);
