INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('acidentes-transporte', 'Acidentes de Transporte', 'outras', 'Outras', 0, 0, 'Associado a exposição ocupacional (entregadores) e infraestrutura viária desigual', 'Maior exposição ao trânsito por uso de transporte público e motocicletas de trabalho, combinada a infraestrutura viária mais precária em periferias, eleva o risco de óbito por acidentes de transporte em populações negras.', '72,2%', 'No DF (2012–2021), 72,2% dos óbitos por acidentes de transporte ocorreram em pessoas negras — sobre-representação de 1,25× em relação à proporção populacional (57,8%).', 'Estudo Pop. Negra DF 2015–2024 · SIM/DATASUS 2012–2021');
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('ansiedade-redes-sociais', 'Ansiedade crônica por uso irresponsável de redes sociais', 'socioeconomica-contemporanea', 'Saúde Mental e Socioeconômica Contemporânea', 0, 0, 'UNICEF Brasil · CNN Brasil · Jornal da USP · The Conversation Brasil (2024–2025)', 'Uso excessivo/compulsivo de redes sociais está associado a aumento de sintomas de ansiedade, comparação social e distúrbios de sono em adolescentes brasileiros — quadro já descrito como "epidemia" por especialistas, motivando regulamentação do uso de celulares em escolas em diversos estados.', NULL, NULL, NULL);
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('vicio-apostas', 'Vício em jogos de apostas online (bets)', 'socioeconomica-contemporanea', 'Saúde Mental e Socioeconômica Contemporânea', 0, 0, 'Datafolha/Folha de S.Paulo (2024) · Alma Preta · Revista Raça · O Joio e O Trigo', '66,8% dos apostadores brasileiros apresentam padrão de aposta problemático; o perfil mais afetado é jovem, do sexo masculino, autodeclarado negro, desempregado ou de baixa renda. Estima-se que ~1,4 milhão de brasileiros vivam hoje com transtorno relacionado a apostas, com forte concentração em periferias urbanas.', NULL, NULL, NULL);
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('abuso-substancias-disparidade', 'Abuso de substâncias — disparidade de qualidade/pureza por classe e raça', 'socioeconomica-contemporanea', 'Saúde Mental e Socioeconômica Contemporânea', 0, 0, 'SENAD ("Grau de Pureza de Cocaína em Quatro Estados") · Fiocruz (levantamento nacional sobre uso de crack) · gov.br/MJ-OBID · Jornal da USP · Brasil de Fato', 'Substâncias consumidas em contextos de baixa renda/periferia tendem a apresentar maior grau de adulteração (misturadas a outras substâncias, muitas vezes tóxicas), ampliando o dano à saúde por dose consumida, enquanto consumidores de alta renda têm acesso a substâncias de maior pureza. Simultaneamente, a política de drogas é aplicada de forma racialmente desigual — pessoas negras cumprem, em média, mais tempo de prisão pela mesma infração.', NULL, NULL, NULL);
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('violencia-reativa', 'Violência como resposta reativa (déficit de educação/inteligência emocional)', 'socioeconomica-contemporanea', 'Saúde Mental e Socioeconômica Contemporânea', 0, 0, 'Atlas da Violência 2026 (IPEA / Fórum Brasileiro de Segurança Pública)', '77% das vítimas de homicídio no Brasil são pessoas negras; taxa de 27 homicídios por 100 mil habitantes entre negros vs. 10 por 100 mil entre não negros — uma pessoa negra tem 2,6x mais chance de ser assassinada no Brasil, quadro associado à ausência de políticas preventivas de mediação de conflito e educação emocional em territórios de alta exposição à violência.', '77,4%', 'No DF (2015–2022), 77,4% das mortes violentas ocorreram em pessoas negras (predominantemente pardas, 70,2%) — sobre-representação de 1,34× em relação à proporção populacional. 89,9% das vítimas fatais são homens; já nas notificações de violência não fatal (SINAN), 83,1% das vítimas são mulheres.', 'Estudo Pop. Negra DF 2015–2024 · Indicadores 17–18 (SIM/DATASUS, SINAN Q3 2025)');
INSERT OR REPLACE INTO diseases (id, name, category_id, category_title, is_priority_theme, has_deep_content, study, finding, local_value, local_finding, local_source) VALUES ('falta-educacao-financeira', 'Falta de educação financeira', 'socioeconomica-contemporanea', 'Saúde Mental e Socioeconômica Contemporânea', 0, 0, 'Banco Central do Brasil — Relatório de Cidadania Financeira 2025', 'Mulheres negras de baixa renda pagam taxas de juros de até 140% ao ano em crédito informal/rotativo; a população negra recebe em média 58,3% do rendimento da população branca; a pontuação nacional média de educação financeira é de apenas 59,6/100 — um ciclo de vulnerabilidade financeira que é, em si, determinante social de saúde (estresse crônico, insegurança alimentar, ansiedade).', NULL, NULL, NULL);
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (1, 'anemia-falciforme', 'pt', 'medico', 'Fisiopatologia, diagnóstico diferencial, condutas clínicas e evidência atualizada para a prática médica e a pesquisa em doença falciforme (DF).', 'https://sspark.genspark.ai/i/U0fgB9sbw0tFlBV7?width=2560', 'Micrografia eletrônica colorizada comparando hemácias normais em forma de disco biconcavo com uma hemácia em formato de foice (drepanócito), característica da doença falciforme', 'Pixnio — domínio público / CC0 (placeholder científico, substituir por material próprio se necessário)', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (1, 1, 0, 'O que é — fisiopatologia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (1, 1, 0, 'A doença falciforme (DF) é uma hemoglobinopatia hereditária autossômica recessiva causada por uma mutação pontual no gene da beta-globina (HBB), no cromossomo 11 (substituição de ácido glutâmico por valina na posição 6 da cadeia beta — GAG→GTG), resultando na hemoglobina S (HbS).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (2, 1, 1, 'Em condições de baixa tensão de oxigênio, acidose ou desidratação, a HbS polimeriza, deformando a hemácia em formato de foice (drepanócito). Essas células rígidas e pouco deformáveis causam vaso-oclusão microvascular, hemólise extravascular e intravascular crônica, inflamação endotelial sustentada e um estado de hipercoagulabilidade — a tríade fisiopatológica central (vaso-oclusão, hemólise, inflamação) que explica a maior parte das manifestações clínicas.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (3, 1, 2, 'Genótipos clinicamente relevantes: HbSS (forma mais grave, "anemia falciforme" em sentido estrito), HbSC, HbS/beta-talassemia (S-beta-zero e S-beta-mais) e o traço falciforme heterozigoto HbAS (portador assintomático na maioria dos casos, mas não isento de risco em situações extremas de hipóxia/exercício intenso — rabdomiólise, morte súbita em esforço extremo são descritas, ainda que raras).');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (2, 1, 1, 'Por que importa — epidemiologia e recorte racial');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (4, 2, 0, 'A DF é a doença monogênica mais prevalente no Brasil, com incidência estimada em 1:1.000 a 1:1.400 nascidos vivos, e prevalência do traço falciforme (HbAS) de cerca de 2% na população geral — chegando a 6-10% em populações afrodescendentes de algumas regiões, refletindo a origem da mutação como provável vantagem seletiva histórica contra a malária (heterozigoto protegido) na África Subsaariana.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (5, 2, 1, 'Por sua distribuição genética ligada à ancestralidade africana, a DF é um marcador direto de como o racismo estrutural se traduz em inequidade em saúde: subdiagnóstico, atraso no início do tratamento, descrédito da dor relatada por pacientes negros (viés documentado na literatura internacional de manejo de dor) e menor investimento histórico em pesquisa comparado a condições de prevalência similar em populações majoritariamente brancas.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (3, 1, 2, 'Diagnóstico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (6, 3, 0, 'Triagem neonatal universal (Programa Nacional de Triagem Neonatal / "teste do pezinho", Portaria MS) por eletroforese em pH alcalino ou HPLC — padrão-ouro para confirmação diagnóstica, complementado por estudo familiar quando indicado.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (7, 3, 1, 'Diagnóstico diferencial inclui outras hemoglobinopatias (HbC, HbD-Punjab, talassemias), anemias hemolíticas de outras etiologias e, na crise aguda, abdome agudo cirúrgico, osteomielite e artrite séptica (importante em criança com dor óssea e febre).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (8, 3, 2, 'Acompanhamento laboratorial de rotina: hemograma completo com reticulócitos, LDH, bilirrubina indireta, função renal (a nefropatia falciforme é subdiagnosticada), ultrassom transcraniano com Doppler em crianças (triagem de risco de AVC isquêmico) e avaliação cardiopulmonar periódica (ecocardiograma para hipertensão pulmonar, função respiratória).');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (4, 1, 3, 'Tratamento e condutas');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (9, 4, 0, 'Hidroxiureia é a terapia modificadora de doença de primeira linha, disponível no SUS — aumenta HbF (hemoglobina fetal), reduzindo frequência de crises vaso-oclusivas e síndrome torácica aguda; requer monitoramento hematológico (risco de mielossupressão) e ajuste de dose individualizado.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (10, 4, 1, 'Profilaxia com penicilina oral até os 5 anos (risco aumentado de sepse por S. pneumoniae por asplenia funcional) e esquema vacinal ampliado (pneumocócica conjugada e polissacarídica, meningocócica, Haemophilus influenzae tipo b) são condutas-padrão em crianças com HbSS/S-beta-zero.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (11, 4, 2, 'Manejo da crise vaso-oclusiva: hidratação, analgesia multimodal e escalonada (incluindo opioides quando indicado — vigilância ativa contra subtratamento da dor por viés racial), oxigenoterapia se hipoxemia, e investigação de gatilhos/complicações associadas.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (12, 4, 3, 'Transfusão crônica (programa de hipertransfusão ou exsanguineotransfusão parcial) indicada em prevenção secundária de AVC, síndrome torácica aguda grave e outras complicações graves recorrentes; requer vigilância de sobrecarga de ferro (quelação) e aloimunização.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (13, 4, 4, 'Terapias emergentes: voxelotor (inibidor de polimerização da HbS), crizanlizumabe (anti-P-selectina, redução de crises vaso-oclusivas), L-glutamina oral, e terapia genética (edição de genes — exa-cel/Casgevy, lovotibeglogene autotemcel) já aprovadas em outras jurisdições, com discussão de incorporação no SUS em curso — acompanhar PCDT vigente do Ministério da Saúde.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (14, 4, 5, 'Transplante de células-tronco hematopoiéticas (TCTH) alogênico permanece a única modalidade curativa estabelecida, reservado a casos graves com doador compatível, dado o risco de morbimortalidade do procedimento.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (5, 1, 4, 'Quando referenciar / sinais de alarme clínico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (15, 5, 0, 'Febre ≥38°C em paciente com DF é emergência até prova em contrário (risco de sepse por asplenia funcional) — hemocultura e antibioticoterapia empírica precoce.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (16, 5, 1, 'Síndrome torácica aguda (novo infiltrado radiológico + febre/dor torácica/hipoxemia) é a principal causa de morte em adultos com DF — manejo hospitalar agressivo, suporte respiratório e considerar exsanguineotransfusão.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (17, 5, 2, 'Déficit neurológico focal agudo (mesmo transitório) exige investigação imediata de AVC — maior risco em crianças com HbSS, rastreio por Doppler transcraniano permite prevenção primária com transfusão crônica.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (18, 5, 3, 'Priapismo >4h, sequestro esplênico agudo (criança pequena, esplenomegalia súbita + queda de Hb) e crise aplásica (geralmente por parvovírus B19) são emergências que exigem intervenção imediata.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (6, 1, 5, 'Fontes e diretrizes');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (19, 6, 0, 'Protocolo Clínico e Diretrizes Terapêuticas (PCDT) da Doença Falciforme, Ministério da Saúde — referência normativa para conduta no SUS.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (20, 6, 1, 'Parceria técnica ABRADFAL (Associação Brasiliense das Pessoas com Doença Falciforme) fundamenta a curadoria e revisão deste conteúdo junto ao App Sentinela.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (21, 6, 2, 'Literatura internacional consolidada (NHLBI Evidence-Based Management of Sickle Cell Disease; American Society of Hematology guidelines) orienta as condutas descritas acima — sempre cotejar com protocolo institucional local.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (2, 'anemia-falciforme', 'pt', 'enfermeiro', 'Triagem, manejo de crises, cuidado continuado e orientação ao paciente/família — conteúdo clínico de nível intermediário para a rotina de enfermagem na Atenção Básica e na urgência/emergência.', 'https://sspark.genspark.ai/i/U0fgB9sbw0tFlBV7?width=2560', 'Micrografia eletrônica colorizada comparando hemácias normais em forma de disco biconcavo com uma hemácia em formato de foice (drepanócito), característica da doença falciforme', 'Pixnio — domínio público / CC0 (placeholder científico, substituir por material próprio se necessário)', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (7, 2, 0, 'O que é');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (22, 7, 0, 'A doença falciforme é uma condição genética hereditária (não é contagiosa, não é "contaminação") em que as hemácias, em vez de manterem o formato arredondado normal, podem assumir formato de foice sob certas condições (falta de oxigênio, desidratação, frio, esforço físico intenso, infecção).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (23, 7, 1, 'Essas hemácias em foice são mais rígidas e "entopem" vasos sanguíneos pequenos, causando dor (crise) e, ao longo do tempo, dano a órgãos como baço, rins, pulmões e ossos. A pessoa com DF também tem anemia crônica, porque essas hemácias se rompem (hemolisam) mais rápido que o normal.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (8, 2, 1, 'Sinais que a equipe deve reconhecer');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (24, 8, 0, 'Dor aguda e intensa, geralmente em ossos longos, peito, abdômen ou articulações — é o motivo mais comum de busca por atendimento, chamada de "crise de dor" ou "crise vaso-oclusiva". A intensidade relatada pelo paciente deve ser sempre levada a sério: pessoas negras historicamente têm sua dor subestimada e subtratada no sistema de saúde — é um viés a ser ativamente combatido na triagem.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (25, 8, 1, 'Palidez, icterícia (olhos/pele amarelados), cansaço desproporcional e falta de ar podem indicar agravamento da anemia ou sequestro esplênico (em crianças pequenas).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (26, 8, 2, 'Febre em pessoa com DF NUNCA deve ser minimizada — classificar como prioridade alta/vermelha no acolhimento, pois pode ser sinal de infecção grave (o baço geralmente não funciona bem nessas pessoas, aumentando risco de infecções graves).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (27, 8, 3, 'Falta de ar associada a dor no peito e febre pode ser síndrome torácica aguda, uma complicação grave que precisa de avaliação médica imediata.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (28, 8, 4, 'Em homens, ereção dolorosa prolongada (priapismo, mais de 4 horas) é emergência urológica — orientar busca imediata de atendimento.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (9, 2, 2, 'Quem fica atento — grupos de risco e acompanhamento');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (29, 9, 0, 'Toda criança deve ter o resultado do "teste do pezinho" verificado — é nele que a DF costuma ser identificada no Brasil, ainda nos primeiros dias de vida. Crianças diagnosticadas precisam de acompanhamento regular, vacinação em dia (incluindo vacinas extras recomendadas) e, até os 5 anos, uso contínuo de penicilina para prevenir infecções graves — reforçar a adesão com a família em cada contato.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (30, 9, 1, 'Adultos com DF precisam de acompanhamento hematológico regular, mesmo em períodos sem crise — a doença continua "trabalhando" silenciosamente nos órgãos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (31, 9, 2, 'Pessoas com traço falciforme (que têm o "gene", mas não a doença) geralmente não têm sintomas, mas devem saber informar isso em situações de exercício físico extremo, desidratação severa ou altitude elevada, e é informação relevante para planejamento familiar (risco de ter filho com a doença se o parceiro/parceira também tiver o traço).');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (10, 2, 3, 'Manejo da crise de dor — o que fazer na unidade');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (32, 10, 0, 'Acolher rapidamente, classificar risco considerando a história de DF como fator automático de atenção prioritária, e iniciar hidratação (oral se tolerado, venosa se necessário) o quanto antes.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (33, 10, 1, 'Seguir o protocolo de analgesia escalonada da unidade sem demora — crises de dor falciforme exigem controle rápido e eficaz da dor; não é "drama" nem "procura por medicamento controlado", é manifestação direta da doença.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (34, 10, 2, 'Observar sinais vitais, saturação de oxigênio e temperatura com frequência — aplicar oxigênio se houver queda de saturação.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (35, 10, 3, 'Registrar e comunicar imediatamente à equipe médica qualquer sinal de alarme: febre, dificuldade respiratória, dor torácica, alteração neurológica (fala, força, visão), priapismo ou baço muito aumentado em criança.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (11, 2, 4, 'Cuidado continuado e orientação ao paciente/família');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (36, 11, 0, 'Reforçar hidratação adequada no dia a dia, evitar exposição a frio intenso e extremos de esforço físico sem preparo, e buscar atendimento precoce diante de febre — são as orientações de autocuidado mais efetivas para reduzir crises.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (37, 11, 1, 'Orientar sobre a importância de não interromper a hidroxiureia (quando prescrita) sem orientação médica, mesmo em períodos sem sintomas — é tratamento contínuo, não "de crise".');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (38, 11, 2, 'Apoiar psicossocialmente: DF é doença crônica, dolorosa e muitas vezes invisibilizada; o acolhimento humanizado da equipe de enfermagem é determinante para a adesão ao tratamento e para a confiança no sistema de saúde.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (39, 11, 3, 'Encaminhar à Rede SUS local (ver página "Rede SUS" desta plataforma) para vínculo com hematologia de referência, serviço social e, quando pertinente, a ABRADFAL (associação de pacientes, parceira técnica deste projeto).');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (3, 'anemia-falciforme', 'pt', 'usuario', 'O que é a anemia falciforme, sinais de alerta, cuidados do dia a dia e onde buscar ajuda no SUS — em linguagem simples e direta.', 'https://sspark.genspark.ai/i/U0fgB9sbw0tFlBV7?width=2560', 'Micrografia eletrônica colorizada comparando hemácias normais em forma de disco biconcavo com uma hemácia em formato de foice (drepanócito), característica da doença falciforme', 'Pixnio — domínio público / CC0 (placeholder científico, substituir por material próprio se necessário)', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (12, 3, 0, 'O que é');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (40, 12, 0, 'A anemia falciforme (também chamada de doença falciforme) é uma doença do sangue que a pessoa já nasce com ela — passada pelos pais, no "sangue" (genes). Não é uma doença contagiosa: não se "pega" de ninguém.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (41, 12, 1, 'Na anemia falciforme, os glóbulos vermelhos do sangue (que levam oxigênio para o corpo) podem mudar de formato: em vez de redondinhos, ficam parecidos com uma foice (lua crescente). Esses glóbulos em formato de foice entopem vasinhos de sangue pequenos, o que causa dores fortes e pode machucar órgãos do corpo com o tempo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (42, 12, 2, 'É a doença genética mais comum no Brasil, e é bem mais frequente entre pessoas negras — por isso é um tema tão importante para a nossa comunidade.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (13, 3, 1, 'Por que isso importa');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (43, 13, 0, 'Quem tem anemia falciforme pode ter uma vida longa e de qualidade com acompanhamento médico regular, remédios certos e cuidados simples no dia a dia. O problema não é a doença "não ter solução" — é o atraso no diagnóstico, o preconceito, e a dor da pessoa não ser levada a sério nos atendimentos de saúde.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (44, 13, 1, 'Historicamente, a dor de pessoas negras é mais desacreditada nos hospitais. Isso é um tipo de racismo institucional que custa vidas — e é algo que esta plataforma existe para combater.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (14, 3, 2, 'Sinais de alerta — fique atento(a)');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (45, 14, 0, 'Dor forte e repentina em ossos, barriga, peito ou juntas — é a chamada "crise de dor" e é o sinal mais comum. Nunca minimize: procure atendimento.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (46, 14, 1, 'Febre é sempre um sinal de alerta em pessoa com anemia falciforme — mesmo que pareça "só uma febrezinha", procure a Unidade Básica de Saúde (UBS) ou emergência no mesmo dia.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (47, 14, 2, 'Cansaço fora do normal, falta de ar, olhos ou pele amarelados (icterícia) e palidez podem indicar que a anemia está mais forte — vale uma consulta.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (48, 14, 3, 'Criança pequena com a barriga inchando de repente (baço aumentado) precisa de atendimento urgente.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (49, 14, 4, 'Em homens, ereção dolorida que não passa (mais de 4 horas) é emergência — procure o hospital imediatamente, não espere.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (15, 3, 3, 'Cuidados do dia a dia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (50, 15, 0, 'Beba bastante água todos os dias — a desidratação é um dos principais gatilhos de crise de dor.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (51, 15, 1, 'Evite ficar muito tempo no frio intenso e evite esforço físico muito pesado sem preparo — ambos podem provocar crises.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (52, 15, 2, 'Se toma remédio contínuo (como hidroxiureia), não pare por conta própria, mesmo se estiver se sentindo bem — ele ajuda a prevenir crises mesmo quando você não sente nada.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (53, 15, 3, 'Mantenha as vacinas em dia — pessoas com anemia falciforme têm risco maior de infecções graves, então estar vacinado(a) é uma proteção extra importante.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (54, 15, 4, 'Se seu filho(a) tem anemia falciforme e tem menos de 5 anos, o uso diário de penicilina (conforme orientação médica) ajuda a prevenir infecções graves — é um cuidado simples, mas que salva vidas.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (16, 3, 4, 'Onde buscar ajuda no SUS');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (55, 16, 0, 'Todo bebê faz o "teste do pezinho" nos primeiros dias de vida — é assim que a anemia falciforme costuma ser descoberta no Brasil. Se seu filho(a) tem o diagnóstico, procure a Unidade Básica de Saúde (UBS) da sua região para ser encaminhado(a) ao acompanhamento com hematologia.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (56, 16, 1, 'Para dor forte ou febre, vá à UBS mais próxima ou, se for fora do horário ou a dor for muito intensa, procure a UPA (Unidade de Pronto Atendimento) ou pronto-socorro.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (57, 16, 2, 'Use a página "Rede SUS" desta plataforma para encontrar as unidades de saúde mais próximas de você no Distrito Federal.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (58, 16, 3, 'A ABRADFAL (Associação Brasiliense das Pessoas com Doença Falciforme) é parceira deste projeto e pode oferecer apoio, informação e acolhimento entre pessoas que vivem a mesma realidade.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (1, 'anemia-falciforme', 'pt', 0, 'ABRADFAL', 'Associação Brasiliense das Pessoas com Doença Falciforme — parceria técnica de conteúdo e curadoria clínica.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (2, 'anemia-falciforme', 'pt', 1, 'Ministério da Saúde — PCDT Doença Falciforme', 'Protocolo Clínico e Diretrizes Terapêuticas vigente, referência normativa para a conduta no SUS.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (3, 'anemia-falciforme', 'pt', 2, 'Programa Nacional de Triagem Neonatal', '"Teste do pezinho" — diagnóstico precoce padrão no Brasil, base da identificação neonatal da doença falciforme.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (4, 'anemia-falciforme', 'pt', 3, 'NHLBI / American Society of Hematology', 'Diretrizes internacionais de manejo clínico baseado em evidência, usadas como referência complementar.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (4, 'anemia-falciforme', 'es', 'medico', 'Fisiopatología, diagnóstico diferencial, conductas clínicas y evidencia actualizada para la práctica médica y la investigación en enfermedad falciforme (EF).', 'https://sspark.genspark.ai/i/U0fgB9sbw0tFlBV7?width=2560', 'Micrografía electrónica coloreada que compara glóbulos rojos normales con forma de disco bicóncavo con un glóbulo rojo en forma de hoz (drepanocito), característico de la enfermedad falciforme', 'Pixnio — dominio público / CC0 (placeholder científico, sustituir por material propio si es necesario)', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (17, 4, 0, 'Qué es — fisiopatología');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (59, 17, 0, 'La enfermedad falciforme (EF) es una hemoglobinopatía hereditaria autosómica recesiva causada por una mutación puntual en el gen de la beta-globina (HBB), en el cromosoma 11 (sustitución de ácido glutámico por valina en la posición 6 de la cadena beta — GAG→GTG), que da lugar a la hemoglobina S (HbS).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (60, 17, 1, 'En condiciones de baja tensión de oxígeno, acidosis o deshidratación, la HbS polimeriza, deformando el glóbulo rojo en forma de hoz (drepanocito). Estas células rígidas y poco deformables provocan vasoclusión microvascular, hemólisis extravascular e intravascular crónica, inflamación endotelial sostenida y un estado de hipercoagulabilidad — la tríada fisiopatológica central (vasoclusión, hemólisis, inflamación) que explica la mayoría de las manifestaciones clínicas.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (61, 17, 2, 'Genotipos clínicamente relevantes: HbSS (forma más grave, "anemia de células falciformes" en sentido estricto), HbSC, HbS/beta-talasemia (S-beta-cero y S-beta-más) y el rasgo falciforme heterocigoto HbAS (portador asintomático en la mayoría de los casos, aunque no exento de riesgo en situaciones extremas de hipoxia/ejercicio intenso — se han descrito rabdomiólisis y muerte súbita por esfuerzo extremo, aunque son raras).');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (18, 4, 1, 'Por qué importa — epidemiología y enfoque racial');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (62, 18, 0, 'La EF es la enfermedad monogénica más prevalente en Brasil, con una incidencia estimada de 1:1.000 a 1:1.400 nacidos vivos, y una prevalencia del rasgo falciforme (HbAS) de alrededor del 2% en la población general — llegando al 6-10% en poblaciones afrodescendientes de algunas regiones, lo que refleja el origen de la mutación como una probable ventaja selectiva histórica contra la malaria (heterocigoto protegido) en el África subsahariana.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (63, 18, 1, 'Por su distribución genética vinculada a la ascendencia africana, la EF es un marcador directo de cómo el racismo estructural se traduce en inequidad en salud: subdiagnóstico, retraso en el inicio del tratamiento, descrédito del dolor relatado por pacientes negros (sesgo documentado en la literatura internacional de manejo del dolor) y menor inversión histórica en investigación comparada con condiciones de prevalencia similar en poblaciones mayoritariamente blancas.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (19, 4, 2, 'Diagnóstico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (64, 19, 0, 'Cribado neonatal universal (Programa Nacional de Cribado Neonatal / "prueba del talón", normativa del Ministerio de Salud de Brasil) mediante electroforesis en pH alcalino o HPLC — estándar de referencia para la confirmación diagnóstica, complementado con estudio familiar cuando esté indicado.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (65, 19, 1, 'El diagnóstico diferencial incluye otras hemoglobinopatías (HbC, HbD-Punjab, talasemias), anemias hemolíticas de otras etiologías y, en la crisis aguda, abdomen agudo quirúrgico, osteomielitis y artritis séptica (importante en niños con dolor óseo y fiebre).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (66, 19, 2, 'Seguimiento de laboratorio de rutina: hemograma completo con reticulocitos, LDH, bilirrubina indirecta, función renal (la nefropatía falciforme está subdiagnosticada), ecografía transcraneal con Doppler en niños (cribado de riesgo de ictus isquémico) y evaluación cardiopulmonar periódica (ecocardiograma para hipertensión pulmonar, función respiratoria).');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (20, 4, 3, 'Tratamiento y conductas');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (67, 20, 0, 'La hidroxiurea es la terapia modificadora de la enfermedad de primera línea, disponible en el SUS (sistema público de salud de Brasil) — aumenta la HbF (hemoglobina fetal), reduciendo la frecuencia de crisis vasoclusivas y del síndrome torácico agudo; requiere monitorización hematológica (riesgo de mielosupresión) y ajuste de dosis individualizado.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (68, 20, 1, 'La profilaxis con penicilina oral hasta los 5 años (riesgo aumentado de sepsis por S. pneumoniae debido a asplenia funcional) y un esquema de vacunación ampliado (neumocócica conjugada y polisacárida, meningocócica, Haemophilus influenzae tipo b) son conductas estándar en niños con HbSS/S-beta-cero.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (69, 20, 2, 'Manejo de la crisis vasoclusiva: hidratación, analgesia multimodal y escalonada (incluyendo opioides cuando esté indicado — vigilancia activa contra el subtratamiento del dolor por sesgo racial), oxigenoterapia si hay hipoxemia, e investigación de desencadenantes/complicaciones asociadas.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (70, 20, 3, 'La transfusión crónica (programa de hipertransfusión o exanguinotransfusión parcial) está indicada en la prevención secundaria de ictus, síndrome torácico agudo grave y otras complicaciones graves recurrentes; requiere vigilancia de la sobrecarga de hierro (quelación) y de la aloinmunización.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (71, 20, 4, 'Terapias emergentes: voxelotor (inhibidor de la polimerización de la HbS), crizanlizumab (anti-P-selectina, reducción de crisis vasoclusivas), L-glutamina oral, y terapia génica (edición genética — exa-cel/Casgevy, lovotibeglogene autotemcel) ya aprobadas en otras jurisdicciones, con discusión en curso sobre su incorporación al SUS — seguir el PCDT (Protocolo Clínico y Directrices Terapéuticas) vigente del Ministerio de Salud de Brasil.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (72, 20, 5, 'El trasplante alogénico de células progenitoras hematopoyéticas (TCPH) sigue siendo la única modalidad curativa establecida, reservada para casos graves con donante compatible, dado el riesgo de morbimortalidad del procedimiento.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (21, 4, 4, 'Cuándo referir / signos de alarma clínica');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (73, 21, 0, 'La fiebre ≥38°C en un paciente con EF es una urgencia hasta que se demuestre lo contrario (riesgo de sepsis por asplenia funcional) — hemocultivo y antibioticoterapia empírica precoz.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (74, 21, 1, 'El síndrome torácico agudo (nuevo infiltrado radiológico + fiebre/dolor torácico/hipoxemia) es la principal causa de muerte en adultos con EF — manejo hospitalario agresivo, soporte respiratorio y considerar exanguinotransfusión.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (75, 21, 2, 'Un déficit neurológico focal agudo (incluso transitorio) exige investigación inmediata de ictus — mayor riesgo en niños con HbSS; el cribado con Doppler transcraneal permite la prevención primaria mediante transfusión crónica.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (76, 21, 3, 'El priapismo de más de 4 horas, el secuestro esplénico agudo (niño pequeño, esplenomegalia súbita + caída de Hb) y la crisis aplásica (generalmente por parvovirus B19) son urgencias que exigen intervención inmediata.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (22, 4, 5, 'Fuentes y directrices');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (77, 22, 0, 'Protocolo Clínico y Directrices Terapéuticas (PCDT) de la Enfermedad Falciforme, Ministerio de Salud de Brasil — referencia normativa para la conducta en el SUS.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (78, 22, 1, 'La colaboración técnica con ABRADFAL (Asociación Brasiliense de Personas con Enfermedad Falciforme) fundamenta la curaduría y revisión de este contenido junto con el App Sentinela.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (79, 22, 2, 'La literatura internacional consolidada (NHLBI Evidence-Based Management of Sickle Cell Disease; directrices de la American Society of Hematology) orienta las conductas descritas anteriormente — siempre cotejar con el protocolo institucional local.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (5, 'anemia-falciforme', 'es', 'enfermeiro', 'Cribado, manejo de crisis, cuidado continuo y orientación al paciente/familia — contenido clínico de nivel intermedio para la rutina de enfermería en Atención Primaria y en urgencias/emergencias.', 'https://sspark.genspark.ai/i/U0fgB9sbw0tFlBV7?width=2560', 'Micrografía electrónica coloreada que compara glóbulos rojos normales con forma de disco bicóncavo con un glóbulo rojo en forma de hoz (drepanocito), característico de la enfermedad falciforme', 'Pixnio — dominio público / CC0 (placeholder científico, sustituir por material propio si es necesario)', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (23, 5, 0, 'Qué es');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (80, 23, 0, 'La enfermedad falciforme es una condición genética hereditaria (no es contagiosa, no es "contaminación") en la que los glóbulos rojos, en lugar de mantener la forma redondeada normal, pueden adoptar forma de hoz bajo ciertas condiciones (falta de oxígeno, deshidratación, frío, esfuerzo físico intenso, infección).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (81, 23, 1, 'Estos glóbulos en forma de hoz son más rígidos y "obstruyen" vasos sanguíneos pequeños, causando dolor (crisis) y, con el tiempo, daño a órganos como el bazo, los riñones, los pulmones y los huesos. La persona con EF también tiene anemia crónica, porque estos glóbulos se rompen (se hemolizan) más rápido de lo normal.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (24, 5, 1, 'Señales que el equipo debe reconocer');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (82, 24, 0, 'Dolor agudo e intenso, generalmente en huesos largos, pecho, abdomen o articulaciones — es el motivo más común de búsqueda de atención, llamado "crisis de dolor" o "crisis vasoclusiva". La intensidad relatada por el paciente siempre debe tomarse en serio: las personas negras históricamente han tenido su dolor subestimado y subtratado en el sistema de salud — es un sesgo que debe combatirse activamente en la clasificación de riesgo (triage).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (83, 24, 1, 'La palidez, la ictericia (ojos/piel amarillentos), el cansancio desproporcionado y la falta de aire pueden indicar un empeoramiento de la anemia o un secuestro esplénico (en niños pequeños).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (84, 24, 2, 'La fiebre en una persona con EF NUNCA debe minimizarse — clasificar como prioridad alta/roja en la recepción, ya que puede ser señal de una infección grave (el bazo generalmente no funciona bien en estas personas, lo que aumenta el riesgo de infecciones graves).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (85, 24, 3, 'La falta de aire asociada a dolor en el pecho y fiebre puede ser un síndrome torácico agudo, una complicación grave que necesita evaluación médica inmediata.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (86, 24, 4, 'En hombres, una erección dolorosa prolongada (priapismo, más de 4 horas) es una urgencia urológica — orientar la búsqueda inmediata de atención.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (25, 5, 2, 'Quién debe estar atento — grupos de riesgo y seguimiento');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (87, 25, 0, 'Todo niño debe tener verificado el resultado de la "prueba del talón" — es así como la EF suele identificarse en Brasil, en los primeros días de vida. Los niños diagnosticados necesitan seguimiento regular, vacunación al día (incluyendo vacunas adicionales recomendadas) y, hasta los 5 años, uso continuo de penicilina para prevenir infecciones graves — reforzar la adherencia con la familia en cada contacto.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (88, 25, 1, 'Los adultos con EF necesitan seguimiento hematológico regular, incluso en períodos sin crisis — la enfermedad sigue "trabajando" silenciosamente en los órganos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (89, 25, 2, 'Las personas con rasgo falciforme (que tienen el "gen", pero no la enfermedad) generalmente no presentan síntomas, pero deben saber informarlo en situaciones de ejercicio físico extremo, deshidratación severa o altitud elevada, y es información relevante para la planificación familiar (riesgo de tener un hijo con la enfermedad si la pareja también tiene el rasgo).');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (26, 5, 3, 'Manejo de la crisis de dolor — qué hacer en la unidad');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (90, 26, 0, 'Recibir rápidamente, clasificar el riesgo considerando el antecedente de EF como factor automático de atención prioritaria, e iniciar hidratación (oral si se tolera, intravenosa si es necesario) lo antes posible.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (91, 26, 1, 'Seguir el protocolo de analgesia escalonada de la unidad sin demora — las crisis de dolor falciforme exigen un control rápido y eficaz del dolor; no es "drama" ni "búsqueda de medicamento controlado", es una manifestación directa de la enfermedad.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (92, 26, 2, 'Observar los signos vitales, la saturación de oxígeno y la temperatura con frecuencia — aplicar oxígeno si hay caída de la saturación.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (93, 26, 3, 'Registrar y comunicar inmediatamente al equipo médico cualquier señal de alarma: fiebre, dificultad respiratoria, dolor torácico, alteración neurológica (habla, fuerza, visión), priapismo o bazo muy aumentado en un niño.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (27, 5, 4, 'Cuidado continuo y orientación al paciente/familia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (94, 27, 0, 'Reforzar la hidratación adecuada en el día a día, evitar la exposición al frío intenso y a esfuerzos físicos extremos sin preparación, y buscar atención temprana ante fiebre — son las orientaciones de autocuidado más efectivas para reducir las crisis.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (95, 27, 1, 'Orientar sobre la importancia de no interrumpir la hidroxiurea (cuando esté prescrita) sin orientación médica, incluso en períodos sin síntomas — es un tratamiento continuo, no "de crisis".');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (96, 27, 2, 'Apoyar psicosocialmente: la EF es una enfermedad crónica, dolorosa y muchas veces invisibilizada; la atención humanizada del equipo de enfermería es determinante para la adherencia al tratamiento y para la confianza en el sistema de salud.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (97, 27, 3, 'Derivar a la Red SUS local (ver la página "Red SUS" de esta plataforma) para vincular con hematología de referencia, servicio social y, cuando sea pertinente, con ABRADFAL (asociación de pacientes, socia técnica de este proyecto).');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (6, 'anemia-falciforme', 'es', 'usuario', 'Qué es la anemia falciforme, señales de alerta, cuidados del día a día y dónde buscar ayuda en el SUS — en lenguaje simple y directo.', 'https://sspark.genspark.ai/i/U0fgB9sbw0tFlBV7?width=2560', 'Micrografía electrónica coloreada que compara glóbulos rojos normales con forma de disco bicóncavo con un glóbulo rojo en forma de hoz (drepanocito), característico de la enfermedad falciforme', 'Pixnio — dominio público / CC0 (placeholder científico, sustituir por material propio si es necesario)', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (28, 6, 0, 'Qué es');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (98, 28, 0, 'La anemia falciforme (también llamada enfermedad falciforme) es una enfermedad de la sangre con la que la persona ya nace — transmitida por los padres, en la "sangre" (genes). No es una enfermedad contagiosa: no se "contagia" de nadie.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (99, 28, 1, 'En la anemia falciforme, los glóbulos rojos de la sangre (que llevan oxígeno al cuerpo) pueden cambiar de forma: en lugar de ser redonditos, se parecen a una hoz (luna creciente). Estos glóbulos en forma de hoz obstruyen vasos sanguíneos pequeños, lo que causa dolores fuertes y puede dañar órganos del cuerpo con el tiempo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (100, 28, 2, 'Es la enfermedad genética más común en Brasil, y es mucho más frecuente entre personas negras — por eso es un tema tan importante para nuestra comunidad.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (29, 6, 1, 'Por qué esto importa');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (101, 29, 0, 'Quien tiene anemia falciforme puede tener una vida larga y de calidad con seguimiento médico regular, los medicamentos correctos y cuidados simples en el día a día. El problema no es que la enfermedad "no tenga solución" — es el retraso en el diagnóstico, el prejuicio, y que el dolor de la persona no sea tomado en serio en las atenciones de salud.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (102, 29, 1, 'Históricamente, el dolor de las personas negras es más desacreditado en los hospitales. Esto es un tipo de racismo institucional que cuesta vidas — y es algo que esta plataforma existe para combatir.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (30, 6, 2, 'Señales de alerta — esté atento(a)');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (103, 30, 0, 'Dolor fuerte y repentino en huesos, barriga, pecho o articulaciones — es la llamada "crisis de dolor" y es la señal más común. Nunca lo minimice: busque atención.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (104, 30, 1, 'La fiebre siempre es una señal de alerta en una persona con anemia falciforme — aunque parezca "solo una febrecita", busque la Unidad Básica de Salud (UBS) o emergencia el mismo día.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (105, 30, 2, 'Cansancio fuera de lo normal, falta de aire, ojos o piel amarillentos (ictericia) y palidez pueden indicar que la anemia está más fuerte — vale la pena una consulta.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (106, 30, 3, 'Un niño pequeño con la barriga hinchándose de repente (bazo aumentado) necesita atención urgente.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (107, 30, 4, 'En hombres, una erección dolorida que no pasa (más de 4 horas) es una emergencia — busque el hospital inmediatamente, no espere.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (31, 6, 3, 'Cuidados del día a día');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (108, 31, 0, 'Beba suficiente agua todos los días — la deshidratación es uno de los principales desencadenantes de la crisis de dolor.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (109, 31, 1, 'Evite estar mucho tiempo con frío intenso y evite el esfuerzo físico muy pesado sin preparación — ambos pueden provocar crisis.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (110, 31, 2, 'Si toma un medicamento continuo (como hidroxiurea), no lo suspenda por cuenta propia, aunque se sienta bien — ayuda a prevenir crisis incluso cuando usted no siente nada.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (111, 31, 3, 'Mantenga las vacunas al día — las personas con anemia falciforme tienen mayor riesgo de infecciones graves, por lo que estar vacunado(a) es una protección extra importante.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (112, 31, 4, 'Si su hijo(a) tiene anemia falciforme y tiene menos de 5 años, el uso diario de penicilina (según orientación médica) ayuda a prevenir infecciones graves — es un cuidado simple, pero que salva vidas.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (32, 6, 4, 'Dónde buscar ayuda en el SUS');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (113, 32, 0, 'A todo bebé se le hace la "prueba del talón" en los primeros días de vida — así es como la anemia falciforme suele descubrirse en Brasil. Si su hijo(a) tiene el diagnóstico, busque la Unidad Básica de Salud (UBS) de su región para ser derivado(a) al seguimiento con hematología.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (114, 32, 1, 'Para dolor fuerte o fiebre, vaya a la UBS más cercana o, si es fuera de horario o el dolor es muy intenso, busque la UPA (Unidad de Atención Inmediata) o el servicio de urgencias.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (115, 32, 2, 'Use la página "Red SUS" de esta plataforma para encontrar las unidades de salud más cercanas a usted en el Distrito Federal.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (116, 32, 3, 'ABRADFAL (Asociación Brasiliense de Personas con Enfermedad Falciforme) es socia de este proyecto y puede ofrecer apoyo, información y acogida entre personas que viven la misma realidad.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (5, 'anemia-falciforme', 'es', 0, 'ABRADFAL', 'Asociación Brasiliense de Personas con Enfermedad Falciforme — colaboración técnica de contenido y curaduría clínica.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (6, 'anemia-falciforme', 'es', 1, 'Ministerio de Salud de Brasil — PCDT Enfermedad Falciforme', 'Protocolo Clínico y Directrices Terapéuticas vigente, referencia normativa para la conducta en el SUS.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (7, 'anemia-falciforme', 'es', 2, 'Programa Nacional de Cribado Neonatal', '"Prueba del talón" — diagnóstico precoz estándar en Brasil, base de la identificación neonatal de la enfermedad falciforme.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (8, 'anemia-falciforme', 'es', 3, 'NHLBI / American Society of Hematology', 'Directrices internacionales de manejo clínico basado en evidencia, usadas como referencia complementaria.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (7, 'hipertensao', 'pt', 'medico', 'Fisiopatologia, estratificação de risco, metas pressóricas, racional terapêutico e evidência sobre disparidades raciais no controle da hipertensão arterial sistêmica (HAS).', 'https://sspark.genspark.ai/i/DYbur7l9KsuZidYX?width=2560', 'Medição da pressão arterial com esfigmomanômetro e manguito no braço de uma pessoa', 'Imagem placeholder (CC/PD) — substituir por material próprio se necessário', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (33, 7, 0, 'O que é — fisiopatologia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (117, 33, 0, 'A hipertensão arterial sistêmica (HAS) é uma condição crônica multifatorial caracterizada pela elevação sustentada da pressão arterial (PA), decorrente da interação entre determinantes genéticos, neuro-hormonais (sistema renina-angiotensina-aldosterona, sistema nervoso simpático), metabólicos e ambientais. Não é apenas um "número elevado": é o principal fator de risco modificável para doença cardiovascular, AVC, doença renal crônica e morte prematura.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (118, 33, 1, 'Mecanismos relevantes na população negra incluem maior sensibilidade ao sódio, menor atividade de renina plasmática em parte dos indivíduos, maior rigidez arterial e maior prevalência de hipertrofia ventricular esquerda e de nefropatia — combinados a variantes genéticas (ex.: APOL1) que aceleram a perda de função renal. Esses fatores explicam por que a HAS na população negra tende a ser mais precoce, mais grave e mais resistente ao tratamento.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (119, 33, 2, 'O conceito de "weathering" (desgaste alostático) descreve como a exposição crônica ao estresse do racismo estrutural se traduz em carga cardiovascular cumulativa — um determinante social com efeito biológico mensurável.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (34, 7, 1, 'Por que importa — epidemiologia e recorte racial');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (120, 34, 0, 'Pessoas negras apresentam prevalência de HAS significativamente maior e iniciam a doença em idades mais jovens que a população branca, com pior controle pressórico mesmo em tratamento farmacológico equivalente — padrão atribuído à combinação de biologia, acesso desigual e viés institucional no manejo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (121, 34, 1, 'No Distrito Federal, a mortalidade cardiovascular padronizada por idade é cerca de 50% maior em negros (180/100.000) do que em brancos (120/100.000) — razão 1,50. A hipertensão é o principal fator de risco modificável dessa disparidade.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (35, 7, 2, 'Diagnóstico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (122, 35, 0, 'Diagnóstico de consultório: PA ≥ 140/90 mmHg em pelo menos duas ocasiões distintas. Valores ≥ 180/120 mmHg exigem reavaliação imediata e investigação de lesão aguda de órgão-alvo. Para confirmação e diagnóstico de hipertensão do avental branco e mascarada, utilizar MRPA (Monitorização Residencial da PA) ou MAPA (Monitorização Ambulatorial da PA).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (123, 35, 1, 'A investigação inicial deve incluir avaliação de risco cardiovascular global, pesquisa de lesão de órgão-alvo (eletrocardiograma/ecocardiograma, creatinina e taxa de filtração glomerular, relação albumina/creatinina urinária, fundoscopia) e rastreio de causas secundárias quando indicado (por exemplo, em hipertensão resistente ou de início precoce).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (124, 35, 2, 'Na população negra, a avaliação de função renal deve ocorrer precocemente e ser repetida com frequência, dada a maior prevalência de nefropatia hipertensiva e a contribuição de variantes do gene APOL1.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (36, 7, 3, 'Tratamento e condutas');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (125, 36, 0, 'As diretrizes brasileiras (SBC) recomendam iniciar a terapia anti-hipertensiva com combinação de duas classes em baixa dose na maioria dos pacientes, com meta pressórica individualizada (usualmente < 130/80 mmHg quando tolerada).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (126, 36, 1, 'Na população negra, o perfil de resposta favorece esquemas com bloqueador de canal de cálcio (BCC) e/ou diurético tiazídico; IECA/BRA são particularmente importantes quando há nefropatia, albuminúria ou diabetes associados. A escolha deve considerar comorbidades e não a raça isoladamente, evitando tanto o subtratamento quanto a estereotipagem.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (127, 36, 2, 'Medidas não farmacológicas (redução de sódio, padrão alimentar tipo DASH adaptado à cultura alimentar local, atividade física, redução de álcool, manejo do estresse) potencializam o controle e reduzem a carga medicamentosa.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (128, 36, 3, 'Ponto crítico de equidade: há evidência de que pacientes negros recebem intensificação terapêutica menos agressiva e têm menor probabilidade de atingir a meta pressórica. O racismo institucional — e não a "não adesão" presumida — deve ser considerado ativamente na explicação do controle inadequado.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (37, 7, 4, 'Quando referenciar / sinais de alarme clínico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (129, 37, 0, 'Emergência hipertensiva (PA muito elevada com lesão aguda de órgão-alvo: encefalopatia, AVC, edema agudo de pulmão, síndrome coronariana aguda, dissecção de aorta, insuficiência renal aguda) exige redução pressórica controlada em ambiente hospitalar — não redução abrupta.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (130, 37, 1, 'Hipertensão resistente (PA acima da meta apesar de três fármacos, incluindo um diurético) deve motivar investigação de causas secundárias (apneia do sono, hiperaldosteronismo primário, doença renal parenquimatosa, estenose de artéria renal) e encaminhamento a especialista.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (131, 37, 2, 'Hipertensão de início precoce, hipocalemia espontânea, sopro abdominal ou deterioração rápida da função renal pedem investigação dirigida e referência.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (38, 7, 5, 'Fontes e diretrizes');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (132, 38, 0, 'Diretrizes Brasileiras de Hipertensão Arterial — Sociedade Brasileira de Cardiologia (SBC).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (133, 38, 1, 'Protocolo Clínico e Diretrizes Terapêuticas (PCDT) de Hipertensão Arterial Sistêmica — Ministério da Saúde.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (134, 38, 2, 'Estudo Técnico-Científico "Condições de Vida e Saúde da População Negra do DF (2015–2024)" — AECID/APRECIA/FIOCRUZ/UnB/FEPECS.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (135, 38, 3, 'Literatura internacional (NEJM, Lancet, AHA/ACC) sobre disparidades raciais em hipertensão e mortalidade cardiovascular.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (8, 'hipertensao', 'pt', 'enfermeiro', 'Medição correta da pressão, triagem de risco, orientação de autocuidado e cuidado continuado de pessoas com hipertensão na Atenção Básica e na urgência.', 'https://sspark.genspark.ai/i/DYbur7l9KsuZidYX?width=2560', 'Medição da pressão arterial com esfigmomanômetro e manguito no braço de uma pessoa', 'Imagem placeholder (CC/PD) — substituir por material próprio se necessário', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (39, 8, 0, 'O que é');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (136, 39, 0, 'A hipertensão é uma doença crônica em que a pressão do sangue nas artérias fica alta de forma persistente. Ela costuma não dar sintomas — por isso é chamada de "assassina silenciosa" — mas, sem controle, sobrecarrega o coração, o cérebro e os rins.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (137, 39, 1, 'É uma das condições mais frequentes na Atenção Básica e uma das que mais se beneficiam de acompanhamento contínuo e de uma boa relação de confiança entre equipe e usuário.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (40, 8, 1, 'Sinais que a equipe deve reconhecer');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (138, 40, 0, 'A maioria das pessoas hipertensas é assintomática — não espere sintomas para medir a pressão. Cefaleia, tontura, visão turva e dor no peito podem aparecer, mas não são confiáveis para diagnóstico.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (139, 40, 1, 'Sinais de alarme que exigem avaliação médica imediata: dor no peito, falta de ar, déficit súbito de força ou fala, visão turva intensa e súbita, confusão — podem indicar emergência hipertensiva (AVC, infarto, edema agudo de pulmão).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (140, 40, 2, 'Pressão muito elevada (por exemplo, ≥ 180/120 mmHg) sem sintomas é "urgência hipertensiva": reavalie após repouso, confirme com medida repetida e acione a equipe médica conforme protocolo.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (41, 8, 2, 'Medição correta da pressão — passo a passo na unidade');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (141, 41, 0, 'A técnica correta muda o resultado: pessoa sentada, costas apoiadas, pés no chão, braço apoiado na altura do coração, sem falar durante a medida, bexiga vazia e sem café/cigarro nos 30 minutos anteriores.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (142, 41, 1, 'Use manguito de tamanho adequado à circunferência do braço — manguito pequeno superestima a pressão. Faça ao menos duas medidas com intervalo de 1 minuto e registre a média.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (143, 41, 2, 'Registre os valores no prontuário e no cartão do usuário a cada visita — o histórico é o que revela a tendência real, que uma única medida isolada não mostra.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (42, 8, 3, 'Quem fica atento — grupos de risco e acompanhamento');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (144, 42, 0, 'Priorize acompanhamento de pessoas negras, que têm maior risco de hipertensão precoce e mais grave, além de maior chance de doença renal associada — a avaliação de função renal deve ser frequente.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (145, 42, 1, 'Grupos que exigem atenção redobrada: pessoas com diabetes, doença renal, obesidade, histórico familiar de hipertensão ou de AVC precoce, gestantes (risco de pré-eclâmpsia) e idosos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (146, 42, 2, 'Gestantes negras merecem vigilância reforçada de pressão e sinais de pré-eclâmpsia — a mortalidade materna por causas hipertensivas é desproporcionalmente maior entre mulheres negras.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (43, 8, 4, 'Cuidado continuado e orientação ao paciente/família');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (147, 43, 0, 'Explique, em linguagem simples, que hipertensão não tem cura, mas tem controle — e que o tratamento é para a vida toda, mesmo quando a pessoa se sente bem.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (148, 43, 1, 'Oriente sobre uso correto e contínuo dos medicamentos, redução de sal, atividade física regular e retorno às consultas. A adesão depende muito do vínculo e do acolhimento da equipe.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (149, 43, 2, 'Chamada anti-racista: quando a pressão de uma pessoa negra não controla, não presuma "falta de adesão" — verifique acesso ao medicamento, dificuldades de transporte, efeitos adversos e se o esquema terapêutico foi de fato intensificado. Historicamente, pacientes negros são tratados com menos intensidade e têm menos chance de atingir a meta — é um viés a ser combatido ativamente na prática clínica.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (9, 'hipertensao', 'pt', 'usuario', 'O que é hipertensão, por que ela é tão importante para a população negra, sinais de alerta, cuidados do dia a dia e onde buscar ajuda no SUS.', 'https://sspark.genspark.ai/i/DYbur7l9KsuZidYX?width=2560', 'Medição da pressão arterial com esfigmomanômetro e manguito no braço de uma pessoa', 'Imagem placeholder (CC/PD) — substituir por material próprio se necessário', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (44, 9, 0, 'O que é');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (150, 44, 0, 'A hipertensão (pressão alta) é uma doença em que a pressão do sangue dentro das artérias fica alta quase o tempo todo. Ela é muito comum e quase sempre não dá sintomas — a pessoa pode se sentir bem e ainda assim ter pressão alta.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (151, 44, 1, 'Por isso é chamada de "assassina silenciosa": sem tratamento, ela vai, aos poucos, sobrecarregando o coração, o cérebro e os rins, e pode levar a infarto, AVC e doença renal.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (45, 9, 1, 'Por que isso importa');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (152, 45, 0, 'A população negra tem mais chance de ter pressão alta, costuma começar mais cedo e, muitas vezes, a pressão é mais difícil de controlar. No Distrito Federal, a morte por doenças do coração é cerca de 50% maior entre pessoas negras.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (153, 45, 1, 'A boa notícia: hipertensão tem controle. Com diagnóstico precoce, acompanhamento regular e uso correto dos remédios, dá para viver bem e reduzir muito o risco de complicações.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (46, 9, 2, 'Sinais de alerta — fique atento(a)');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (154, 46, 0, 'Procure atendimento imediatamente se tiver: dor no peito, falta de ar, dor de cabeça muito forte e súbita, fraqueza ou dificuldade para falar de um lado do corpo, visão turva de repente. Esses sinais podem indicar AVC ou infarto.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (155, 46, 1, 'Não espere sentir sintomas para medir a pressão: aproveite qualquer visita à Unidade Básica de Saúde (UBS) para verificar. Pressão alta sem sintoma continua machucando o corpo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (156, 46, 2, 'Se a pressão estiver muito alta e você estiver com sintomas, vá à UPA ou pronto-socorro no mesmo dia.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (47, 9, 3, 'Cuidados do dia a dia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (157, 47, 0, 'Tome os remédios todos os dias, no horário certo, mesmo quando estiver se sentindo bem — a pressão só fica controlada com uso contínuo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (158, 47, 1, 'Reduza o sal e os alimentos industrializados (embutidos, salgadinhos, temperos prontos); prefira comida fresca, feita em casa, e use temperos naturais como alho, cebola e ervas.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (159, 47, 2, 'Mexa-se: caminhar, dançar, subir escadas. Qualquer atividade física regular ajuda a baixar a pressão.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (160, 47, 3, 'Evite excesso de bebida alcoólica e não fume. Se tiver dificuldade para parar de fumar, peça apoio na UBS — o SUS oferece tratamento.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (161, 47, 4, 'Leve seu cartão de acompanhamento e o resultado das medidas em cada consulta; se um remédio não estiver disponível na farmácia, avise a equipe para buscar alternativa.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (48, 9, 4, 'Onde buscar ajuda no SUS');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (162, 48, 0, 'A Unidade Básica de Saúde (UBS) é o lugar certo para medir a pressão, receber os remédios e acompanhar seu tratamento. O remédio para hipertensão é gratuito no SUS.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (163, 48, 1, 'Se estiver com sintomas graves (dor no peito, falta de ar, sinais de AVC), procure a UPA ou o pronto-socorro imediatamente ou ligue 192 (SAMU).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (164, 48, 2, 'Use a página "Rede SUS" desta plataforma para encontrar as unidades de saúde mais próximas de você no Distrito Federal.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (9, 'hipertensao', 'pt', 0, 'Sociedade Brasileira de Cardiologia (SBC)', 'Diretrizes Brasileiras de Hipertensão Arterial — referência nacional para diagnóstico e tratamento.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (10, 'hipertensao', 'pt', 1, 'Ministério da Saúde — PCDT Hipertensão Arterial', 'Protocolo Clínico e Diretrizes Terapêuticas vigente, referência normativa para a conduta no SUS.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (11, 'hipertensao', 'pt', 2, 'Estudo Pop. Negra DF 2015–2024', 'AECID/APRECIA/FIOCRUZ/UnB/FEPECS — Indicador 13 (mortalidade cardiovascular, razão negra/branca 1,50).');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (12, 'hipertensao', 'pt', 3, 'NEJM / AHA / Lancet', 'Literatura internacional sobre disparidades raciais em prevalência, controle e desfechos da hipertensão.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (10, 'hipertensao', 'es', 'medico', 'Fisiopatología, estratificación de riesgo, metas de presión, fundamento terapéutico y evidencia sobre las disparidades raciales en el control de la hipertensión arterial sistémica (HAS).', 'https://sspark.genspark.ai/i/DYbur7l9KsuZidYX?width=2560', 'Medición de la presión arterial con esfigmomanómetro y brazalete en el brazo de una persona', 'Imagen de relleno (CC/PD) — sustituir por material propio si es necesario', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (49, 10, 0, 'Qué es — fisiopatología');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (165, 49, 0, 'La hipertensión arterial sistémica (HAS) es una condición crónica multifactorial caracterizada por la elevación sostenida de la presión arterial (PA), resultante de la interacción entre determinantes genéticos, neurohormonales (sistema renina-angiotensina-aldosterona, sistema nervioso simpático), metabólicos y ambientales. No es solo un "número elevado": es el principal factor de riesgo modificable de enfermedad cardiovascular, ictus, enfermedad renal crónica y muerte prematura.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (166, 49, 1, 'Los mecanismos relevantes en la población negra incluyen mayor sensibilidad al sodio, menor actividad de renina plasmática en parte de los individuos, mayor rigidez arterial y mayor prevalencia de hipertrofia ventricular izquierda y de nefropatía — combinados con variantes genéticas (p. ej., APOL1) que aceleran la pérdida de función renal. Estos factores explican por qué la HAS en la población negra tiende a ser más precoz, más grave y más resistente al tratamiento.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (167, 49, 2, 'El concepto de "weathering" (desgaste alostático) describe cómo la exposición crónica al estrés del racismo estructural se traduce en una carga cardiovascular acumulativa — un determinante social con efecto biológico mensurable.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (50, 10, 1, 'Por qué importa — epidemiología y enfoque racial');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (168, 50, 0, 'Las personas negras presentan una prevalencia de HAS significativamente mayor e inician la enfermedad a edades más tempranas que la población blanca, con peor control de la presión incluso con tratamiento farmacológico equivalente — patrón atribuido a la combinación de biología, acceso desigual y sesgo institucional en el manejo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (169, 50, 1, 'En el Distrito Federal (Brasil), la mortalidad cardiovascular estandarizada por edad es cerca de un 50% mayor en negros (180/100.000) que en blancos (120/100.000) — razón 1,50. La hipertensión es el principal factor de riesgo modificable de esa disparidad.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (51, 10, 2, 'Diagnóstico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (170, 51, 0, 'Diagnóstico en consulta: PA ≥ 140/90 mmHg en al menos dos ocasiones distintas. Los valores ≥ 180/120 mmHg exigen reevaluación inmediata e investigación de lesión aguda de órgano diana. Para confirmación y diagnóstico de hipertensión de bata blanca y enmascarada, utilizar MRPA (Monitorización Residencial de la PA) o MAPA (Monitorización Ambulatoria de la PA).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (171, 51, 1, 'La investigación inicial debe incluir evaluación del riesgo cardiovascular global, búsqueda de lesión de órgano diana (electrocardiograma/ecocardiograma, creatinina y tasa de filtración glomerular, relación albúmina/creatinina urinaria, fondo de ojo) y cribado de causas secundarias cuando esté indicado (por ejemplo, en hipertensión resistente o de inicio precoz).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (172, 51, 2, 'En la población negra, la evaluación de la función renal debe realizarse de forma precoz y repetirse con frecuencia, dada la mayor prevalencia de nefropatía hipertensiva y la contribución de variantes del gen APOL1.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (52, 10, 3, 'Tratamiento y conductas');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (173, 52, 0, 'Las directrices brasileñas (SBC) recomiendan iniciar la terapia antihipertensiva con combinación de dos clases en dosis baja en la mayoría de los pacientes, con meta de presión individualizada (habitualmente < 130/80 mmHg cuando se tolera).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (174, 52, 1, 'En la población negra, el perfil de respuesta favorece esquemas con bloqueador de canales de calcio (BCC) y/o diurético tiazídico; los IECA/BRA son particularmente importantes cuando hay nefropatía, albuminuria o diabetes asociadas. La elección debe considerar las comorbilidades y no la raza de forma aislada, evitando tanto el subtratamiento como la estereotipación.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (175, 52, 2, 'Las medidas no farmacológicas (reducción de sodio, patrón alimentario tipo DASH adaptado a la cultura alimentaria local, actividad física, reducción de alcohol, manejo del estrés) potencian el control y reducen la carga farmacológica.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (176, 52, 3, 'Punto crítico de equidad: existe evidencia de que los pacientes negros reciben una intensificación terapéutica menos agresiva y tienen menor probabilidad de alcanzar la meta de presión. El racismo institucional — y no la "no adherencia" presunta — debe considerarse activamente al explicar el control inadecuado.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (53, 10, 4, 'Cuándo referir / signos de alarma clínica');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (177, 53, 0, 'La emergencia hipertensiva (PA muy elevada con lesión aguda de órgano diana: encefalopatía, ictus, edema agudo de pulmón, síndrome coronario agudo, disección de aorta, insuficiencia renal aguda) exige reducción de la presión controlada en ambiente hospitalario — no reducción abrupta.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (178, 53, 1, 'La hipertensión resistente (PA por encima de la meta a pesar de tres fármacos, incluido un diurético) debe motivar la investigación de causas secundarias (apnea del sueño, hiperaldosteronismo primario, enfermedad renal parenquimatosa, estenosis de arteria renal) y la derivación a especialista.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (179, 53, 2, 'La hipertensión de inicio precoz, la hipopotasemia espontánea, el soplo abdominal o el deterioro rápido de la función renal requieren investigación dirigida y referencia.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (54, 10, 5, 'Fuentes y directrices');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (180, 54, 0, 'Directrices Brasileñas de Hipertensión Arterial — Sociedad Brasileña de Cardiología (SBC).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (181, 54, 1, 'Protocolo Clínico y Directrices Terapéuticas (PCDT) de Hipertensión Arterial Sistémica — Ministerio de Salud de Brasil.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (182, 54, 2, 'Estudio Técnico-Científico "Condiciones de Vida y Salud de la Población Negra del DF (2015–2024)" — AECID/APRECIA/FIOCRUZ/UnB/FEPECS.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (183, 54, 3, 'Literatura internacional (NEJM, Lancet, AHA/ACC) sobre disparidades raciales en hipertensión y mortalidad cardiovascular.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (11, 'hipertensao', 'es', 'enfermeiro', 'Medición correcta de la presión, cribado de riesgo, orientación de autocuidado y cuidado continuo de personas con hipertensión en la Atención Primaria y en urgencias.', 'https://sspark.genspark.ai/i/DYbur7l9KsuZidYX?width=2560', 'Medición de la presión arterial con esfigmomanómetro y brazalete en el brazo de una persona', 'Imagen de relleno (CC/PD) — sustituir por material propio si es necesario', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (55, 11, 0, 'Qué es');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (184, 55, 0, 'La hipertensión es una enfermedad crónica en la que la presión de la sangre en las arterias se mantiene alta de forma persistente. Suele no dar síntomas — por eso se la llama "asesina silenciosa" — pero, sin control, sobrecarga el corazón, el cerebro y los riñones.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (185, 55, 1, 'Es una de las condiciones más frecuentes en la Atención Primaria y una de las que más se benefician del seguimiento continuo y de una buena relación de confianza entre el equipo y el usuario.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (56, 11, 1, 'Señales que el equipo debe reconocer');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (186, 56, 0, 'La mayoría de las personas hipertensas son asintomáticas — no espere síntomas para medir la presión. La cefalea, el mareo, la visión borrosa y el dolor en el pecho pueden aparecer, pero no son fiables para el diagnóstico.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (187, 56, 1, 'Signos de alarma que exigen evaluación médica inmediata: dolor en el pecho, falta de aire, déficit súbito de fuerza o del habla, visión borrosa intensa y súbita, confusión — pueden indicar emergencia hipertensiva (ictus, infarto, edema agudo de pulmón).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (188, 56, 2, 'Presión muy elevada (por ejemplo, ≥ 180/120 mmHg) sin síntomas es "urgencia hipertensiva": reevalúe tras reposo, confirme con una medición repetida y active al equipo médico según el protocolo.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (57, 11, 2, 'Medición correcta de la presión — paso a paso en la unidad');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (189, 57, 0, 'La técnica correcta cambia el resultado: persona sentada, espalda apoyada, pies en el suelo, brazo apoyado a la altura del corazón, sin hablar durante la medición, vejiga vacía y sin café/tabaco en los 30 minutos previos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (190, 57, 1, 'Use un brazalete del tamaño adecuado a la circunferencia del brazo — un brazalete pequeño sobreestima la presión. Realice al menos dos mediciones con un intervalo de 1 minuto y registre el promedio.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (191, 57, 2, 'Registre los valores en la historia clínica y en la tarjeta del usuario en cada visita — el historial es lo que revela la tendencia real, que una sola medición aislada no muestra.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (58, 11, 3, 'Quién debe estar atento — grupos de riesgo y seguimiento');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (192, 58, 0, 'Priorice el seguimiento de personas negras, que tienen mayor riesgo de hipertensión precoz y más grave, además de mayor probabilidad de enfermedad renal asociada — la evaluación de la función renal debe ser frecuente.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (193, 58, 1, 'Grupos que exigen especial atención: personas con diabetes, enfermedad renal, obesidad, antecedentes familiares de hipertensión o de ictus precoz, gestantes (riesgo de preeclampsia) y personas mayores.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (194, 58, 2, 'Las gestantes negras merecen una vigilancia reforzada de la presión y de los signos de preeclampsia — la mortalidad materna por causas hipertensivas es desproporcionadamente mayor entre las mujeres negras.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (59, 11, 4, 'Cuidado continuo y orientación al paciente/familia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (195, 59, 0, 'Explique, en lenguaje sencillo, que la hipertensión no tiene cura, pero sí control — y que el tratamiento es para toda la vida, incluso cuando la persona se siente bien.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (196, 59, 1, 'Oriente sobre el uso correcto y continuo de los medicamentos, la reducción de sal, la actividad física regular y el regreso a las consultas. La adherencia depende mucho del vínculo y de la acogida del equipo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (197, 59, 2, 'Llamado antirracista: cuando la presión de una persona negra no se controla, no presuma "falta de adherencia" — verifique el acceso al medicamento, las dificultades de transporte, los efectos adversos y si el esquema terapéutico se intensificó realmente. Históricamente, los pacientes negros son tratados con menos intensidad y tienen menos probabilidad de alcanzar la meta — es un sesgo que debe combatirse activamente en la práctica clínica.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (12, 'hipertensao', 'es', 'usuario', 'Qué es la hipertensión, por qué es tan importante para la población negra, señales de alerta, cuidados diarios y dónde buscar ayuda en el SUS.', 'https://sspark.genspark.ai/i/DYbur7l9KsuZidYX?width=2560', 'Medición de la presión arterial con esfigmomanómetro y brazalete en el brazo de una persona', 'Imagen de relleno (CC/PD) — sustituir por material propio si es necesario', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (60, 12, 0, 'Qué es');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (198, 60, 0, 'La hipertensión (presión alta) es una enfermedad en la que la presión de la sangre dentro de las arterias se mantiene alta casi todo el tiempo. Es muy común y casi nunca da síntomas — la persona puede sentirse bien y aun así tener la presión alta.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (199, 60, 1, 'Por eso se la llama "asesina silenciosa": sin tratamiento, va sobrecargando poco a poco el corazón, el cerebro y los riñones, y puede provocar infarto, ictus y enfermedad renal.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (61, 12, 1, 'Por qué esto importa');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (200, 61, 0, 'La población negra tiene más probabilidad de tener presión alta, suele comenzar más temprano y, muchas veces, la presión es más difícil de controlar. En el Distrito Federal, la muerte por enfermedades del corazón es cerca de un 50% mayor entre las personas negras.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (201, 61, 1, 'La buena noticia: la hipertensión se controla. Con diagnóstico precoz, seguimiento regular y uso correcto de los medicamentos, es posible vivir bien y reducir mucho el riesgo de complicaciones.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (62, 12, 2, 'Señales de alerta — esté atento(a)');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (202, 62, 0, 'Busque atención de inmediato si tiene: dolor en el pecho, falta de aire, dolor de cabeza muy fuerte y súbito, debilidad o dificultad para hablar de un lado del cuerpo, visión borrosa repentina. Estas señales pueden indicar ictus o infarto.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (203, 62, 1, 'No espere sentir síntomas para medir la presión: aproveche cualquier visita a la Unidad Básica de Salud (UBS) para verificarla. La presión alta sin síntomas sigue dañando el cuerpo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (204, 62, 2, 'Si la presión está muy alta y usted tiene síntomas, acuda a la UPA o al servicio de urgencias el mismo día.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (63, 12, 3, 'Cuidados del día a día');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (205, 63, 0, 'Tome los medicamentos todos los días, a la hora correcta, incluso cuando se sienta bien — la presión solo se mantiene controlada con el uso continuo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (206, 63, 1, 'Reduzca la sal y los alimentos industrializados (embutidos, snacks, condimentos listos); prefiera la comida fresca, hecha en casa, y use condimentos naturales como ajo, cebolla y hierbas.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (207, 63, 2, 'Muévase: caminar, bailar, subir escaleras. Cualquier actividad física regular ayuda a bajar la presión.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (208, 63, 3, 'Evite el exceso de alcohol y no fume. Si le cuesta dejar de fumar, pida apoyo en la UBS — el SUS ofrece tratamiento.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (209, 63, 4, 'Lleve su tarjeta de seguimiento y el resultado de las mediciones a cada consulta; si un medicamento no está disponible en la farmacia, avise al equipo para buscar una alternativa.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (64, 12, 4, 'Dónde buscar ayuda en el SUS');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (210, 64, 0, 'La Unidad Básica de Salud (UBS) es el lugar correcto para medir la presión, recibir los medicamentos y seguir su tratamiento. El medicamento para la hipertensión es gratuito en el SUS.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (211, 64, 1, 'Si tiene síntomas graves (dolor en el pecho, falta de aire, señales de ictus), acuda a la UPA o al servicio de urgencias de inmediato o llame al 192 (SAMU).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (212, 64, 2, 'Use la página "Red SUS" de esta plataforma para encontrar las unidades de salud más cercanas a usted en el Distrito Federal.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (13, 'hipertensao', 'es', 0, 'Sociedad Brasileña de Cardiología (SBC)', 'Directrices Brasileñas de Hipertensión Arterial — referencia nacional para diagnóstico y tratamiento.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (14, 'hipertensao', 'es', 1, 'Ministerio de Salud de Brasil — PCDT Hipertensión Arterial', 'Protocolo Clínico y Directrices Terapéuticas vigente, referencia normativa para la conducta en el SUS.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (15, 'hipertensao', 'es', 2, 'Estudio Población Negra DF 2015–2024', 'AECID/APRECIA/FIOCRUZ/UnB/FEPECS — Indicador 13 (mortalidad cardiovascular, razón negra/blanca 1,50).');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (16, 'hipertensao', 'es', 3, 'NEJM / AHA / Lancet', 'Literatura internacional sobre disparidades raciales en prevalencia, control y desenlaces de la hipertensión.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (13, 'diabetes', 'pt', 'medico', 'Fisiopatologia do diabetes tipo 1 e tipo 2, critérios diagnósticos, racional terapêutico e evidência sobre disparidades raciais em prevalência, complicações e controle glicêmico.', 'https://sspark.genspark.ai/i/fhNaPFo6WtBOQSHf?width=2560', 'Pessoa medindo a glicemia capilar com glicosímetro e fita reagente no dedo', 'Imagem placeholder (CC/PD) — substituir por material próprio se necessário', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (65, 13, 0, 'O que é — fisiopatologia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (213, 65, 0, 'O diabetes mellitus é um grupo de doenças metabólicas caracterizado por hiperglicemia crônica decorrente de defeitos na secreção de insulina, na ação da insulina ou em ambas. O diabetes tipo 1 (DM1) resulta de destruição autoimune das células beta pancreáticas, levando à deficiência absoluta de insulina; o tipo 2 (DM2) resulta de resistência à insulina associada a progressiva falência secretória das células beta.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (214, 65, 1, 'Mecanismos relevantes na população negra incluem maior resistência à insulina, maior adiposidade visceral para o mesmo IMC, menor capacidade de compensação da célula beta, padrões alimentares influenciados por insegurança alimentar e ambiente obesogênico, além de determinantes sociais (estresse crônico, sono, acesso a alimentos frescos) que aceleram a progressão.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (215, 65, 2, 'Complicações microvasculares (retinopatia, nefropatia, neuropatia) e macrovasculares (infarto, AVC, doença arterial periférica) são o que confere gravidade à doença — e o controle glicêmico precoce e sustentado é o principal modulador de risco. A coexistência com hipertensão e doença renal (frequentemente associada a variantes do gene APOL1) agrava o prognóstico.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (66, 13, 1, 'Por que importa — epidemiologia e recorte racial');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (216, 66, 0, 'A prevalência do diabetes tipo 2 é substancialmente maior em pessoas negras, que também apresentam diagnóstico mais precoce, pior controle glicêmico e maior taxa de complicações (nefropatia terminal, amputações e cegueira por retinopatia) em comparação à população branca, mesmo com acesso equivalente ao cuidado.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (217, 66, 1, 'Essas disparidades refletem a combinação de biologia, determinantes sociais e viés institucional no manejo. O racismo estrutural atua como expositor crônico (allostatic load), e o subdiagnóstico/triagem tardia amplia o tempo de exposição à hiperglicemia.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (218, 66, 2, 'No Distrito Federal, o diabetes caiu do 3º lugar (2014) para o 8º lugar (2024) entre as causas de morte — o que pode indicar melhora no controle (acesso a insulina e antidiabéticos pelo SUS) ou subnotificação como causa associada. O dado ainda não está estratificado por raça/cor no boletim agregado, o que limita a leitura de equidade e deve orientar a priorização da estratificação racial nos registros.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (67, 13, 2, 'Diagnóstico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (219, 67, 0, 'Critérios diagnósticos (Ministério da Saúde / SBD / ADA): glicemia de jejum ≥ 126 mg/dL; glicemia de 2h no teste oral de tolerância à glicose ≥ 200 mg/dL; hemoglobina glicada (HbA1c) ≥ 6,5%; ou glicemia ao acaso ≥ 200 mg/dL com sintomas clássicos (poliúria, polidipsia, perda de peso). Na ausência de hiperglicemia inequívoca, confirmar com segunda dosagem.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (220, 67, 1, 'Pré-diabetes (glicemia de jejum 100–125 mg/dL, TOTG 140–199 mg/dL ou HbA1c 5,7–6,4%) deve motivar intervenção em estilo de vida e seguimento — é a janela de maior potencial preventivo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (221, 67, 2, 'DM1 deve ser suspeitado em quadro de hiperglicemia com cetose, início agudo, em crianças/adolescentes ou adultos jovens, e confirmado com autoanticorpos (anti-GAD, anti-IA2, anti-ZnT8, anti-insulina) e peptídeo C quando disponível. O rastreio de DM2 deve ser mais precoce e repetido com maior frequência na população negra e em grupos com sobrepeso/obesidade, histórico familiar e hipertensão.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (68, 13, 3, 'Tratamento e condutas');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (222, 68, 0, 'Metas individualizadas de HbA1c (usualmente < 7% para a maioria dos adultos, mais flexíveis em idosos/frágeis e mais estritas em jovens sem comorbidade). O manejo combina mudança de estilo de vida, terapia farmacológica escalonada e controle rigoroso de pressão arterial e lipídios.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (223, 68, 1, 'No DM2, a escolha do antidiabético deve ser guiada por comorbidades: iSGLT2 e agonistas de GLP-1 têm benefício cardio-renal comprovado (especialmente relevantes diante do maior risco de nefropatia na população negra); metformina permanece primeira linha na maioria dos casos. A insulina é indicada conforme a falência progressiva da célula beta.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (224, 68, 2, 'No DM1, a terapia é insulina em esquema basal-bolus (ou bomba) com monitorização glicêmica; o acesso a análogos de insulina, monitores de glicose (CGM) e sistemas de infusão é direito e impacta diretamente o desfecho — barreiras de acesso a essa tecnologia aprofundam a disparidade racial.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (225, 68, 3, 'Ponto crítico de equidade: não atribuir controle inadequado à "não adesão" presumida sem investigar acesso a medicamentos, insumos de monitorização, insegurança alimentar, transporte e carga psicossocial. Esses fatores são frequentes e modificáveis, e a falha em reconhecê-los reproduz racismo institucional na prática clínica.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (69, 13, 4, 'Quando referenciar / sinais de alarme clínico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (226, 69, 0, 'Emergências metabólicas — cetoacidose diabética (DM1/DM2) e estado hiperglicêmico hiperosmolar (DM2) — exigem atendimento hospitalar imediato com hidratação, insulina e correção de distúrbios eletrolíticos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (227, 69, 1, 'Hipoglicemia grave (rebaixamento de consciência, convulsão) é emergência; revisar esquema, técnica de aplicação e acesso a monitorização.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (228, 69, 2, 'Encaminhar a especialista conforme necessidade: oftalmologia (rastreio anual de retinopatia), nefrologia (TFG reduzida/albuminúria), cardiologia (doença cardiovascular), vascular (pé diabético/doença arterial periférica), endocrinologia (controle complexo ou DM1), nutrição e equipe multiprofissional. Úlceras, infecções e deformidades nos pés exigem avaliação vascular e de enfermagem especializada.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (70, 13, 5, 'Fontes e diretrizes');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (229, 70, 0, 'Diretrizes da Sociedade Brasileira de Diabetes (SBD) — referência nacional para diagnóstico e tratamento.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (230, 70, 1, 'Protocolo Clínico e Diretrizes Terapêuticas (PCDT) de Diabetes Mellitus — Ministério da Saúde.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (231, 70, 2, 'American Diabetes Association (ADA) — Standards of Care, referência internacional baseada em evidência.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (232, 70, 3, 'Estudo Técnico-Científico "Condições de Vida e Saúde da População Negra do DF (2015–2024)" — AECID/APRECIA/FIOCRUZ/UnB/FEPECS.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (14, 'diabetes', 'pt', 'enfermeiro', 'Triagem e rastreio, orientação de autocuidado, prevenção do pé diabético e cuidado continuado de pessoas com diabetes na Atenção Básica e na urgência.', 'https://sspark.genspark.ai/i/fhNaPFo6WtBOQSHf?width=2560', 'Pessoa medindo a glicemia capilar com glicosímetro e fita reagente no dedo', 'Imagem placeholder (CC/PD) — substituir por material próprio se necessário', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (71, 14, 0, 'O que é');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (233, 71, 0, 'O diabetes é uma doença crônica em que o corpo não produz insulina suficiente ou não consegue usá-la bem, fazendo o açúcar (glicose) do sangue ficar alto. Sem controle, ao longo do tempo, o excesso de açúcar machuca vasos e nervos de todo o corpo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (234, 71, 1, 'É uma das condições mais frequentes na Atenção Básica e uma das que mais se beneficiam de acompanhamento contínuo, educação em saúde e vínculo de confiança entre equipe e usuário.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (72, 14, 1, 'Sinais que a equipe deve reconhecer');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (235, 72, 0, 'Sintomas clássicos de hiperglicemia: muita sede, urinar muito (inclusive à noite), perda de peso sem explicação, cansaço, visão embaçada, feridas que não cicatrizam e infecções de repetição (candidíase, pele, urina).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (236, 72, 1, 'Sinais de alarme que exigem avaliação médica imediata: respiração rápida e profunda, hálito com cheiro de fruta, vômitos, dor abdominal, sonolência/confusão e desidratação — podem indicar cetoacidose ou estado hiperosmolar.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (237, 72, 2, 'Sinais de hipoglicemia: suor frio, tremor, palidez, fome súbita, taquicardia, confusão e, em casos graves, perda de consciência — oriente o usuário a reconhecer e a agir (regra dos 15 g de carboidrato rápido).');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (73, 14, 2, 'Rastreio e acompanhamento na Atenção Básica');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (238, 73, 0, 'Priorize o rastreio de glicemia em pessoas negras, com sobrepeso/obesidade, hipertensão, histórico familiar de diabetes, história de diabetes gestacional e maiores de 35 anos — a população negra tende a desenvolver a doença mais cedo e com mais complicações.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (239, 73, 1, 'No acompanhamento, verifique a cada visita: glicemia de jejum/HbA1c conforme protocolo, pressão arterial, peso, perímetro abdominal, exame dos pés (inspeção, sensibilidade com monofilamento, pulsos) e revisão do uso correto dos medicamentos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (240, 73, 2, 'Garanta a organização do cuidado: busca ativa de faltosos, agendamento do rastreio de retinopatia (fundoscopia) e da avaliação de função renal (creatinina/TFG e relação albumina/creatinina), vacinação e articulação com a equipe multiprofissional (nutrição, psicologia, educação física, odontologia).');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (74, 14, 3, 'Quem fica atento — grupos de risco');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (241, 74, 0, 'Grupos que exigem atenção redobrada: pessoas negras, com sobrepeso/obesidade, hipertensão, dislipidemia, histórico familiar de diabetes, diabetes gestacional prévia, síndrome dos ovários policísticos, uso de medicamentos hiperglicemiantes (corticoide) e pessoas em insegurança alimentar.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (242, 74, 1, 'Gestantes: rastrear diabetes gestacional no pré-natal (TOTG entre 24 e 28 semanas, ou antes em alto risco) — o cuidado adequado reduz desfechos maternos e neonatais. Gestantes negras merecem vigilância reforçada, dado o maior risco de desfechos adversos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (243, 74, 2, 'Pessoas com diabetes e sinais de sofrimento psíquico: a depressão e o "burnout do diabetes" são comuns e prejudicam o autocuidado — acolha e articule com saúde mental.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (75, 14, 4, 'Cuidado continuado e orientação ao paciente/família');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (244, 75, 0, 'Explique, em linguagem simples, que o diabetes tem controle — mas não tem cura — e que o tratamento é contínuo, mesmo quando a pessoa se sente bem. Ensine o manejo básico: alimentação, atividade física, medicação e monitorização glicêmica.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (245, 75, 1, 'Oriente o cuidado com os pés (exame diário, hidratação, calçado adequado, nunca andar descalço), o reconhecimento de hipoglicemia e o que fazer em situações de risco. Reforce a importância de comparecer às consultas e de retirar os medicamentos regularmente na farmácia.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (246, 75, 2, 'Chamada anti-racista: quando o controle glicêmico de uma pessoa negra não melhora, não presuma "falta de adesão" — investigue acesso a medicamentos e insumos, insegurança alimentar, custo do transporte, efeitos adversos e carga psicossocial. Historicamente, pacientes negros têm o autocuidado julgado com mais rigor e recebem menos tecnologia (análogos de insulina, monitores). É um viés a ser combatido ativamente na prática clínica.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (15, 'diabetes', 'pt', 'usuario', 'O que é diabetes, por que é tão importante para a população negra, sinais de alerta, cuidados do dia a dia e onde buscar ajuda no SUS.', 'https://sspark.genspark.ai/i/fhNaPFo6WtBOQSHf?width=2560', 'Pessoa medindo a glicemia capilar com glicosímetro e fita reagente no dedo', 'Imagem placeholder (CC/PD) — substituir por material próprio se necessário', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (76, 15, 0, 'O que é');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (247, 76, 0, 'Diabetes é uma doença em que o açúcar do sangue (glicose) fica alto demais. Isso acontece porque o corpo não produz insulina suficiente ou não consegue usá-la direito. A insulina é o "porteiro" que coloca o açúcar para dentro das células e dá energia ao corpo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (248, 76, 1, 'Quando esse açúcar sobra no sangue por muito tempo, ele vai machucando, aos poucos, o coração, os olhos, os rins, os nervos e os pés. É uma doença crônica: a pessoa vive com ela, mas pode controlá-la muito bem.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (77, 15, 1, 'Por que isso importa');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (249, 77, 0, 'A população negra tem mais chance de ter diabetes tipo 2, costuma adoecer mais cedo e desenvolver mais complicações. Isso não é "sorte" nem culpa: tem a ver com genética, com alimentação, com o estresse do racismo no dia a dia e com acesso desigual a médico, remédio e exames.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (250, 77, 1, 'A boa notícia: dá para controlar. Com diagnóstico precoce, acompanhamento na UBS, alimentação adequada, atividade física e uso correto dos remédios, é possível viver bem e evitar as complicações mais graves.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (78, 15, 2, 'Sinais de alerta — fique atento(a)');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (251, 78, 0, 'Procure a UBS se você tiver: muita sede, vontade de urinar muito (inclusive à noite), perda de peso sem explicação, cansaço, visão embaçada ou feridas que demoram a cicatrizar. Esses podem ser sinais de diabetes.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (252, 78, 1, 'Vá imediatamente à UPA/pronto-socorro se houver: respiração rápida e profunda, hálito com cheiro de fruta, vômitos, dor na barriga, sonolência ou confusão. Isso pode ser uma emergência do diabetes.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (253, 78, 2, 'Aprenda a reconhecer a hipoglicemia (açúcar baixo): suor frio, tremor, palidez, fome de repente, tontura. Nesses casos, tome rápido um pouco de açúcar (um copo de suco, uma colher de mel) e avise alguém.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (79, 15, 3, 'Cuidados do dia a dia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (254, 79, 0, 'Tome os remédios (ou a insulina) todos os dias, no horário certo, mesmo se sentir bem. Nunca pare por conta própria — se algum remédio não estiver disponível na farmácia, avise a equipe da UBS.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (255, 79, 1, 'Cuide da alimentação: reduza açúcar, refrigerantes e ultraprocessados; prefira comida de verdade — feijão, arroz, verduras, legumes, frutas e carnes com pouca gordura. Não precisa ser perfeito: pequenas mudanças constantes já ajudam muito.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (256, 79, 2, 'Mexa-se: caminhar, dançar, subir escadas. Qualquer atividade regular ajuda a controlar o açúcar no sangue.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (257, 79, 3, 'Cuide dos pés todos os dias: observe feridas, bolhas ou vermelhidão, hidrate (sem passar entre os dedos) e use calçado fechado e confortável. Nunca ande descalço. Uma ferida no pé do diabético precisa de atenção rápida.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (258, 79, 4, 'Vá às consultas e faça os exames de rotina (glicemia, hemoglobina glicada, olhos e rins). O exame de fundo de olho e o de urina são importantes para pegar problemas cedo, antes de virarem graves.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (80, 15, 4, 'Onde buscar ajuda no SUS');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (259, 80, 0, 'A Unidade Básica de Saúde (UBS) é o lugar certo para acompanhar o diabetes, pegar os medicamentos (inclusive insulina) e receber orientação com a equipe. O tratamento do diabetes é gratuito no SUS.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (260, 80, 1, 'Se houver sinais graves (respiração alterada, vômitos, confusão, hipoglicemia grave), procure a UPA ou o pronto-socorro imediatamente ou ligue 192 (SAMU).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (261, 80, 2, 'Use a página "Rede SUS" desta plataforma para encontrar as unidades de saúde mais próximas de você no Distrito Federal. Grupos de apoio e educação em diabetes na UBS ajudam muito no autocuidado.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (17, 'diabetes', 'pt', 0, 'Sociedade Brasileira de Diabetes (SBD)', 'Diretrizes da SBD — referência nacional para diagnóstico e tratamento do diabetes.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (18, 'diabetes', 'pt', 1, 'Ministério da Saúde — PCDT Diabetes Mellitus', 'Protocolo Clínico e Diretrizes Terapêuticas vigente, referência normativa para a conduta no SUS.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (19, 'diabetes', 'pt', 2, 'Estudo Pop. Negra DF 2015–2024', 'AECID/APRECIA/FIOCRUZ/UnB/FEPECS — Indicador 14 (diabetes como causa de morte: 3º lugar em 2014 → 8º em 2024; estratificação racial pendente).');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (20, 'diabetes', 'pt', 3, 'American Diabetes Association (ADA)', 'Standards of Care in Diabetes — referência internacional baseada em evidência, usada de forma complementar.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (16, 'diabetes', 'es', 'medico', 'Fisiopatología de la diabetes tipo 1 y tipo 2, criterios diagnósticos, fundamento terapéutico y evidencia sobre disparidades raciales en prevalencia, complicaciones y control glucémico.', 'https://sspark.genspark.ai/i/fhNaPFo6WtBOQSHf?width=2560', 'Persona midiendo la glucemia capilar con glucómetro y tira reactiva en el dedo', 'Imagen de relleno (CC/PD) — sustituir por material propio si es necesario', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (81, 16, 0, 'Qué es — fisiopatología');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (262, 81, 0, 'La diabetes mellitus es un grupo de enfermedades metabólicas caracterizado por hiperglucemia crónica derivada de defectos en la secreción de insulina, en la acción de la insulina o en ambas. La diabetes tipo 1 (DM1) resulta de la destrucción autoinmune de las células beta pancreáticas, lo que lleva a la deficiencia absoluta de insulina; el tipo 2 (DM2) resulta de resistencia a la insulina asociada a una progresiva falla secretora de las células beta.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (263, 81, 1, 'Los mecanismos relevantes en la población negra incluyen mayor resistencia a la insulina, mayor adiposidad visceral para el mismo IMC, menor capacidad de compensación de la célula beta, patrones alimentarios influidos por la inseguridad alimentaria y un entorno obesogénico, además de determinantes sociales (estrés crónico, sueño, acceso a alimentos frescos) que aceleran la progresión.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (264, 81, 2, 'Las complicaciones microvasculares (retinopatía, nefropatía, neuropatía) y macrovasculares (infarto, ictus, enfermedad arterial periférica) son lo que confiere gravedad a la enfermedad — y el control glucémico precoz y sostenido es el principal modulador del riesgo. La coexistencia con hipertensión y enfermedad renal (frecuentemente asociada a variantes del gen APOL1) agrava el pronóstico.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (82, 16, 1, 'Por qué importa — epidemiología y enfoque racial');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (265, 82, 0, 'La prevalencia de la diabetes tipo 2 es sustancialmente mayor en personas negras, que también presentan diagnóstico más precoz, peor control glucémico y mayor tasa de complicaciones (nefropatía terminal, amputaciones y ceguera por retinopatía) en comparación con la población blanca, incluso con acceso equivalente al cuidado.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (266, 82, 1, 'Estas disparidades reflejan la combinación de biología, determinantes sociales y sesgo institucional en el manejo. El racismo estructural actúa como expositor crónico (carga alostática), y el subdiagnóstico/cribado tardío amplía el tiempo de exposición a la hiperglucemia.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (267, 82, 2, 'En el Distrito Federal, la diabetes pasó del 3.º lugar (2014) al 8.º lugar (2024) entre las causas de muerte — lo que puede indicar mejor control (acceso a insulina y antidiabéticos por el SUS) o subnotificación como causa asociada. El dato aún no está estratificado por raza/color en el boletín agregado, lo que limita la lectura de equidad y debe orientar la priorización de la estratificación racial en los registros.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (83, 16, 2, 'Diagnóstico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (268, 83, 0, 'Criterios diagnósticos (Ministerio de Salud / SBD / ADA): glucemia en ayunas ≥ 126 mg/dL; glucemia a las 2 h en la prueba oral de tolerancia a la glucosa ≥ 200 mg/dL; hemoglobina glucosilada (HbA1c) ≥ 6,5%; o glucemia al azar ≥ 200 mg/dL con síntomas clásicos (poliuria, polidipsia, pérdida de peso). En ausencia de hiperglucemia inequívoca, confirmar con una segunda medición.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (269, 83, 1, 'Prediabetes (glucemia en ayunas 100–125 mg/dL, PTOG 140–199 mg/dL o HbA1c 5,7–6,4%) debe motivar intervención en el estilo de vida y seguimiento — es la ventana de mayor potencial preventivo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (270, 83, 2, 'La DM1 debe sospecharse ante un cuadro de hiperglucemia con cetosis, inicio agudo, en niños/adolescentes o adultos jóvenes, y confirmarse con autoanticuerpos (anti-GAD, anti-IA2, anti-ZnT8, antiinsulina) y péptido C cuando esté disponible. El cribado de DM2 debe ser más precoz y repetirse con mayor frecuencia en la población negra y en grupos con sobrepeso/obesidad, antecedente familiar e hipertensión.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (84, 16, 3, 'Tratamiento y conductas');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (271, 84, 0, 'Metas individualizadas de HbA1c (habitualmente < 7% para la mayoría de los adultos, más flexibles en ancianos/frágiles y más estrictas en jóvenes sin comorbilidad). El manejo combina cambio de estilo de vida, terapia farmacológica escalonada y control riguroso de la presión arterial y los lípidos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (272, 84, 1, 'En la DM2, la elección del antidiabético debe guiarse por las comorbilidades: iSGLT2 y agonistas de GLP-1 tienen beneficio cardiorrenal comprobado (especialmente relevantes ante el mayor riesgo de nefropatía en la población negra); la metformina sigue siendo primera línea en la mayoría de los casos. La insulina está indicada conforme a la falla progresiva de la célula beta.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (273, 84, 2, 'En la DM1, la terapia es insulina en esquema basal-bolus (o bomba) con monitorización glucémica; el acceso a análogos de insulina, monitores de glucosa (CGM) y sistemas de infusión es un derecho e impacta directamente el desenlace — las barreras de acceso a esa tecnología profundizan la disparidad racial.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (274, 84, 3, 'Punto crítico de equidad: no atribuir el control inadecuado a la "falta de adherencia" presunta sin investigar el acceso a medicamentos, los insumos de monitorización, la inseguridad alimentaria, el transporte y la carga psicosocial. Estos factores son frecuentes y modificables, y la falla en reconocerlos reproduce racismo institucional en la práctica clínica.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (85, 16, 4, 'Cuándo derivar / señales de alarma clínica');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (275, 85, 0, 'Urgencias metabólicas — cetoacidosis diabética (DM1/DM2) y estado hiperglucémico hiperosmolar (DM2) — exigen atención hospitalaria inmediata con hidratación, insulina y corrección de los trastornos electrolíticos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (276, 85, 1, 'La hipoglucemia grave (deterioro de la conciencia, convulsión) es una urgencia; revisar el esquema, la técnica de aplicación y el acceso a la monitorización.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (277, 85, 2, 'Derivar a especialista según necesidad: oftalmología (cribado anual de retinopatía), nefrología (TFG reducida/albuminuria), cardiología (enfermedad cardiovascular), vascular (pie diabético/enfermedad arterial periférica), endocrinología (control complejo o DM1), nutrición y equipo multiprofesional. Las úlceras, infecciones y deformidades en los pies exigen evaluación vascular y de enfermería especializada.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (86, 16, 5, 'Fuentes y directrices');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (278, 86, 0, 'Directrices de la Sociedad Brasileña de Diabetes (SBD) — referencia nacional para diagnóstico y tratamiento.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (279, 86, 1, 'Protocolo Clínico y Directrices Terapéuticas (PCDT) de Diabetes Mellitus — Ministerio de Salud.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (280, 86, 2, 'American Diabetes Association (ADA) — Standards of Care, referencia internacional basada en evidencia.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (281, 86, 3, 'Estudio Técnico-Científico "Condiciones de Vida y Salud de la Población Negra del DF (2015–2024)" — AECID/APRECIA/FIOCRUZ/UnB/FEPECS.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (17, 'diabetes', 'es', 'enfermeiro', 'Cribado y seguimiento, orientación del autocuidado, prevención del pie diabético y cuidado continuo de personas con diabetes en la Atención Primaria y en urgencias.', 'https://sspark.genspark.ai/i/fhNaPFo6WtBOQSHf?width=2560', 'Persona midiendo la glucemia capilar con glucómetro y tira reactiva en el dedo', 'Imagen de relleno (CC/PD) — sustituir por material propio si es necesario', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (87, 17, 0, 'Qué es');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (282, 87, 0, 'La diabetes es una enfermedad crónica en la que el cuerpo no produce insulina suficiente o no logra usarla bien, haciendo que el azúcar (glucosa) de la sangre se mantenga alta. Sin control, con el tiempo, el exceso de azúcar daña los vasos y los nervios de todo el cuerpo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (283, 87, 1, 'Es una de las condiciones más frecuentes en la Atención Primaria y una de las que más se benefician del seguimiento continuo, de la educación en salud y del vínculo de confianza entre el equipo y el usuario.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (88, 17, 1, 'Señales que el equipo debe reconocer');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (284, 88, 0, 'Síntomas clásicos de hiperglucemia: mucha sed, orinar mucho (incluso de noche), pérdida de peso sin explicación, cansancio, visión borrosa, heridas que no cicatrizan e infecciones repetidas (candidiasis, piel, orina).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (285, 88, 1, 'Señales de alarma que exigen evaluación médica inmediata: respiración rápida y profunda, aliento con olor a fruta, vómitos, dolor abdominal, somnolencia/confusión y deshidratación — pueden indicar cetoacidosis o estado hiperosmolar.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (286, 88, 2, 'Señales de hipoglucemia: sudor frío, temblor, palidez, hambre súbita, taquicardia, confusión y, en casos graves, pérdida de conciencia — oriente al usuario a reconocerlas y actuar (regla de los 15 g de carbohidrato rápido).');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (89, 17, 2, 'Cribado y seguimiento en la Atención Primaria');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (287, 89, 0, 'Priorice el cribado de glucemia en personas negras, con sobrepeso/obesidad, hipertensión, antecedente familiar de diabetes, antecedente de diabetes gestacional y mayores de 35 años — la población negra tiende a desarrollar la enfermedad más temprano y con más complicaciones.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (288, 89, 1, 'En el seguimiento, verifique en cada visita: glucemia en ayunas/HbA1c según protocolo, presión arterial, peso, perímetro abdominal, examen de los pies (inspección, sensibilidad con monofilamento, pulsos) y revisión del uso correcto de los medicamentos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (289, 89, 2, 'Garantice la organización del cuidado: búsqueda activa de ausentes, programación del cribado de retinopatía (fondo de ojo) y de la evaluación de la función renal (creatinina/TFG y relación albúmina/creatinina), vacunación y articulación con el equipo multiprofesional (nutrición, psicología, educación física, odontología).');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (90, 17, 3, 'Quién debe estar atento — grupos de riesgo');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (290, 90, 0, 'Grupos que exigen atención redoblada: personas negras, con sobrepeso/obesidad, hipertensión, dislipidemia, antecedente familiar de diabetes, diabetes gestacional previa, síndrome de ovario poliquístico, uso de medicamentos hiperglucemiantes (corticoide) y personas en inseguridad alimentaria.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (291, 90, 1, 'Gestantes: cribar la diabetes gestacional en el prenatal (PTOG entre las 24 y 28 semanas, o antes en alto riesgo) — el cuidado adecuado reduce los desenlaces maternos y neonatales. Las gestantes negras merecen vigilancia reforzada, dado el mayor riesgo de desenlaces adversos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (292, 90, 2, 'Personas con diabetes y señales de sufrimiento psíquico: la depresión y el "burnout de la diabetes" son frecuentes y perjudican el autocuidado — acoja y articule con salud mental.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (91, 17, 4, 'Cuidado continuo y orientación al paciente/familia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (293, 91, 0, 'Explique, en lenguaje sencillo, que la diabetes tiene control — pero no cura — y que el tratamiento es continuo, incluso cuando la persona se siente bien. Enseñe el manejo básico: alimentación, actividad física, medicación y monitorización glucémica.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (294, 91, 1, 'Oriente el cuidado de los pies (examen diario, hidratación, calzado adecuado, nunca andar descalzo), el reconocimiento de la hipoglucemia y qué hacer en situaciones de riesgo. Refuerce la importancia de asistir a las consultas y de retirar los medicamentos regularmente en la farmacia.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (295, 91, 2, 'Llamado antirracista: cuando el control glucémico de una persona negra no mejora, no presuma "falta de adherencia" — investigue el acceso a medicamentos e insumos, la inseguridad alimentaria, el costo del transporte, los efectos adversos y la carga psicosocial. Históricamente, a los pacientes negros se les juzga el autocuidado con más rigor y reciben menos tecnología (análogos de insulina, monitores). Es un sesgo que debe combatirse activamente en la práctica clínica.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (18, 'diabetes', 'es', 'usuario', 'Qué es la diabetes, por qué es tan importante para la población negra, señales de alerta, cuidados diarios y dónde buscar ayuda en el SUS.', 'https://sspark.genspark.ai/i/fhNaPFo6WtBOQSHf?width=2560', 'Persona midiendo la glucemia capilar con glucómetro y tira reactiva en el dedo', 'Imagen de relleno (CC/PD) — sustituir por material propio si es necesario', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (92, 18, 0, 'Qué es');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (296, 92, 0, 'La diabetes es una enfermedad en la que el azúcar de la sangre (glucosa) se mantiene demasiado alta. Esto ocurre porque el cuerpo no produce insulina suficiente o no logra usarla bien. La insulina es el "portero" que introduce el azúcar en las células y da energía al cuerpo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (297, 92, 1, 'Cuando ese azúcar sobra en la sangre durante mucho tiempo, va dañando, poco a poco, el corazón, los ojos, los riñones, los nervios y los pies. Es una enfermedad crónica: la persona vive con ella, pero puede controlarla muy bien.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (93, 18, 1, 'Por qué importa');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (298, 93, 0, 'La población negra tiene más probabilidad de tener diabetes tipo 2, suele enfermar más temprano y desarrollar más complicaciones. Esto no es "suerte" ni culpa: tiene que ver con la genética, con la alimentación, con el estrés del racismo en el día a día y con el acceso desigual a médico, medicamentos y exámenes.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (299, 93, 1, 'La buena noticia: se puede controlar. Con diagnóstico precoz, seguimiento en la UBS, alimentación adecuada, actividad física y uso correcto de los medicamentos, es posible vivir bien y evitar las complicaciones más graves.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (94, 18, 2, 'Señales de alerta — mantente atento(a)');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (300, 94, 0, 'Acude a la UBS si tienes: mucha sed, ganas de orinar mucho (incluso de noche), pérdida de peso sin explicación, cansancio, visión borrosa o heridas que tardan en cicatrizar. Estas pueden ser señales de diabetes.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (301, 94, 1, 'Acude de inmediato a urgencias si hay: respiración rápida y profunda, aliento con olor a fruta, vómitos, dolor de barriga, somnolencia o confusión. Esto puede ser una urgencia de la diabetes.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (302, 94, 2, 'Aprende a reconocer la hipoglucemia (azúcar bajo): sudor frío, temblor, palidez, hambre repentina, mareo. En esos casos, toma rápido un poco de azúcar (un vaso de jugo, una cucharada de miel) y avisa a alguien.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (95, 18, 3, 'Cuidados diarios');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (303, 95, 0, 'Toma los medicamentos (o la insulina) todos los días, en el horario correcto, aunque te sientas bien. Nunca los suspendas por tu cuenta — si algún medicamento no está disponible en la farmacia, avisa al equipo de la UBS.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (304, 95, 1, 'Cuida la alimentación: reduce el azúcar, los refrescos y los ultraprocesados; prefiere comida de verdad — fríjol, arroz, verduras, legumbres, frutas y carnes con poca grasa. No tiene que ser perfecto: los pequeños cambios constantes ya ayudan mucho.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (305, 95, 2, 'Muévete: caminar, bailar, subir escaleras. Cualquier actividad regular ayuda a controlar el azúcar en la sangre.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (306, 95, 3, 'Cuida los pies todos los días: observa heridas, ampollas o enrojecimiento, hidrata (sin aplicar entre los dedos) y usa calzado cerrado y cómodo. Nunca andes descalzo. Una herida en el pie del diabético necesita atención rápida.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (307, 95, 4, 'Acude a las consultas y haz los exámenes de rutina (glucemia, hemoglobina glucosilada, ojos y riñones). El examen de fondo de ojo y el de orina son importantes para detectar problemas a tiempo, antes de que se vuelvan graves.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (96, 18, 4, 'Dónde buscar ayuda en el SUS');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (308, 96, 0, 'La Unidad Básica de Salud (UBS) es el lugar correcto para hacer el seguimiento de la diabetes, retirar los medicamentos (incluida la insulina) y recibir orientación con el equipo. El tratamiento de la diabetes es gratuito en el SUS.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (309, 96, 1, 'Si hay señales graves (respiración alterada, vómitos, confusión, hipoglucemia grave), acude de inmediato a urgencias o llama al 192 (SAMU).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (310, 96, 2, 'Usa la página "Red SUS" de esta plataforma para encontrar las unidades de salud más cercanas a ti en el Distrito Federal. Los grupos de apoyo y de educación en diabetes en la UBS ayudan mucho en el autocuidado.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (21, 'diabetes', 'es', 0, 'Sociedad Brasileña de Diabetes (SBD)', 'Directrices de la SBD — referencia nacional para diagnóstico y tratamiento de la diabetes.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (22, 'diabetes', 'es', 1, 'Ministerio de Salud de Brasil — PCDT Diabetes Mellitus', 'Protocolo Clínico y Directrices Terapéuticas vigente, referencia normativa para la conducta en el SUS.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (23, 'diabetes', 'es', 2, 'Estudio Población Negra DF 2015–2024', 'AECID/APRECIA/FIOCRUZ/UnB/FEPECS — Indicador 14 (diabetes como causa de muerte: 3.º lugar en 2014 → 8.º en 2024; estratificación racial pendiente).');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (24, 'diabetes', 'es', 3, 'American Diabetes Association (ADA)', 'Standards of Care in Diabetes — referencia internacional basada en evidencia, usada de forma complementaria.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (19, 'miomas-uterinos', 'pt', 'medico', 'Fisiopatologia dos leiomiomas, classificação FIGO, diagnóstico por imagem, opções terapêuticas e evidência sobre a disparidade racial em prevalência, gravidade e acesso a tratamentos menos invasivos.', 'https://sspark.genspark.ai/i/NYpPsNuS3oGvOr9t?width=2560', 'Ilustração anatômica do útero humano com representação de nódulos (miomas) na parede uterina', 'Imagem placeholder (CC/PD) — substituir por material próprio se necessário', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (97, 19, 0, 'O que é — fisiopatologia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (311, 97, 0, 'Os miomas uterinos (leiomiomas ou fibromas) são tumores benignos monoclonais do músculo liso do miométrio, extremamente prevalentes e dependentes de estrogênio e progesterona. Apesar de benignos, podem causar sangramento uterino anormal, dor pélvica, anemia ferropriva, efeitos compressivos (bexiga/reto) e infertilidade.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (312, 97, 1, 'A patogênese envolve fatores genéticos (mutações somáticas como MED12), epigenética, hormônios ovarianos, fatores de crescimento (TGF-β, FGF), inflamação e remodelamento da matriz extracelular. A deficiência de vitamina D e a exposição a disruptores endócrinos têm sido implicadas na maior proliferação.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (313, 97, 2, 'A classificação FIGO (0–8) descreve a localização (submucosa, intramural, subserosa), com impacto direto no tipo de sintoma e na elegibilidade para tratamentos conservadores (histeroscopia, embolização, miomectomia).');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (98, 19, 1, 'Por que importa — epidemiologia e recorte racial');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (314, 98, 0, 'Mulheres negras apresentam prevalência de miomas aproximadamente 2 a 3 vezes maior que mulheres brancas, com início mais precoce (idade mais jovem no diagnóstico), tumores maiores e mais numerosos, sintomas mais intensos (sangramento abundante, dor, anemia) e maior taxa de histerectomia.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (315, 98, 1, 'Essa disparidade combina predisposição genética/biológica, determinantes sociais (estresse crônico do racismo, exposição ambiental, vitamina D) e acesso desigual: mulheres negras têm menor probabilidade de receber tratamentos menos invasivos (miomectomia, embolização, terapias hormonais) e chegam mais frequentemente à cirurgia radical.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (316, 98, 2, 'O impacto na vida reprodutiva e na qualidade de vida (dor, sangramento, anemia, afastamentos) é significativo e frequentemente subvalorizado — o que reforça a necessidade de escuta qualificada e manejo equânime.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (99, 19, 2, 'Diagnóstico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (317, 99, 0, 'A avaliação inicial é clínica (história menstrual, sintomas compressivos, impacto na qualidade de vida) e complementada por exame pélvico. O diagnóstico por imagem de escolha é a ultrassonografia pélvica (transvaginal); a ressonância magnética é útil para mapeamento pré-operatório, miomas múltiplos ou planejamento de tratamento conservador.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (318, 99, 1, 'A histeroscopia diagnóstica avalia miomas submucosos e permite tratamento no mesmo procedimento. Sempre investigar anemia ferropriva associada ao sangramento, dosando hemograma e ferritina.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (319, 99, 2, 'Diagnóstico diferencial: pólipos endometriais, adenomiose, hiperplasia/malignidade endometrial, sarcomas uterinos (raros, suspeitar em crescimento rápido pós-menopausa).');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (100, 19, 3, 'Tratamento e condutas');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (320, 100, 0, 'O manejo é individualizado conforme sintomas, desejo de fertilidade, tamanho/localização dos miomas e comorbidades. Opções incluem: vigilância para casos assintomáticos; tratamento farmacológico (anticoncepcionais, progestágenos, sistema intrauterino de levonorgestrel, análogos de GnRH, moduladores seletivos); e intervenções procedimentais.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (321, 100, 1, 'Procedimentos conservadores: miomectomia (histeroscópica, laparoscópica ou aberta) e embolização de artérias uterinas (UAE), além de técnicas menos invasivas (ablação por radiofrequência, HIFU). A histerectomia é reservada para casos refratários ou quando não há desejo de preservar o útero.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (322, 100, 2, 'Ponto crítico de equidade: há evidência de que mulheres negras são encaminhadas com mais frequência à histerectomia e têm menos acesso a alternativas conservadoras. A oferta de todas as opções — de forma informada e sem estereótipos — é obrigação ética e de justiça reprodutiva.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (101, 19, 4, 'Quando referenciar / sinais de alarme clínico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (323, 101, 0, 'Referenciar à ginecologia: sangramento uterino anormal refratário ao tratamento inicial, anemia ferropriva grave, dor pélvica incapacitante, crescimento rápido de massa uterina, suspeita de malignidade, desejo de fertilidade com miomas que possam comprometer a implantação, e sintomas compressivos importantes.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (324, 101, 1, 'Sinais de alarme: sangramento pós-menopausa, sangramento com repercussão hemodinâmica (síncope, taquicardia, palidez), massa de crescimento acelerado ou sinais de obstrução/compressão urinária — exigem investigação urgente.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (325, 101, 2, 'Mulheres com anemia importante devem ser tratadas da anemia concomitantemente, com reposição de ferro e, quando necessário, transfusão, além do controle do sangramento.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (102, 19, 5, 'Fontes e diretrizes');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (326, 102, 0, 'Federação Brasileira das Associações de Ginecologia e Obstetrícia (FEBRASGO) — protocolos e diretrizes nacionais.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (327, 102, 1, 'Sociedade de Ginecologia e Obstetrícia do Estado de São Paulo (SOGESP) — referência clínica.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (328, 102, 2, 'American College of Obstetricians and Gynecologists (ACOG) / American Society for Reproductive Medicine (ASRM) — diretrizes internacionais baseadas em evidência.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (329, 102, 3, 'Literatura sobre disparidades raciais em miomas uterinos (NIH / estudos populacionais em mulheres negras).');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (20, 'miomas-uterinos', 'pt', 'enfermeiro', 'Reconhecimento do sangramento uterino anormal, triagem de anemia, acolhimento sem viés racial e orientação sobre os caminhos de cuidado dos miomas na Atenção Básica.', 'https://sspark.genspark.ai/i/NYpPsNuS3oGvOr9t?width=2560', 'Ilustração anatômica do útero humano com representação de nódulos (miomas) na parede uterina', 'Imagem placeholder (CC/PD) — substituir por material próprio se necessário', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (103, 20, 0, 'O que é');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (330, 103, 0, 'Miomas são tumores benignos (não cancerosos) que crescem na parede do útero. São muito comuns e, muitas vezes, não causam sintoma nenhum. Quando causam, os problemas mais frequentes são sangramento menstrual muito intenso, dor e sensação de pressão na barriga.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (331, 103, 1, 'É importante dizer com clareza: mioma NÃO é câncer. Mas, quando dá sintoma, precisa de acompanhamento — especialmente porque o sangramento intenso pode causar anemia.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (104, 20, 1, 'Sinais que a equipe deve reconhecer');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (332, 104, 0, 'Sangramento uterino anormal: menstruação muito intensa (troca de absorvente a cada hora, coágulos grandes), menstruação prolongada, sangramento entre as menstruações ou fora do período esperado.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (333, 104, 1, 'Sinais de anemia associada: cansaço intenso, palidez, falta de ar aos esforços, taquicardia, queda de cabelo — investigar hemograma e ferritina.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (334, 104, 2, 'Sintomas compressivos: necessidade frequente de urinar, dificuldade para evacuar, sensação de peso/volume abdominal e dor pélvica.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (335, 104, 3, 'Sinais de alarme que exigem encaminhamento prioritário: sangramento pós-menopausa, sangramento muito intenso com tontura/desmaio, crescimento rápido de massa abdominal.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (105, 20, 2, 'Triagem e acompanhamento na Atenção Básica');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (336, 105, 0, 'Priorize a escuta qualificada de mulheres negras que relatam menstruação intensa ou dor pélvica: elas têm maior prevalência de miomas e, historicamente, têm a dor subestimada. Registre a intensidade e o impacto do sangramento na vida diária (trabalho, escola, sono).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (337, 105, 1, 'Garanta a investigação básica: hemograma (anemia), ferritina, avaliação ginecológica e solicitação de ultrassonografia conforme protocolo. Busque ativamente casos de anemia em mulheres com sangramento abundante.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (338, 105, 2, 'No acompanhamento: monitorar sangramento e sintomas, reforçar a adesão a tratamentos hormonais quando prescritos, orientar sobre sinais de alarme e organizar o encaminhamento à ginecologia quando indicado.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (106, 20, 3, 'Quem fica atento — grupos de risco');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (339, 106, 0, 'Grupos que exigem atenção redobrada: mulheres negras (prevalência 2–3× maior e sintomas mais graves), mulheres na faixa de 30–50 anos, com histórico familiar de miomas, obesidade, hipertensão, início precoce da menstruação e que nunca engravidaram.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (340, 106, 1, 'Mulheres com anemia recorrente ou que não respondem ao ferro merecem investigação de sangramento uterino anormal como causa.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (341, 106, 2, 'Atenção especial ao desejo reprodutivo: registrar e respeitar o planejamento de gravidez da usuária, pois isso influencia diretamente as opções de tratamento e a defesa do direito de escolha informada.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (107, 20, 4, 'Cuidado continuado e orientação ao paciente/família');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (342, 107, 0, 'Explique, em linguagem simples, que mioma é comum, não é câncer e que existem várias formas de tratamento — nem toda mulher precisa de cirurgia. Desmistificar o medo ajuda a mulher a decidir com tranquilidade.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (343, 107, 1, 'Oriente sobre o registro dos dias e do volume do sangramento, a importância de tratar a anemia (ferro, alimentação) e o comparecimento às consultas. Esclareça que existem tratamentos com remédio, procedimentos que preservam o útero e, em alguns casos, cirurgia.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (344, 107, 2, 'Chamada anti-racista: a dor pélvica e o sangramento intenso de mulheres negras são frequentemente normalizados ("é assim mesmo") ou minimizados. Não banalize a queixa: acolha, registre e investigue. A intensidade relatada deve ser sempre levada a sério — pessoas negras historicamente têm sua dor subestimada e subtratada no sistema de saúde, e esse viés precisa ser combatido ativamente na triagem.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (21, 'miomas-uterinos', 'pt', 'usuario', 'O que são miomas, por que são tão comuns entre mulheres negras, sinais de alerta, cuidados do dia a dia e onde buscar ajuda no SUS.', 'https://sspark.genspark.ai/i/NYpPsNuS3oGvOr9t?width=2560', 'Ilustração anatômica do útero humano com representação de nódulos (miomas) na parede uterina', 'Imagem placeholder (CC/PD) — substituir por material próprio se necessário', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (108, 21, 0, 'O que é');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (345, 108, 0, 'Miomas (também chamados de fibromas) são caroços que crescem na parede do útero. Eles são muito comuns e não são câncer — são benignos. Muitas mulheres têm miomas e nem sabem, porque não sentem nada.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (346, 108, 1, 'Quando dão sintoma, o mais comum é a menstruação ficar muito intensa, com coágulos e muitos dias de duração, além de dor na barriga e vontade frequente de urinar. Em alguns casos, os miomas podem dificultar a gravidez.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (109, 21, 1, 'Por que isso importa');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (347, 109, 0, 'Os miomas são bem mais frequentes em mulheres negras: aparecem mais cedo, costumam ser maiores e dar mais sintomas, como sangramento intenso e anemia. Isso não é "coisa da sua cabeça" nem frescura — é uma condição real e mais grave para nós.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (348, 109, 1, 'A boa notícia: existem vários tratamentos, e a maioria não exige retirar o útero. Você tem o direito de conhecer todas as opções e decidir o que é melhor para o seu corpo e para os seus planos de vida.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (110, 21, 2, 'Sinais de alerta — fique atento(a)');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (349, 110, 0, 'Procure a UBS se você tiver: menstruação muito intensa (trocar absorvente a cada hora, com coágulos grandes), menstruação que dura muitos dias, sangramento entre as menstruações, dor forte na barriga ou na relação sexual.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (350, 110, 1, 'Fique atenta à anemia: cansaço que não passa, palidez, falta de ar, coração acelerado e queda de cabelo podem ser sinal de que o sangramento está tirando ferro do seu corpo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (351, 110, 2, 'Vá com prioridade se tiver: sangramento muito intenso com tontura ou desmaio, ou sangramento depois da menopausa. Nesses casos, procure atendimento no mesmo dia.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (111, 21, 3, 'Cuidados do dia a dia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (352, 111, 0, 'Anote em um caderno (ou no celular) os dias e o quanto você sangra, e leve essa anotação nas consultas — isso ajuda muito a equipe a entender o seu caso e a escolher o melhor tratamento.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (353, 111, 1, 'Trate a anemia: tome o ferro prescrito, mesmo que ele escureça o cocô (é normal), e coma alimentos ricos em ferro (feijão, carnes, folhas verdes escuras) junto com vitamina C (laranja, acerola), que ajuda na absorção.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (354, 111, 2, 'Não aceite "é normal sangrar assim": se o sangramento atrapalha sua vida, seu trabalho ou seu sono, isso é motivo para investigar e tratar. Você tem direito a tratamento.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (355, 111, 3, 'Se tiver planos de engravidar, fale isso claramente na consulta — existem tratamentos que preservam o útero e a sua capacidade de gestar.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (112, 21, 4, 'Onde buscar ajuda no SUS');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (356, 112, 0, 'A Unidade Básica de Saúde (UBS) é o ponto de partida: lá a equipe avalia o seu caso, pede os exames e, se precisar, encaminha para a ginecologia. Tudo pelo SUS, de graça.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (357, 112, 1, 'Se tiver sangramento muito intenso com tontura, desmaio ou dor insuportável, procure a UPA/pronto-socorro imediatamente.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (358, 112, 2, 'Use a página "Rede SUS" desta plataforma para encontrar as unidades de saúde mais próximas de você no Distrito Federal. Pergunte também sobre grupos de saúde da mulher na sua UBS.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (25, 'miomas-uterinos', 'pt', 0, 'FEBRASGO', 'Federação Brasileira das Associações de Ginecologia e Obstetrícia — protocolos nacionais sobre miomas e sangramento uterino anormal.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (26, 'miomas-uterinos', 'pt', 1, 'SOGESP', 'Sociedade de Ginecologia e Obstetrícia do Estado de São Paulo — referência clínica e apoio técnico de conteúdo.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (27, 'miomas-uterinos', 'pt', 2, 'ACOG / ASRM', 'American College of Obstetricians and Gynecologists e American Society for Reproductive Medicine — diretrizes internacionais baseadas em evidência.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (28, 'miomas-uterinos', 'pt', 3, 'Literatura sobre disparidades raciais (NIH)', 'Estudos populacionais que documentam a maior prevalência, gravidade e taxa de histerectomia em mulheres negras.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (22, 'miomas-uterinos', 'es', 'medico', 'Fisiopatología de los leiomiomas, clasificación FIGO, diagnóstico por imagen, opciones terapéuticas y evidencia sobre la disparidad racial en prevalencia, gravedad y acceso a tratamientos menos invasivos.', 'https://sspark.genspark.ai/i/NYpPsNuS3oGvOr9t?width=2560', 'Ilustración anatómica del útero humano con representación de nódulos (miomas) en la pared uterina', 'Imagen de relleno (CC/PD) — sustituir por material propio si es necesario', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (113, 22, 0, 'Qué es — fisiopatología');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (359, 113, 0, 'Los miomas uterinos (leiomiomas o fibromas) son tumores benignos monoclonales del músculo liso del miometrio, extremadamente prevalentes y dependientes de estrógeno y progesterona. Aunque benignos, pueden causar sangrado uterino anormal, dolor pélvico, anemia ferropénica, efectos compresivos (vejiga/recto) e infertilidad.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (360, 113, 1, 'La patogénesis involucra factores genéticos (mutaciones somáticas como MED12), epigenética, hormonas ováricas, factores de crecimiento (TGF-β, FGF), inflamación y remodelación de la matriz extracelular. La deficiencia de vitamina D y la exposición a disruptores endocrinos han sido implicadas en la mayor proliferación.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (361, 113, 2, 'La clasificación FIGO (0–8) describe la localización (submucoso, intramural, subseroso), con impacto directo en el tipo de síntoma y en la elegibilidad para tratamientos conservadores (histeroscopia, embolización, miomectomía).');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (114, 22, 1, 'Por qué importa — epidemiología y enfoque racial');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (362, 114, 0, 'Las mujeres negras presentan una prevalencia de miomas aproximadamente 2 a 3 veces mayor que las mujeres blancas, con inicio más precoz (edad más joven al diagnóstico), tumores más grandes y numerosos, síntomas más intensos (sangrado abundante, dolor, anemia) y mayor tasa de histerectomía.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (363, 114, 1, 'Esta disparidad combina predisposición genética/biológica, determinantes sociales (estrés crónico del racismo, exposición ambiental, vitamina D) y acceso desigual: las mujeres negras tienen menor probabilidad de recibir tratamientos menos invasivos (miomectomía, embolización, terapias hormonales) y llegan con más frecuencia a la cirugía radical.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (364, 114, 2, 'El impacto en la vida reproductiva y en la calidad de vida (dolor, sangrado, anemia, ausencias laborales) es significativo y frecuentemente subvalorado — lo que refuerza la necesidad de una escucha cualificada y un manejo equitativo.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (115, 22, 2, 'Diagnóstico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (365, 115, 0, 'La evaluación inicial es clínica (historia menstrual, síntomas compresivos, impacto en la calidad de vida) y se complementa con el examen pélvico. El diagnóstico por imagen de elección es la ecografía pélvica (transvaginal); la resonancia magnética es útil para el mapeo preoperatorio, miomas múltiples o la planificación de un tratamiento conservador.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (366, 115, 1, 'La histeroscopia diagnóstica evalúa los miomas submucosos y permite el tratamiento en el mismo procedimiento. Siempre investigar la anemia ferropénica asociada al sangrado, dosificando hemograma y ferritina.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (367, 115, 2, 'Diagnóstico diferencial: pólipos endometriales, adenomiosis, hiperplasia/malignidad endometrial, sarcomas uterinos (raros, sospechar en crecimiento rápido posmenopáusico).');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (116, 22, 3, 'Tratamiento y conductas');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (368, 116, 0, 'El manejo es individualizado según síntomas, deseo de fertilidad, tamaño/localización de los miomas y comorbilidades. Las opciones incluyen: vigilancia en casos asintomáticos; tratamiento farmacológico (anticonceptivos, progestágenos, sistema intrauterino de levonorgestrel, análogos de GnRH, moduladores selectivos); e intervenciones procedimentales.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (369, 116, 1, 'Procedimientos conservadores: miomectomía (histeroscópica, laparoscópica o abierta) y embolización de arterias uterinas (UAE), además de técnicas menos invasivas (ablación por radiofrecuencia, HIFU). La histerectomía se reserva para casos refractarios o cuando no hay deseo de preservar el útero.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (370, 116, 2, 'Punto crítico de equidad: hay evidencia de que las mujeres negras son derivadas con más frecuencia a la histerectomía y tienen menos acceso a alternativas conservadoras. Ofrecer todas las opciones — de forma informada y sin estereotipos — es una obligación ética y de justicia reproductiva.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (117, 22, 4, 'Cuándo derivar / señales de alarma clínica');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (371, 117, 0, 'Derivar a ginecología: sangrado uterino anormal refractario al tratamiento inicial, anemia ferropénica grave, dolor pélvico incapacitante, crecimiento rápido de masa uterina, sospecha de malignidad, deseo de fertilidad con miomas que puedan comprometer la implantación, y síntomas compresivos importantes.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (372, 117, 1, 'Señales de alarma: sangrado posmenopáusico, sangrado con repercusión hemodinámica (síncope, taquicardia, palidez), masa de crecimiento acelerado o señales de obstrucción/compresión urinaria — exigen investigación urgente.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (373, 117, 2, 'Las mujeres con anemia importante deben ser tratadas de la anemia concomitantemente, con reposición de hierro y, cuando sea necesario, transfusión, además del control del sangrado.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (118, 22, 5, 'Fuentes y directrices');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (374, 118, 0, 'Federación Brasileña de las Asociaciones de Ginecología y Obstetricia (FEBRASGO) — protocolos y directrices nacionales.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (375, 118, 1, 'Sociedad de Ginecología y Obstetricia del Estado de São Paulo (SOGESP) — referencia clínica.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (376, 118, 2, 'American College of Obstetricians and Gynecologists (ACOG) / American Society for Reproductive Medicine (ASRM) — directrices internacionales basadas en evidencia.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (377, 118, 3, 'Literatura sobre disparidades raciales en miomas uterinos (NIH / estudios poblacionales en mujeres negras).');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (23, 'miomas-uterinos', 'es', 'enfermeiro', 'Reconocimiento del sangrado uterino anormal, cribado de anemia, acogida sin sesgo racial y orientación sobre los caminos de cuidado de los miomas en la Atención Primaria.', 'https://sspark.genspark.ai/i/NYpPsNuS3oGvOr9t?width=2560', 'Ilustración anatómica del útero humano con representación de nódulos (miomas) en la pared uterina', 'Imagen de relleno (CC/PD) — sustituir por material propio si es necesario', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (119, 23, 0, 'Qué es');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (378, 119, 0, 'Los miomas son tumores benignos (no cancerosos) que crecen en la pared del útero. Son muy comunes y, muchas veces, no causan ningún síntoma. Cuando los causan, los problemas más frecuentes son sangrado menstrual muy intenso, dolor y sensación de presión en la barriga.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (379, 119, 1, 'Es importante decirlo con claridad: el mioma NO es cáncer. Pero, cuando da síntomas, necesita seguimiento — especialmente porque el sangrado intenso puede causar anemia.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (120, 23, 1, 'Señales que el equipo debe reconocer');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (380, 120, 0, 'Sangrado uterino anormal: menstruación muy intensa (cambio de toalla cada hora, coágulos grandes), menstruación prolongada, sangrado entre las menstruaciones o fuera del periodo esperado.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (381, 120, 1, 'Señales de anemia asociada: cansancio intenso, palidez, falta de aire al esfuerzo, taquicardia, caída del cabello — investigar hemograma y ferritina.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (382, 120, 2, 'Síntomas compresivos: necesidad frecuente de orinar, dificultad para evacuar, sensación de peso/volumen abdominal y dolor pélvico.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (383, 120, 3, 'Señales de alarma que exigen derivación prioritaria: sangrado posmenopáusico, sangrado muy intenso con mareo/desmayo, crecimiento rápido de masa abdominal.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (121, 23, 2, 'Cribado y seguimiento en la Atención Primaria');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (384, 121, 0, 'Priorice la escucha cualificada de mujeres negras que relatan menstruación intensa o dolor pélvico: tienen mayor prevalencia de miomas y, históricamente, su dolor es subestimado. Registre la intensidad y el impacto del sangrado en la vida diaria (trabajo, escuela, sueño).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (385, 121, 1, 'Garantice la investigación básica: hemograma (anemia), ferritina, evaluación ginecológica y solicitud de ecografía según protocolo. Busque activamente casos de anemia en mujeres con sangrado abundante.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (386, 121, 2, 'En el seguimiento: monitorear sangrado y síntomas, reforzar la adherencia a tratamientos hormonales cuando estén prescritos, orientar sobre señales de alarma y organizar la derivación a ginecología cuando esté indicado.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (122, 23, 3, 'Quién debe estar atento — grupos de riesgo');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (387, 122, 0, 'Grupos que exigen atención redoblada: mujeres negras (prevalencia 2–3× mayor y síntomas más graves), mujeres de 30–50 años, con antecedente familiar de miomas, obesidad, hipertensión, inicio precoz de la menstruación y que nunca han estado embarazadas.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (388, 122, 1, 'Las mujeres con anemia recurrente o que no responden al hierro merecen investigación de sangrado uterino anormal como causa.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (389, 122, 2, 'Atención especial al deseo reproductivo: registrar y respetar el planeamiento de embarazo de la usuaria, pues esto influye directamente en las opciones de tratamiento y en la defensa del derecho de elección informada.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (123, 23, 4, 'Cuidado continuo y orientación al paciente/familia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (390, 123, 0, 'Explique, en lenguaje sencillo, que el mioma es común, no es cáncer y que existen varias formas de tratamiento — no toda mujer necesita cirugía. Desmitificar el miedo ayuda a la mujer a decidir con tranquilidad.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (391, 123, 1, 'Oriente sobre el registro de los días y el volumen del sangrado, la importancia de tratar la anemia (hierro, alimentación) y la asistencia a las consultas. Aclare que existen tratamientos con medicamentos, procedimientos que preservan el útero y, en algunos casos, cirugía.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (392, 123, 2, 'Llamado antirracista: el dolor pélvico y el sangrado intenso de las mujeres negras son frecuentemente normalizados ("así es") o minimizados. No banalice la queja: acoja, registre e investigue. La intensidad relatada debe tomarse siempre en serio — las personas negras históricamente tienen su dolor subestimado y subtratado en el sistema de salud, y ese sesgo debe combatirse activamente en el triaje.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (24, 'miomas-uterinos', 'es', 'usuario', 'Qué son los miomas, por qué son tan comunes entre las mujeres negras, señales de alerta, cuidados diarios y dónde buscar ayuda en el SUS.', 'https://sspark.genspark.ai/i/NYpPsNuS3oGvOr9t?width=2560', 'Ilustración anatómica del útero humano con representación de nódulos (miomas) en la pared uterina', 'Imagen de relleno (CC/PD) — sustituir por material propio si es necesario', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (124, 24, 0, 'Qué es');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (393, 124, 0, 'Los miomas (también llamados fibromas) son bultos que crecen en la pared del útero. Son muy comunes y no son cáncer — son benignos. Muchas mujeres tienen miomas y ni lo saben, porque no sienten nada.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (394, 124, 1, 'Cuando dan síntomas, lo más común es que la menstruación se vuelva muy intensa, con coágulos y muchos días de duración, además de dolor en la barriga y ganas frecuentes de orinar. En algunos casos, los miomas pueden dificultar el embarazo.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (125, 24, 1, 'Por qué importa');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (395, 125, 0, 'Los miomas son mucho más frecuentes en las mujeres negras: aparecen más temprano, suelen ser más grandes y dar más síntomas, como sangrado intenso y anemia. Esto no es "cosa de tu cabeza" ni exageración — es una condición real y más grave para nosotras.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (396, 125, 1, 'La buena noticia: existen varios tratamientos, y la mayoría no exige extirpar el útero. Tienes derecho a conocer todas las opciones y a decidir lo que es mejor para tu cuerpo y para tus planes de vida.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (126, 24, 2, 'Señales de alerta — mantente atenta');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (397, 126, 0, 'Acude a la UBS si tienes: menstruación muy intensa (cambiar la toalla cada hora, con coágulos grandes), menstruación que dura muchos días, sangrado entre las menstruaciones, dolor fuerte en la barriga o en las relaciones sexuales.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (398, 126, 1, 'Presta atención a la anemia: cansancio que no pasa, palidez, falta de aire, corazón acelerado y caída del cabello pueden ser señal de que el sangrado está quitando hierro a tu cuerpo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (399, 126, 2, 'Acude con prioridad si tienes: sangrado muy intenso con mareo o desmayo, o sangrado después de la menopausia. En esos casos, busca atención el mismo día.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (127, 24, 3, 'Cuidados diarios');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (400, 127, 0, 'Anota en un cuaderno (o en el móvil) los días y cuánto sangras, y lleva esa anotación a las consultas — esto ayuda mucho al equipo a entender tu caso y a elegir el mejor tratamiento.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (401, 127, 1, 'Trata la anemia: toma el hierro prescrito, aunque oscurezca las heces (es normal), y come alimentos ricos en hierro (frijol, carnes, hojas verdes oscuras) junto con vitamina C (naranja, acerola), que ayuda en la absorción.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (402, 127, 2, 'No aceptes "es normal sangrar así": si el sangrado interfiere en tu vida, tu trabajo o tu sueño, eso es motivo para investigar y tratar. Tienes derecho a tratamiento.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (403, 127, 3, 'Si tienes planes de embarazo, dilo claramente en la consulta — existen tratamientos que preservan el útero y tu capacidad de gestar.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (128, 24, 4, 'Dónde buscar ayuda en el SUS');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (404, 128, 0, 'La Unidad Básica de Salud (UBS) es el punto de partida: allí el equipo evalúa tu caso, pide los exámenes y, si es necesario, te deriva a ginecología. Todo por el SUS, gratis.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (405, 128, 1, 'Si tienes sangrado muy intenso con mareo, desmayo o dolor insoportable, acude de inmediato a urgencias.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (406, 128, 2, 'Usa la página "Red SUS" de esta plataforma para encontrar las unidades de salud más cercanas a ti en el Distrito Federal. Pregunta también por grupos de salud de la mujer en tu UBS.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (29, 'miomas-uterinos', 'es', 0, 'FEBRASGO', 'Federación Brasileña de las Asociaciones de Ginecología y Obstetricia — protocolos nacionales sobre miomas y sangrado uterino anormal.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (30, 'miomas-uterinos', 'es', 1, 'SOGESP', 'Sociedad de Ginecología y Obstetricia del Estado de São Paulo — referencia clínica y apoyo técnico de contenido.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (31, 'miomas-uterinos', 'es', 2, 'ACOG / ASRM', 'American College of Obstetricians and Gynecologists y American Society for Reproductive Medicine — directrices internacionales basadas en evidencia.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (32, 'miomas-uterinos', 'es', 3, 'Literatura sobre disparidades raciales (NIH)', 'Estudios poblacionales que documentan la mayor prevalencia, gravedad y tasa de histerectomía en mujeres negras.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (25, 'lupus', 'pt', 'medico', 'Fisiopatologia do lúpus eritematoso sistêmico, critérios de classificação, avaliação de atividade e dano, arsenal terapêutico e evidência sobre a disparidade racial em gravidade, nefrite e mortalidade.', 'https://sspark.genspark.ai/i/2ZrbjwRPCOIjnBSA?width=2560', 'Ilustração médica representando inflamação autoimune multissistêmica do lúpus, com destaque para articulações e pele', 'Imagem placeholder (CC/PD) — substituir por material próprio se necessário', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (129, 25, 0, 'O que é — fisiopatologia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (407, 129, 0, 'O lúpus eritematoso sistêmico (LES) é uma doença autoimune crônica multissistêmica caracterizada pela perda da autotolerância, produção de autoanticorpos (anti-dsDNA, anti-Sm, anti-Ro, entre outros) e formação de imunocomplexos que depositam em tecidos, gerando inflamação e lesão de órgãos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (408, 129, 1, 'A patogênese envolve interação entre predisposição genética, fatores hormonais (predomínio feminino), ambientais (radiação ultravioleta, infecções, tabagismo, exposição a sílica) e epigenética. A ativação do interferon tipo I é um eixo central, e as vias de interferão têm se tornado alvo de terapias modernas.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (409, 129, 2, 'A doença tem curso em surtos (flares) e remissões, com potencial de acometer pele, articulações, rins (nefrite lúpica — a manifestação de maior gravidade), sistema nervoso central, serosas, sangue e pulmões. A gravidade e a mortalidade variam conforme ancestralidade e acesso ao cuidado.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (130, 25, 1, 'Por que importa — epidemiologia e recorte racial');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (410, 130, 0, 'O LES é mais prevalente e mais grave em mulheres negras: incidência 2 a 3 vezes maior que em mulheres brancas, início mais precoce, maior frequência de nefrite lúpica, mais atividade de doença, mais dano acumulado e mortalidade significativamente maior.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (411, 130, 1, 'A disparidade não é apenas biológica: combina predisposição genética (ancestralidade africana), determinantes sociais e acesso desigual a diagnóstico precoce, medicamentos poupadores de corticoide e terapias avançadas. O atraso diagnóstico é um fator crítico — quanto mais tempo a inflamação atua, maior o dano irreversível a rins e outros órgãos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (412, 130, 2, 'Manifestações em pele negra merecem atenção específica: a fotossensibilidade e o exantema malar podem ser mais difíceis de reconhecer em tons de pele mais escuros, contribuindo para subdiagnóstico e atraso de tratamento. Lesões discóides podem deixar cicatrizes com impacto estético e psicossocial importante.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (131, 25, 2, 'Diagnóstico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (413, 131, 0, 'O diagnóstico é clínico-laboratorial e baseia-se em critérios de classificação (EULAR/ACR 2019), que combinam a positividade do FAN (fator antinuclear) como critério de entrada e escores de domínios clínicos e imunológicos (anti-dsDNA, anti-Sm, anti-fosfolípides, hipocomplementemia, entre outros).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (414, 131, 1, 'O FAN positivo isolado NÃO é diagnóstico de lúpus — deve ser interpretado no contexto clínico. Complementar com hemograma, urina tipo 1, relação proteína/creatinina urinária, função renal, marcadores inflamatórios e sorologias conforme o quadro.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (415, 131, 2, 'A avaliação da nefrite lúpica é essencial: proteinúria, sedimento urinário ativo, queda de função renal e, quando indicado, biópsia renal com classificação histológica (ISN/RPS) orientam o tratamento. Rastrear antígenos anti-Ro/anti-La e anticorpos antifosfolípides conforme manifestações.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (132, 25, 3, 'Tratamento e condutas');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (416, 132, 0, 'O tratamento é individualizado conforme atividade e gravidade, com objetivo de controlar a inflamação, prevenir dano de órgãos e manter a qualidade de vida. Inclui hidroxicloroquina (pilar do tratamento, recomendada para quase todos os pacientes), corticoides em doses ajustadas, imunossupressores (metotrexato, azatioprina, micofenolato) e terapias biológicas (belimumabe, anifrolumabe, rituximabe) em casos selecionados.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (417, 132, 1, 'Na nefrite lúpica, o esquema de indução e manutenção com micofenolato ou ciclofosfamida, associado a corticoide, é a base; o acompanhamento com nefrologia é obrigatório. Proteção solar rigorosa, suplementação de vitamina D, vacinação adequada e manejo de fatores de risco cardiovascular são parte do cuidado integral.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (418, 132, 2, 'Ponto crítico de equidade: mulheres negras com LES têm maior probabilidade de receber apenas corticoide (com suas complicações) e menor acesso a poupadores de corticoide e terapias avançadas. Garantir acesso equânime ao tratamento moderno e o encaminhamento precoce à reumatologia é medida de justiça em saúde.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (133, 25, 4, 'Quando referenciar / sinais de alarme clínico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (419, 133, 0, 'Referenciar à reumatologia: suspeita diagnóstica, atividade de doença, necessidade de imunossupressão/terapia biológica e gestação (lúpus exige planejamento gestacional e equipe multiprofissional).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (420, 133, 1, 'Encaminhamento urgente à nefrologia: proteinúria significativa, sedimento urinário ativo, elevação de creatinina ou hipertensão — sinais de nefrite, que exigem avaliação e tratamento rápidos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (421, 133, 2, 'Sinais de alarme: acometimento do sistema nervoso central (convulsões, psicose, AVC), citopenias graves, serosite, comprometimento pulmonar ou cardíaco, e síndrome antifosfolípide com eventos trombóticos — situações de alto risco que demandam manejo especializado e, muitas vezes, hospitalar.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (134, 25, 5, 'Fontes e diretrizes');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (422, 134, 0, 'Sociedade Brasileira de Reumatologia (SBR) — recomendações e diretrizes nacionais para o LES.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (423, 134, 1, 'EULAR / ACR — critérios de classificação 2019 e recomendações de manejo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (424, 134, 2, 'Ministério da Saúde — Protocolo Clínico e Diretrizes Terapêuticas de Lúpus Eritematoso Sistêmico.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (425, 134, 3, 'Literatura sobre disparidades raciais em lúpus (LUMINA, NIH) — evidência de maior gravidade e mortalidade em mulheres negras.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (26, 'lupus', 'pt', 'enfermeiro', 'Reconhecimento dos sinais de lúpus, rastreio de complicações (especialmente renais), acolhimento de mulheres negras com queixas frequentemente desvalorizadas e apoio ao autocuidado.', 'https://sspark.genspark.ai/i/2ZrbjwRPCOIjnBSA?width=2560', 'Ilustração médica representando inflamação autoimune multissistêmica do lúpus, com destaque para articulações e pele', 'Imagem placeholder (CC/PD) — substituir por material próprio se necessário', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (135, 26, 0, 'O que é');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (426, 135, 0, 'O lúpus é uma doença autoimune crônica: o sistema de defesa do corpo ataca os próprios tecidos por engano. Pode afetar a pele, as juntas, os rins, o sangue e outros órgãos. É mais comum em mulheres, especialmente mulheres negras, e costuma aparecer entre os 15 e os 45 anos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (427, 135, 1, 'O lúpus vai e volta: tem fases de crise (quando os sintomas pioram) e fases mais calmas. Reconhecer os sinais de crise e agir rápido evita que os órgãos sejam machucados de forma permanente.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (136, 26, 1, 'Sinais que a equipe deve reconhecer');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (428, 136, 0, 'Sintomas gerais frequentes: cansaço intenso e desproporcional, febre baixa sem infecção aparente, dor e inchaço nas juntas, queda de cabelo e aftas na boca.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (429, 136, 1, 'Manifestações na pele: manchas no rosto (em "asas de borboleta"), lesões que pioram com o sol (fotossensibilidade) e feridas na pele. Em pele negra, essas manchas podem ser mais difíceis de perceber — atenção redobrada à queixa da paciente.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (430, 136, 2, 'Sinais de gravidade que exigem avaliação médica imediata: urina espumosa ou com sangue, inchaço nas pernas, pressão alta nova, falta de ar, dor no peito, convulsões, confusão mental e queda importante das células do sangue.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (137, 26, 2, 'Triagem e acompanhamento na Atenção Básica');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (431, 137, 0, 'Valorize queixas persistentes de cansaço, dor articular e manchas na pele em mulheres negras: o lúpus é mais grave e mais frequente nesse grupo, e o atraso diagnóstico é comum. Não trate como "estresse" ou "drama".');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (432, 137, 1, 'Apoie a investigação: solicitação de FAN, hemograma, urina tipo 1, função renal e marcadores inflamatórios conforme protocolo. O acompanhamento da urina (proteinúria) é essencial para detectar nefrite precocemente.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (433, 137, 2, 'No acompanhamento: monitore sinais de crise, adesão à hidroxicloroquina e aos demais medicamentos, efeitos adversos, proteção solar, vacinação e saúde cardiovascular (o lúpus aumenta o risco de infarto e AVC).');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (138, 26, 3, 'Quem fica atento — grupos de risco');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (434, 138, 0, 'Grupos que exigem atenção redobrada: mulheres negras (incidência 2–3× maior e doença mais grave), mulheres entre 15 e 45 anos, com histórico familiar de doenças autoimunes, e pessoas com outras condições autoimunes associadas.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (435, 138, 1, 'Gestantes com lúpus: exigem acompanhamento conjunto com reumatologia e obstetrícia de alto risco, pois o lúpus pode agravar a gestação e aumentar o risco de complicações maternas e fetais.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (436, 138, 2, 'Pessoas com nefrite lúpica precisam de monitorização renal frequente e encaminhamento à nefrologia — o cuidado com o rim é o que mais muda o desfecho a longo prazo.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (139, 26, 4, 'Cuidado continuado e orientação ao paciente/família');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (437, 139, 0, 'Explique que o lúpus tem tratamento e que, com acompanhamento regular, a maioria das pessoas vive bem. Reforce que a hidroxicloroquina não deve ser interrompida por conta própria — ela reduz crises e protege os órgãos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (438, 139, 1, 'Oriente sobre proteção solar rigorosa (protetor, roupas, evitar sol forte), sinais de crise que exigem retorno imediato, uso correto dos medicamentos e a importância das consultas e exames periódicos, especialmente os de urina e sangue.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (439, 139, 2, 'Chamada anti-racista: a dor e o cansaço de mulheres negras são frequentemente subestimados ou atribuídos a fatores emocionais, atrasando o diagnóstico de lúpus — que é justamente mais grave nelas. Leve a queixa a sério, registre e investigue. A intensidade relatada deve ser sempre considerada um dado clínico legítimo.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (27, 'lupus', 'pt', 'usuario', 'O que é lúpus, por que é mais comum e mais grave em mulheres negras, sinais de alerta, cuidados do dia a dia e onde buscar ajuda no SUS.', 'https://sspark.genspark.ai/i/2ZrbjwRPCOIjnBSA?width=2560', 'Ilustração médica representando inflamação autoimune multissistêmica do lúpus, com destaque para articulações e pele', 'Imagem placeholder (CC/PD) — substituir por material próprio se necessário', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (140, 27, 0, 'O que é');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (440, 140, 0, 'Lúpus é uma doença em que o sistema de defesa do corpo (a imunidade) ataca os próprios tecidos por engano. Ele pode afetar a pele, as juntas, os rins, o sangue e outros órgãos. Não é contagioso — não se pega de ninguém.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (441, 140, 1, 'A doença vai e volta: tem fases em que os sintomas pioram (as crises) e fases mais tranquilas. Com acompanhamento certo, dá para viver bem e proteger os órgãos.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (141, 27, 1, 'Por que isso importa');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (442, 141, 0, 'O lúpus é bem mais comum e mais grave em mulheres negras: aparece mais cedo, dá mais crises e afeta os rins com mais frequência. Por isso, é tão importante reconhecer os sinais cedo e não deixar passar.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (443, 141, 1, 'Muitas mulheres negras ouvem que "é só estresse" ou "é frescura" quando relatam cansaço e dor. Isso atrasa o diagnóstico. Você tem o direito de ser ouvida e investigada com seriedade.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (142, 27, 2, 'Sinais de alerta — fique atento(a)');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (444, 142, 0, 'Procure a UBS se você tiver, com frequência: cansaço muito forte, febre baixa sem explicação, dor e inchaço nas juntas, queda de cabelo, aftas na boca ou manchas na pele que pioram com o sol.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (445, 142, 1, 'Fique atenta às manchas no rosto (em forma de "asas de borboleta") e a feridas na pele que aparecem ou pioram no sol. Em pele negra, elas podem ser mais difíceis de ver — observe mudanças na sua pele.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (446, 142, 2, 'Vá imediatamente à UPA/pronto-socorro se tiver: urina espumosa ou com sangue, inchaço nas pernas, falta de ar, dor no peito, convulsões, confusão mental ou desmaio. Esses sinais podem indicar crise grave ou problema nos rins.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (143, 27, 3, 'Cuidados do dia a dia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (447, 143, 0, 'Tome os remédios todos os dias, principalmente a hidroxicloroquina — ela reduz as crises e protege seus órgãos. Nunca pare por conta própria, mesmo quando estiver se sentindo bem.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (448, 143, 1, 'Proteja-se do sol: use protetor solar todos os dias, chapéu, roupas que cubram a pele e evite o sol forte entre 10h e 16h. O sol é um dos principais gatilhos de crise.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (449, 143, 2, 'Vá às consultas e faça os exames de sangue e de urina com regularidade. O exame de urina é muito importante: ele mostra cedo quando o rim está sendo afetado.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (450, 143, 3, 'Cuide do corpo de forma geral: durma bem, alimente-se de forma saudável, evite cigarro e mantenha a pressão e o açúcar controlados — isso protege o coração e os rins.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (451, 143, 4, 'Planeje uma gravidez junto com a equipe de saúde: engravidar com o lúpus controlado é mais seguro para você e para o bebê.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (144, 27, 4, 'Onde buscar ajuda no SUS');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (452, 144, 0, 'A Unidade Básica de Saúde (UBS) é o ponto de partida: a equipe avalia, pede os exames e, se precisar, encaminha para o reumatologista. O tratamento do lúpus é gratuito no SUS.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (453, 144, 1, 'Se tiver sinais graves (urina alterada, falta de ar, dor no peito, convulsão, confusão), procure a UPA ou o pronto-socorro imediatamente ou ligue 192 (SAMU).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (454, 144, 2, 'Use a página "Rede SUS" desta plataforma para encontrar as unidades de saúde mais próximas de você no Distrito Federal. Grupos de apoio entre pacientes ajudam muito a lidar com a doença no dia a dia.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (33, 'lupus', 'pt', 0, 'Sociedade Brasileira de Reumatologia (SBR)', 'Recomendações e diretrizes nacionais para o diagnóstico e o manejo do lúpus eritematoso sistêmico.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (34, 'lupus', 'pt', 1, 'EULAR / ACR 2019', 'Critérios de classificação e recomendações internacionais de manejo — referência para a prática clínica baseada em evidência.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (35, 'lupus', 'pt', 2, 'Ministério da Saúde — PCDT Lúpus Eritematoso Sistêmico', 'Protocolo Clínico e Diretrizes Terapêuticas vigente, referência normativa para a conduta no SUS.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (36, 'lupus', 'pt', 3, 'Estudos de disparidade racial (LUMINA / NIH)', 'Evidência de maior gravidade, nefrite e mortalidade em mulheres negras com lúpus, associada a fatores genéticos e sociais.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (28, 'lupus', 'es', 'medico', 'Fisiopatología del lupus eritematoso sistémico, criterios de clasificación, evaluación de actividad y daño, arsenal terapéutico y evidencia sobre la disparidad racial en gravedad, nefritis y mortalidad.', 'https://sspark.genspark.ai/i/2ZrbjwRPCOIjnBSA?width=2560', 'Ilustración médica que representa la inflamación autoinmune multisistémica del lupus, con énfasis en articulaciones y piel', 'Imagen de relleno (CC/PD) — sustituir por material propio si es necesario', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (145, 28, 0, 'Qué es — fisiopatología');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (455, 145, 0, 'El lupus eritematoso sistémico (LES) es una enfermedad autoinmune crónica multisistémica caracterizada por la pérdida de la autotolerancia, la producción de autoanticuerpos (anti-dsDNA, anti-Sm, anti-Ro, entre otros) y la formación de inmunocomplejos que se depositan en los tejidos, generando inflamación y lesión de órganos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (456, 145, 1, 'La patogénesis involucra la interacción entre predisposición genética, factores hormonales (predominio femenino), ambientales (radiación ultravioleta, infecciones, tabaquismo, exposición a sílice) y epigenética. La activación del interferón tipo I es un eje central, y las vías de interferón se han convertido en blanco de terapias modernas.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (457, 145, 2, 'La enfermedad tiene un curso de brotes (flares) y remisiones, con potencial de afectar piel, articulaciones, riñones (nefritis lúpica — la manifestación de mayor gravedad), sistema nervioso central, serosas, sangre y pulmones. La gravedad y la mortalidad varían según la ancestralidad y el acceso al cuidado.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (146, 28, 1, 'Por qué importa — epidemiología y enfoque racial');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (458, 146, 0, 'El LES es más prevalente y más grave en mujeres negras: incidencia 2 a 3 veces mayor que en mujeres blancas, inicio más precoz, mayor frecuencia de nefritis lúpica, más actividad de enfermedad, más daño acumulado y mortalidad significativamente mayor.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (459, 146, 1, 'La disparidad no es solo biológica: combina predisposición genética (ancestralidad africana), determinantes sociales y acceso desigual a diagnóstico precoz, medicamentos ahorradores de corticoide y terapias avanzadas. El retraso diagnóstico es un factor crítico — cuanto más tiempo actúa la inflamación, mayor el daño irreversible a los riñones y otros órganos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (460, 146, 2, 'Las manifestaciones en piel negra merecen atención específica: la fotosensibilidad y el exantema malar pueden ser más difíciles de reconocer en tonos de piel más oscuros, contribuyendo al subdiagnóstico y al retraso del tratamiento. Las lesiones discoides pueden dejar cicatrices con impacto estético y psicosocial importante.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (147, 28, 2, 'Diagnóstico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (461, 147, 0, 'El diagnóstico es clínico-laboratorial y se basa en criterios de clasificación (EULAR/ACR 2019), que combinan la positividad del ANA (anticuerpo antinuclear) como criterio de entrada y puntuaciones de dominios clínicos e inmunológicos (anti-dsDNA, anti-Sm, antifosfolípidos, hipocomplementemia, entre otros).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (462, 147, 1, 'El ANA positivo aislado NO es diagnóstico de lupus — debe interpretarse en el contexto clínico. Complementar con hemograma, análisis de orina, relación proteína/creatinina urinaria, función renal, marcadores inflamatorios y serologías según el cuadro.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (463, 147, 2, 'La evaluación de la nefritis lúpica es esencial: proteinuria, sedimento urinario activo, caída de la función renal y, cuando esté indicado, biopsia renal con clasificación histológica (ISN/RPS) orientan el tratamiento. Rastrear anti-Ro/anti-La y anticuerpos antifosfolípidos según las manifestaciones.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (148, 28, 3, 'Tratamiento y conductas');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (464, 148, 0, 'El tratamiento es individualizado según actividad y gravedad, con el objetivo de controlar la inflamación, prevenir el daño de órganos y mantener la calidad de vida. Incluye hidroxicloroquina (pilar del tratamiento, recomendada para casi todos los pacientes), corticoides en dosis ajustadas, inmunosupresores (metotrexato, azatioprina, micofenolato) y terapias biológicas (belimumab, anifrolumab, rituximab) en casos seleccionados.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (465, 148, 1, 'En la nefritis lúpica, el esquema de inducción y mantenimiento con micofenolato o ciclofosfamida, asociado a corticoide, es la base; el seguimiento con nefrología es obligatorio. La fotoprotección rigurosa, la suplementación de vitamina D, la vacunación adecuada y el manejo de los factores de riesgo cardiovascular son parte del cuidado integral.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (466, 148, 2, 'Punto crítico de equidad: las mujeres negras con LES tienen mayor probabilidad de recibir solo corticoide (con sus complicaciones) y menor acceso a ahorradores de corticoide y terapias avanzadas. Garantizar un acceso equitativo al tratamiento moderno y la derivación precoz a reumatología es una medida de justicia en salud.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (149, 28, 4, 'Cuándo derivar / señales de alarma clínica');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (467, 149, 0, 'Derivar a reumatología: sospecha diagnóstica, actividad de enfermedad, necesidad de inmunosupresión/terapia biológica y embarazo (el lupus exige planificación gestacional y equipo multiprofesional).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (468, 149, 1, 'Derivación urgente a nefrología: proteinuria significativa, sedimento urinario activo, elevación de creatinina o hipertensión — señales de nefritis, que exigen evaluación y tratamiento rápidos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (469, 149, 2, 'Señales de alarma: afectación del sistema nervioso central (convulsiones, psicosis, ictus), citopenias graves, serositis, compromiso pulmonar o cardíaco, y síndrome antifosfolípido con eventos trombóticos — situaciones de alto riesgo que requieren manejo especializado y, a menudo, hospitalario.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (150, 28, 5, 'Fuentes y directrices');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (470, 150, 0, 'Sociedad Brasileña de Reumatología (SBR) — recomendaciones y directrices nacionales para el LES.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (471, 150, 1, 'EULAR / ACR — criterios de clasificación 2019 y recomendaciones de manejo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (472, 150, 2, 'Ministerio de Salud de Brasil — Protocolo Clínico y Directrices Terapéuticas de Lupus Eritematoso Sistémico.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (473, 150, 3, 'Literatura sobre disparidades raciales en lupus (LUMINA, NIH) — evidencia de mayor gravedad y mortalidad en mujeres negras.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (29, 'lupus', 'es', 'enfermeiro', 'Reconocimiento de las señales de lupus, cribado de complicaciones (especialmente renales), acogida de mujeres negras con quejas frecuentemente desvalorizadas y apoyo al autocuidado.', 'https://sspark.genspark.ai/i/2ZrbjwRPCOIjnBSA?width=2560', 'Ilustración médica que representa la inflamación autoinmune multisistémica del lupus, con énfasis en articulaciones y piel', 'Imagen de relleno (CC/PD) — sustituir por material propio si es necesario', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (151, 29, 0, 'Qué es');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (474, 151, 0, 'El lupus es una enfermedad autoinmune crónica: el sistema de defensa del cuerpo ataca sus propios tejidos por error. Puede afectar la piel, las articulaciones, los riñones, la sangre y otros órganos. Es más común en mujeres, especialmente mujeres negras, y suele aparecer entre los 15 y los 45 años.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (475, 151, 1, 'El lupus va y viene: tiene fases de brote (cuando los síntomas empeoran) y fases más calmadas. Reconocer las señales de brote y actuar rápido evita que los órganos se dañen de forma permanente.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (152, 29, 1, 'Señales que el equipo debe reconocer');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (476, 152, 0, 'Síntomas generales frecuentes: cansancio intenso y desproporcionado, fiebre baja sin infección aparente, dolor e hinchazón en las articulaciones, caída del cabello y aftas en la boca.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (477, 152, 1, 'Manifestaciones en la piel: manchas en el rostro (en "alas de mariposa"), lesiones que empeoran con el sol (fotosensibilidad) y heridas en la piel. En piel negra, estas manchas pueden ser más difíciles de percibir — atención redoblada a la queja de la paciente.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (478, 152, 2, 'Señales de gravedad que exigen evaluación médica inmediata: orina espumosa o con sangre, hinchazón en las piernas, presión alta nueva, falta de aire, dolor en el pecho, convulsiones, confusión mental y caída importante de las células de la sangre.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (153, 29, 2, 'Cribado y seguimiento en la Atención Primaria');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (479, 153, 0, 'Valore las quejas persistentes de cansancio, dolor articular y manchas en la piel en mujeres negras: el lupus es más grave y más frecuente en este grupo, y el retraso diagnóstico es común. No lo trate como "estrés" o "drama".');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (480, 153, 1, 'Apoye la investigación: solicitud de ANA, hemograma, análisis de orina, función renal y marcadores inflamatorios según protocolo. El seguimiento de la orina (proteinuria) es esencial para detectar la nefritis precozmente.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (481, 153, 2, 'En el seguimiento: monitorear señales de brote, adherencia a la hidroxicloroquina y a los demás medicamentos, efectos adversos, fotoprotección, vacunación y salud cardiovascular (el lupus aumenta el riesgo de infarto e ictus).');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (154, 29, 3, 'Quién debe estar atento — grupos de riesgo');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (482, 154, 0, 'Grupos que exigen atención redoblada: mujeres negras (incidencia 2–3× mayor y enfermedad más grave), mujeres entre 15 y 45 años, con antecedente familiar de enfermedades autoinmunes, y personas con otras condiciones autoinmunes asociadas.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (483, 154, 1, 'Gestantes con lupus: exigen seguimiento conjunto con reumatología y obstetricia de alto riesgo, pues el lupus puede agravar el embarazo y aumentar el riesgo de complicaciones maternas y fetales.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (484, 154, 2, 'Las personas con nefritis lúpica necesitan monitorización renal frecuente y derivación a nefrología — el cuidado del riñón es lo que más cambia el desenlace a largo plazo.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (155, 29, 4, 'Cuidado continuo y orientación al paciente/familia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (485, 155, 0, 'Explique que el lupus tiene tratamiento y que, con seguimiento regular, la mayoría de las personas vive bien. Refuerce que la hidroxicloroquina no debe interrumpirse por cuenta propia — reduce los brotes y protege los órganos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (486, 155, 1, 'Oriente sobre fotoprotección rigurosa (protector, ropa, evitar el sol fuerte), señales de brote que exigen retorno inmediato, uso correcto de los medicamentos y la importancia de las consultas y exámenes periódicos, especialmente los de orina y sangre.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (487, 155, 2, 'Llamado antirracista: el dolor y el cansancio de las mujeres negras son frecuentemente subestimados o atribuidos a factores emocionales, retrasando el diagnóstico de lupus — que es justamente más grave en ellas. Tome la queja en serio, registre e investigue. La intensidad relatada debe considerarse siempre un dato clínico legítimo.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (30, 'lupus', 'es', 'usuario', 'Qué es el lupus, por qué es más común y más grave en las mujeres negras, señales de alerta, cuidados diarios y dónde buscar ayuda en el SUS.', 'https://sspark.genspark.ai/i/2ZrbjwRPCOIjnBSA?width=2560', 'Ilustración médica que representa la inflamación autoinmune multisistémica del lupus, con énfasis en articulaciones y piel', 'Imagen de relleno (CC/PD) — sustituir por material propio si es necesario', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (156, 30, 0, 'Qué es');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (488, 156, 0, 'El lupus es una enfermedad en la que el sistema de defensa del cuerpo (la inmunidad) ataca sus propios tejidos por error. Puede afectar la piel, las articulaciones, los riñones, la sangre y otros órganos. No es contagioso — no se contrae de nadie.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (489, 156, 1, 'La enfermedad va y viene: tiene fases en que los síntomas empeoran (los brotes) y fases más tranquilas. Con el seguimiento correcto, se puede vivir bien y proteger los órganos.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (157, 30, 1, 'Por qué importa');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (490, 157, 0, 'El lupus es mucho más común y más grave en las mujeres negras: aparece más temprano, da más brotes y afecta los riñones con más frecuencia. Por eso es tan importante reconocer las señales temprano y no dejar pasar.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (491, 157, 1, 'Muchas mujeres negras oyen que "es solo estrés" o "es exageración" cuando relatan cansancio y dolor. Eso retrasa el diagnóstico. Tienes derecho a ser escuchada e investigada con seriedad.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (158, 30, 2, 'Señales de alerta — mantente atenta');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (492, 158, 0, 'Acude a la UBS si tienes, con frecuencia: cansancio muy fuerte, fiebre baja sin explicación, dolor e hinchazón en las articulaciones, caída del cabello, aftas en la boca o manchas en la piel que empeoran con el sol.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (493, 158, 1, 'Presta atención a las manchas en el rostro (en forma de "alas de mariposa") y a las heridas en la piel que aparecen o empeoran con el sol. En piel negra, pueden ser más difíciles de ver — observa los cambios en tu piel.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (494, 158, 2, 'Acude de inmediato a urgencias si tienes: orina espumosa o con sangre, hinchazón en las piernas, falta de aire, dolor en el pecho, convulsiones, confusión mental o desmayo. Estas señales pueden indicar un brote grave o un problema en los riñones.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (159, 30, 3, 'Cuidados diarios');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (495, 159, 0, 'Toma los medicamentos todos los días, principalmente la hidroxicloroquina — reduce los brotes y protege tus órganos. Nunca los suspendas por cuenta propia, aunque te sientas bien.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (496, 159, 1, 'Protégete del sol: usa protector solar todos los días, sombrero, ropa que cubra la piel y evita el sol fuerte entre las 10 h y las 16 h. El sol es uno de los principales desencadenantes de los brotes.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (497, 159, 2, 'Acude a las consultas y haz los exámenes de sangre y de orina con regularidad. El análisis de orina es muy importante: muestra temprano cuando el riñón está siendo afectado.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (498, 159, 3, 'Cuida el cuerpo en general: duerme bien, aliméntate de forma saludable, evita el cigarrillo y mantén la presión y el azúcar controlados — esto protege el corazón y los riñones.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (499, 159, 4, 'Planifica un embarazo junto con el equipo de salud: embarazarse con el lupus controlado es más seguro para ti y para el bebé.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (160, 30, 4, 'Dónde buscar ayuda en el SUS');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (500, 160, 0, 'La Unidad Básica de Salud (UBS) es el punto de partida: el equipo evalúa, pide los exámenes y, si es necesario, te deriva al reumatólogo. El tratamiento del lupus es gratuito en el SUS.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (501, 160, 1, 'Si tienes señales graves (orina alterada, falta de aire, dolor en el pecho, convulsión, confusión), acude de inmediato a urgencias o llama al 192 (SAMU).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (502, 160, 2, 'Usa la página "Red SUS" de esta plataforma para encontrar las unidades de salud más cercanas a ti en el Distrito Federal. Los grupos de apoyo entre pacientes ayudan mucho a sobrellevar la enfermedad en el día a día.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (37, 'lupus', 'es', 0, 'Sociedad Brasileña de Reumatología (SBR)', 'Recomendaciones y directrices nacionales para el diagnóstico y el manejo del lupus eritematoso sistémico.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (38, 'lupus', 'es', 1, 'EULAR / ACR 2019', 'Criterios de clasificación y recomendaciones internacionales de manejo — referencia para la práctica clínica basada en evidencia.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (39, 'lupus', 'es', 2, 'Ministerio de Salud de Brasil — PCDT Lupus Eritematoso Sistémico', 'Protocolo Clínico y Directrices Terapéuticas vigente, referencia normativa para la conducta en el SUS.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (40, 'lupus', 'es', 3, 'Estudios de disparidad racial (LUMINA / NIH)', 'Evidencia de mayor gravedad, nefritis y mortalidad en mujeres negras con lupus, asociada a factores genéticos y sociales.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (31, 'depressao', 'pt', 'medico', 'Fisiopatologia e classificação do transtorno depressivo maior, critérios diagnósticos, diagnóstico diferencial, opções terapêuticas e evidência sobre subdiagnóstico e disparidades raciais no tratamento.', 'https://sspark.genspark.ai/i/JKe27K9j1WJNZSzz?width=2560', 'Pessoa sentada em silêncio, com expressão de reflexão, representando o sofrimento psíquico da depressão', 'Imagem placeholder (CC/PD) — substituir por material próprio se necessário', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (161, 31, 0, 'O que é — fisiopatologia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (503, 161, 0, 'O transtorno depressivo maior (TDM) é um transtorno do humor caracterizado por tristeza persistente e/ou anedonia (perda de interesse e prazer), acompanhadas de alterações cognitivas, motoras e neurovegetativas (sono, apetite, energia), com prejuízo funcional significativo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (504, 161, 1, 'A fisiopatologia é multifatorial e envolve disfunção de circuitos corticolímbicos, desregulação de monoaminas, alterações do eixo hipotálamo-hipófise-adrenal (HPA), neuroinflamação, alterações neuroplásticas (fator neurotrófico derivado do cérebro — BDNF) e fatores genéticos e epigenéticos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (505, 161, 2, 'Determinantes sociais desempenham papel central: exposição crônica ao estresse (incluindo o estresse do racismo estrutural e da discriminação), violência, insegurança financeira e alimentar, e isolamento social alteram de forma mensurável o eixo HPA e a carga alostática — tornando o racismo um determinante de sofrimento psíquico, e não um "fator de risco" abstrato.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (162, 31, 1, 'Por que importa — epidemiologia e recorte racial');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (506, 162, 0, 'Pessoas negras apresentam carga de sofrimento psíquico igual ou maior que a população branca, mas taxas menores de diagnóstico e de tratamento adequado. O quadro é frequentemente subdiagnosticado ou tratado apenas como sintoma somático, refletindo racismo institucional e estigma.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (507, 162, 1, 'Quando diagnosticadas, pessoas negras têm menor probabilidade de receber psicoterapia, medicamentos adequados em dose e tempo corretos, e acompanhamento continuado. A depressão pós-parto em mulheres negras é particularmente sub-reconhecida, apesar do maior risco.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (508, 162, 2, 'O racismo — interpessoal e estrutural — funciona como expositor crônico e fator de manutenção do sofrimento. Reconhecer isso é essencial para não reduzir a depressão na população negra a uma questão individual, descontextualizada das condições de vida.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (163, 31, 2, 'Diagnóstico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (509, 163, 0, 'O diagnóstico é clínico, baseado nos critérios do DSM-5-TR ou da CID-11. Para o episódio depressivo maior, exige-se humor deprimido e/ou anedonia por pelo menos duas semanas, acompanhados de pelo menos cinco sintomas (alterações de sono, apetite, energia, concentração, psicomotricidade, sentimento de culpa/desvalia e ideação suicida).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (510, 163, 1, 'Sempre avaliar risco de suicídio de forma direta e cuidadosa — é uma emergência médica. Aplicar instrumentos de rastreio validados (PHQ-9, GAD-7) facilita a detecção, especialmente na Atenção Básica.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (511, 163, 2, 'Diagnóstico diferencial: transtorno bipolar (essencial antes de iniciar antidepressivo), hipotireoidismo, anemia, deficiência de vitamina B12/folato, uso de substâncias, efeitos de medicamentos e luto — além de condições médicas que mimetizam a depressão.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (164, 31, 3, 'Tratamento e condutas');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (512, 164, 0, 'O tratamento combina psicoterapia (terapia cognitivo-comportamental e outras abordagens baseadas em evidência), farmacoterapia (antidepressivos — ISRS como primeira linha) e intervenções psicossociais. A escolha considera gravidade, comorbidades, preferência do paciente e histórico de resposta.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (513, 164, 1, 'Casos graves, refratários ou com risco elevado de suicídio podem exigir combinação de medicamentos, potencialização, eletroconvulsoterapia (ECT) ou encaminhamento a serviços especializados. O tratamento deve ser continuado por tempo adequado para prevenir recaídas.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (514, 164, 2, 'Ponto crítico de equidade: não interpretar barreiras culturais ou experiências de racismo como "resistência ao tratamento". Construir vínculo, validar a experiência do paciente e garantir acesso equânime a psicoterapia (e não apenas medicação) é central — pessoas negras recebem menos psicoterapia e menos continuidade do cuidado.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (165, 31, 4, 'Quando referenciar / sinais de alarme clínico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (515, 165, 0, 'Encaminhamento urgente/emergência: risco de suicídio, risco de auto ou heteroagressão, sintomas psicóticos, incapacidade funcional grave, recusa alimentar e sinais de catatonia — encaminhar imediatamente a serviço de urgência psiquiátrica ou CAPS 24h.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (516, 165, 1, 'Encaminhamento à atenção especializada: depressão refratária a dois antidepressivos em dose e tempo adequados, comorbidade com transtorno bipolar, uso de substâncias, transtorno de personalidade, gestação e puerpério, e quadros graves ou recorrentes.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (517, 165, 2, 'Articular com a rede psicossocial (CAPS, NASF/eMulti) e, quando houver vulnerabilidade social, com assistência social — a depressão frequentemente exige intervenção intersetorial.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (166, 31, 5, 'Fontes e diretrizes');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (518, 166, 0, 'Associação Brasileira de Psiquiatria (ABP) — diretrizes nacionais para o manejo da depressão.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (519, 166, 1, 'Ministério da Saúde — Protocolo Clínico e Diretrizes Terapêuticas de Depressão e linhas de cuidado em saúde mental.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (520, 166, 2, 'Organização Mundial da Saúde (OMS) / CID-11 e DSM-5-TR — critérios diagnósticos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (521, 166, 3, 'Literatura sobre disparidades raciais em saúde mental (JAMA Psychiatry, estudos de subdiagnóstico em populações negras).');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (32, 'depressao', 'pt', 'enfermeiro', 'Rastreio e acolhimento do sofrimento psíquico, avaliação de risco de suicídio, apoio ao tratamento continuado e articulação com a rede de saúde mental na Atenção Básica.', 'https://sspark.genspark.ai/i/JKe27K9j1WJNZSzz?width=2560', 'Pessoa sentada em silêncio, com expressão de reflexão, representando o sofrimento psíquico da depressão', 'Imagem placeholder (CC/PD) — substituir por material próprio se necessário', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (167, 32, 0, 'O que é');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (522, 167, 0, 'A depressão é mais do que tristeza passageira: é uma doença que afeta o humor, o pensamento, o sono, o apetite e a energia por semanas, atrapalhando a vida da pessoa. Não é "falta de força de vontade" nem preguiça.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (523, 167, 1, 'Ela tem tratamento e a maioria das pessoas melhora com acompanhamento. Na Atenção Básica, o enfermeiro tem papel central no acolhimento, no rastreio e no vínculo que faz a diferença na continuidade do cuidado.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (168, 32, 1, 'Sinais que a equipe deve reconhecer');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (524, 168, 0, 'Sinais frequentes: tristeza persistente, perda de interesse e prazer, cansaço, alterações de sono (insônia ou dormir demais), mudanças de apetite, dificuldade de concentração, irritabilidade, choro fácil e sentimentos de culpa ou de não ter valor.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (525, 168, 1, 'Sinais de alerta que exigem ação imediata: falas sobre morrer, querer desaparecer, se machucar ou "dar um fim"; planejamento de suicídio; isolamento abrupto; sintomas psicóticos (ouvir vozes, ideias de perseguição). Nesses casos, acione a equipe e o serviço de urgência conforme protocolo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (526, 168, 2, 'Atenção às queixas somáticas repetidas (dor, cansaço, insônia) sem causa aparente: em muitas pessoas, a depressão se manifesta primeiro no corpo — não descarte a possibilidade de sofrimento psíquico.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (169, 32, 2, 'Rastreio e acompanhamento na Atenção Básica');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (527, 169, 0, 'Priorize o rastreio em grupos de maior risco: mulheres negras (subdiagnóstico frequente), gestantes e puérperas, pessoas com doenças crônicas, uso de substâncias, perda recente, violência e vulnerabilidade social.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (528, 169, 1, 'Use instrumentos validados (PHQ-9, GAD-7) como apoio — eles ajudam a objetivar os sintomas e a acompanhar a evolução. Registre sempre a avaliação de risco de suicídio quando houver sinais.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (529, 169, 2, 'No acompanhamento: verifique adesão e efeitos dos medicamentos (nas primeiras semanas podem surgir náuseas, insônia ou inquietação), incentive a continuidade (o tratamento não pode ser interrompido ao se sentir melhor) e organize o retorno e o encaminhamento à psicologia/psiquiatria quando indicado.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (170, 32, 3, 'Quem fica atento — grupos de risco');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (530, 170, 0, 'Grupos que exigem atenção redobrada: pessoas negras (pelo subdiagnóstico e menor acesso a tratamento), mulheres, pessoas em situação de pobreza e insegurança alimentar, pessoas LGBTQIA+ expostas a discriminação, idosos, pessoas com doenças crônicas e com histórico de trauma e violência.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (531, 170, 1, 'Gestantes e puérperas: rastrear depressão perinatal, que é sub-reconhecida, sobretudo em mulheres negras. O cuidado precoce protege a mãe e o bebê.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (532, 170, 2, 'Profissionais e usuários: o sofrimento ligado ao racismo e à discriminação cotidiana deve ser levado a sério como fator de agravo, não como algo a ser minimizado.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (171, 32, 4, 'Cuidado continuado e orientação ao paciente/família');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (533, 171, 0, 'Acolha sem julgamento. Escute o que a pessoa traz, valide o sofrimento e explique, com clareza, que depressão é uma condição de saúde tratável — não uma fraqueza de caráter.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (534, 171, 1, 'Oriente sobre a importância de tomar a medicação no horário, de não interromper o tratamento quando melhorar e de retornar se piorar ou se surgirem pensamentos de morte. Oriente a família a acolher e a observar sinais de risco.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (535, 171, 2, 'Chamada anti-racista: o sofrimento psíquico de pessoas negras é frequentemente minimizado ("tem que ter fé", "é drama") ou atribuído apenas a questões morais ou religiosas. Não banalize: acolha, registre e encaminhe. Levar a sério a dor emocional é um ato de equidade e de combate ao racismo institucional em saúde.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (33, 'depressao', 'pt', 'usuario', 'O que é depressão, por que ela merece atenção na população negra, sinais de alerta, cuidados do dia a dia e onde buscar ajuda gratuita no SUS.', 'https://sspark.genspark.ai/i/JKe27K9j1WJNZSzz?width=2560', 'Pessoa sentada em silêncio, com expressão de reflexão, representando o sofrimento psíquico da depressão', 'Imagem placeholder (CC/PD) — substituir por material próprio se necessário', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (172, 33, 0, 'O que é');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (536, 172, 0, 'Depressão não é frescura nem falta de força de vontade. É uma doença que afeta o humor, o sono, o apetite, a energia e o jeito de pensar por semanas seguidas, atrapalhando o trabalho, os estudos e as relações.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (537, 172, 1, 'É uma condição de saúde como qualquer outra, tem tratamento e a maioria das pessoas melhora. Buscar ajuda não é sinal de fraqueza — é sinal de cuidado consigo mesmo.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (173, 33, 1, 'Por que isso importa');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (538, 173, 0, 'Muitas pessoas negras têm o sofrimento emocional desvalorizado — ouvem que é "falta de fé", "drama" ou "coisa da cabeça". Isso faz muita gente não buscar ajuda e viver anos com uma doença tratável.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (539, 173, 1, 'O racismo, o preconceito e as dificuldades do dia a dia pesam sobre a saúde mental e não são "culpa" de quem sofre. Falar sobre isso e procurar apoio é um direito e um cuidado com a sua vida.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (174, 33, 2, 'Sinais de alerta — fique atento(a)');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (540, 174, 0, 'Procure ajuda se, por mais de duas semanas, você tiver: tristeza que não passa, perda de interesse pelas coisas de que gostava, cansaço, mudanças no sono ou no apetite, dificuldade de concentração, irritação, choro fácil ou sentimento de não valer nada.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (541, 174, 1, 'Vá imediatamente a um serviço de saúde (ou ligue 188 — CVV, 24h) se tiver pensamentos de morrer, de se machucar ou de "desaparecer". Você não está só, isso tem tratamento e existe ajuda gratuita.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (542, 174, 2, 'Cansaço e dores no corpo que não melhoram também podem ser sinais de depressão — vale conversar sobre o que você sente por dentro, não só sobre o corpo.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (175, 33, 3, 'Cuidados do dia a dia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (543, 175, 0, 'Converse com alguém de confiança e com a equipe da UBS. Falar sobre o que sente é parte do tratamento — não guarde tudo sozinho(a).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (544, 175, 1, 'Tome o remédio, quando prescrito, todos os dias e no horário certo. Ele pode levar algumas semanas para fazer efeito — não pare ao se sentir melhor, sem falar com o profissional.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (545, 175, 2, 'Cuide do básico: procure dormir em horários regulares, alimente-se, movimente o corpo (uma caminhada já ajuda) e evite álcool e outras drogas, que pioram o quadro.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (546, 175, 3, 'Busque apoio e pertencimento: grupos, comunidade, fé, amigos. A rede de apoio faz diferença — mas não substitui o tratamento.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (547, 175, 4, 'Tenha paciência consigo mesmo(a): a melhora vem aos poucos, com altos e baixos. Isso é normal e não significa que você está falhando.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (176, 33, 4, 'Onde buscar ajuda no SUS');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (548, 176, 0, 'A Unidade Básica de Saúde (UBS) é a porta de entrada: a equipe acolhe, avalia e oferece acompanhamento. O CAPS (Centro de Atenção Psicossocial) é o serviço especializado em saúde mental — também é gratuito e atende sem necessidade de encaminhamento.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (549, 176, 1, 'Em crises, pensamentos de morte ou risco de se machucar, procure imediatamente uma UPA/pronto-socorro, o CAPS 24h ou ligue 192 (SAMU). O CVV atende 24h, de graça, pelo telefone 188 e pelo chat.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (550, 176, 2, 'Use a página "Rede SUS" desta plataforma para encontrar as unidades e os serviços de saúde mental mais próximos de você no Distrito Federal.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (41, 'depressao', 'pt', 0, 'Associação Brasileira de Psiquiatria (ABP)', 'Diretrizes nacionais para o diagnóstico e o manejo da depressão — referência clínica e apoio técnico de conteúdo.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (42, 'depressao', 'pt', 1, 'Ministério da Saúde — PCDT e linhas de cuidado em saúde mental', 'Protocolo Clínico e Diretrizes Terapêuticas de Depressão e organização da Rede de Atenção Psicossocial (RAPS).');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (43, 'depressao', 'pt', 2, 'OMS / DSM-5-TR / CID-11', 'Critérios diagnósticos e diretrizes internacionais para transtornos depressivos.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (44, 'depressao', 'pt', 3, 'JAMA Psychiatry / estudos de disparidade racial', 'Evidência de subdiagnóstico e menor acesso a tratamento adequado para pessoas negras com depressão.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (34, 'depressao', 'es', 'medico', 'Fisiopatología y clasificación del trastorno depresivo mayor, criterios diagnósticos, diagnóstico diferencial, opciones terapéuticas y evidencia sobre subdiagnóstico y disparidades raciales en el tratamiento.', 'https://sspark.genspark.ai/i/JKe27K9j1WJNZSzz?width=2560', 'Persona sentada en silencio, con expresión de reflexión, representando el sufrimiento psíquico de la depresión', 'Imagen de relleno (CC/PD) — sustituir por material propio si es necesario', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (177, 34, 0, 'Qué es — fisiopatología');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (551, 177, 0, 'El trastorno depresivo mayor (TDM) es un trastorno del humor caracterizado por tristeza persistente y/o anhedonia (pérdida de interés y placer), acompañadas de alteraciones cognitivas, motoras y neurovegetativas (sueño, apetito, energía), con deterioro funcional significativo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (552, 177, 1, 'La fisiopatología es multifactorial e involucra disfunción de circuitos corticolímbicos, desregulación de monoaminas, alteraciones del eje hipotálamo-hipófisis-suprarrenal (HPA), neuroinflamación, cambios neuroplásticos (factor neurotrófico derivado del cerebro — BDNF) y factores genéticos y epigenéticos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (553, 177, 2, 'Los determinantes sociales desempeñan un papel central: la exposición crónica al estrés (incluido el estrés del racismo estructural y de la discriminación), la violencia, la inseguridad financiera y alimentaria, y el aislamiento social alteran de forma mensurable el eje HPA y la carga alostática — convirtiendo el racismo en un determinante del sufrimiento psíquico, y no en un "factor de riesgo" abstracto.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (178, 34, 1, 'Por qué importa — epidemiología y enfoque racial');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (554, 178, 0, 'Las personas negras presentan una carga de sufrimiento psíquico igual o mayor que la población blanca, pero tasas menores de diagnóstico y de tratamiento adecuado. El cuadro es frecuentemente subdiagnosticado o tratado solo como síntoma somático, reflejando racismo institucional y estigma.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (555, 178, 1, 'Cuando se diagnostican, las personas negras tienen menor probabilidad de recibir psicoterapia, medicamentos adecuados en dosis y tiempo correctos, y seguimiento continuo. La depresión posparto en mujeres negras está particularmente subreconocida, a pesar del mayor riesgo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (556, 178, 2, 'El racismo — interpersonal y estructural — funciona como expositor crónico y factor de mantenimiento del sufrimiento. Reconocerlo es esencial para no reducir la depresión en la población negra a una cuestión individual, descontextualizada de las condiciones de vida.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (179, 34, 2, 'Diagnóstico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (557, 179, 0, 'El diagnóstico es clínico, basado en los criterios del DSM-5-TR o de la CIE-11. Para el episodio depresivo mayor, se exige humor deprimido y/o anhedonia durante al menos dos semanas, acompañados de al menos cinco síntomas (alteraciones del sueño, apetito, energía, concentración, psicomotricidad, sentimiento de culpa/desvalorización e ideación suicida).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (558, 179, 1, 'Siempre evaluar el riesgo de suicidio de forma directa y cuidadosa — es una urgencia médica. Aplicar instrumentos de cribado validados (PHQ-9, GAD-7) facilita la detección, especialmente en la Atención Primaria.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (559, 179, 2, 'Diagnóstico diferencial: trastorno bipolar (esencial antes de iniciar un antidepresivo), hipotiroidismo, anemia, deficiencia de vitamina B12/folato, uso de sustancias, efectos de medicamentos y duelo — además de condiciones médicas que simulan la depresión.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (180, 34, 3, 'Tratamiento y conductas');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (560, 180, 0, 'El tratamiento combina psicoterapia (terapia cognitivo-conductual y otros enfoques basados en evidencia), farmacoterapia (antidepresivos — ISRS como primera línea) e intervenciones psicosociales. La elección considera gravedad, comorbilidades, preferencia del paciente y antecedente de respuesta.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (561, 180, 1, 'Los casos graves, refractarios o con riesgo elevado de suicidio pueden exigir combinación de medicamentos, potenciación, terapia electroconvulsiva (TEC) o derivación a servicios especializados. El tratamiento debe continuarse durante el tiempo adecuado para prevenir recaídas.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (562, 180, 2, 'Punto crítico de equidad: no interpretar las barreras culturales o las experiencias de racismo como "resistencia al tratamiento". Construir vínculo, validar la experiencia del paciente y garantizar un acceso equitativo a psicoterapia (y no solo medicación) es central — las personas negras reciben menos psicoterapia y menos continuidad del cuidado.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (181, 34, 4, 'Cuándo derivar / señales de alarma clínica');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (563, 181, 0, 'Derivación urgente/emergencia: riesgo de suicidio, riesgo de auto o heteroagresión, síntomas psicóticos, incapacidad funcional grave, rechazo alimentario y señales de catatonía — derivar de inmediato a un servicio de urgencia psiquiátrica o CAPS 24 h.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (564, 181, 1, 'Derivación a la atención especializada: depresión refractaria a dos antidepresivos en dosis y tiempo adecuados, comorbilidad con trastorno bipolar, uso de sustancias, trastorno de personalidad, embarazo y puerperio, y cuadros graves o recurrentes.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (565, 181, 2, 'Articular con la red psicosocial (CAPS, equipos multiprofesionales) y, cuando haya vulnerabilidad social, con asistencia social — la depresión exige con frecuencia una intervención intersectorial.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (182, 34, 5, 'Fuentes y directrices');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (566, 182, 0, 'Asociación Brasileña de Psiquiatría (ABP) — directrices nacionales para el manejo de la depresión.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (567, 182, 1, 'Ministerio de Salud de Brasil — Protocolo Clínico y Directrices Terapéuticas de Depresión y líneas de cuidado en salud mental.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (568, 182, 2, 'Organización Mundial de la Salud (OMS) / CIE-11 y DSM-5-TR — criterios diagnósticos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (569, 182, 3, 'Literatura sobre disparidades raciales en salud mental (JAMA Psychiatry, estudios de subdiagnóstico en poblaciones negras).');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (35, 'depressao', 'es', 'enfermeiro', 'Cribado y acogida del sufrimiento psíquico, evaluación del riesgo de suicidio, apoyo al tratamiento continuo y articulación con la red de salud mental en la Atención Primaria.', 'https://sspark.genspark.ai/i/JKe27K9j1WJNZSzz?width=2560', 'Persona sentada en silencio, con expresión de reflexión, representando el sufrimiento psíquico de la depresión', 'Imagen de relleno (CC/PD) — sustituir por material propio si es necesario', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (183, 35, 0, 'Qué es');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (570, 183, 0, 'La depresión es más que tristeza pasajera: es una enfermedad que afecta el humor, el pensamiento, el sueño, el apetito y la energía durante semanas, dificultando la vida de la persona. No es "falta de voluntad" ni pereza.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (571, 183, 1, 'Tiene tratamiento y la mayoría de las personas mejora con seguimiento. En la Atención Primaria, el enfermero tiene un papel central en la acogida, el cribado y el vínculo que marca la diferencia en la continuidad del cuidado.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (184, 35, 1, 'Señales que el equipo debe reconocer');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (572, 184, 0, 'Señales frecuentes: tristeza persistente, pérdida de interés y placer, cansancio, alteraciones del sueño (insomnio o dormir demasiado), cambios de apetito, dificultad de concentración, irritabilidad, llanto fácil y sentimientos de culpa o de no valer nada.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (573, 184, 1, 'Señales de alarma que exigen acción inmediata: hablar de morir, querer desaparecer, lastimarse o "acabar con todo"; planificación de suicidio; aislamiento abrupto; síntomas psicóticos (oír voces, ideas de persecución). En esos casos, active al equipo y al servicio de urgencia según protocolo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (574, 184, 2, 'Atención a las quejas somáticas repetidas (dolor, cansancio, insomnio) sin causa aparente: en muchas personas, la depresión se manifiesta primero en el cuerpo — no descarte la posibilidad de sufrimiento psíquico.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (185, 35, 2, 'Cribado y seguimiento en la Atención Primaria');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (575, 185, 0, 'Priorice el cribado en grupos de mayor riesgo: mujeres negras (subdiagnóstico frecuente), gestantes y puérperas, personas con enfermedades crónicas, uso de sustancias, pérdida reciente, violencia y vulnerabilidad social.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (576, 185, 1, 'Use instrumentos validados (PHQ-9, GAD-7) como apoyo — ayudan a objetivar los síntomas y a seguir la evolución. Registre siempre la evaluación del riesgo de suicidio cuando haya señales.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (577, 185, 2, 'En el seguimiento: verifique la adherencia y los efectos de los medicamentos (en las primeras semanas pueden aparecer náuseas, insomnio o inquietud), incentive la continuidad (el tratamiento no puede interrumpirse al sentirse mejor) y organice el retorno y la derivación a psicología/psiquiatría cuando esté indicado.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (186, 35, 3, 'Quién debe estar atento — grupos de riesgo');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (578, 186, 0, 'Grupos que exigen atención redoblada: personas negras (por el subdiagnóstico y menor acceso a tratamiento), mujeres, personas en situación de pobreza e inseguridad alimentaria, personas LGBTQIA+ expuestas a discriminación, ancianos, personas con enfermedades crónicas y con antecedente de trauma y violencia.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (579, 186, 1, 'Gestantes y puérperas: cribar la depresión perinatal, que está subreconocida, sobre todo en mujeres negras. El cuidado precoz protege a la madre y al bebé.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (580, 186, 2, 'El sufrimiento ligado al racismo y a la discriminación cotidiana debe tomarse en serio como factor de agravamiento, no como algo que deba minimizarse.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (187, 35, 4, 'Cuidado continuo y orientación al paciente/familia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (581, 187, 0, 'Acoja sin juzgar. Escuche lo que la persona trae, valide el sufrimiento y explique, con claridad, que la depresión es una condición de salud tratable — no una debilidad de carácter.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (582, 187, 1, 'Oriente sobre la importancia de tomar la medicación en el horario, de no interrumpir el tratamiento cuando mejore y de regresar si empeora o si surgen pensamientos de muerte. Oriente a la familia a acoger y observar señales de riesgo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (583, 187, 2, 'Llamado antirracista: el sufrimiento psíquico de las personas negras es frecuentemente minimizado ("hay que tener fe", "es drama") o atribuido solo a cuestiones morales o religiosas. No banalice: acoja, registre y derive. Tomar en serio el dolor emocional es un acto de equidad y de combate al racismo institucional en salud.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (36, 'depressao', 'es', 'usuario', 'Qué es la depresión, por qué merece atención en la población negra, señales de alerta, cuidados diarios y dónde buscar ayuda gratuita en el SUS.', 'https://sspark.genspark.ai/i/JKe27K9j1WJNZSzz?width=2560', 'Persona sentada en silencio, con expresión de reflexión, representando el sufrimiento psíquico de la depresión', 'Imagen de relleno (CC/PD) — sustituir por material propio si es necesario', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (188, 36, 0, 'Qué es');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (584, 188, 0, 'La depresión no es exageración ni falta de voluntad. Es una enfermedad que afecta el humor, el sueño, el apetito, la energía y la forma de pensar durante semanas seguidas, dificultando el trabajo, los estudios y las relaciones.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (585, 188, 1, 'Es una condición de salud como cualquier otra, tiene tratamiento y la mayoría de las personas mejora. Buscar ayuda no es señal de debilidad — es una señal de cuidado con uno mismo.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (189, 36, 1, 'Por qué importa');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (586, 189, 0, 'A muchas personas negras se les desvaloriza el sufrimiento emocional — oyen que es "falta de fe", "drama" o "cosa de la cabeza". Eso hace que mucha gente no busque ayuda y viva años con una enfermedad tratable.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (587, 189, 1, 'El racismo, el prejuicio y las dificultades del día a día pesan sobre la salud mental y no son "culpa" de quien sufre. Hablar de esto y buscar apoyo es un derecho y un cuidado con tu vida.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (190, 36, 2, 'Señales de alerta — mantente atento(a)');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (588, 190, 0, 'Busca ayuda si, durante más de dos semanas, tienes: tristeza que no pasa, pérdida de interés por las cosas que te gustaban, cansancio, cambios en el sueño o el apetito, dificultad de concentración, irritación, llanto fácil o sentimiento de no valer nada.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (589, 190, 1, 'Acude de inmediato a un servicio de salud (o llama al 188 — CVV, 24 h) si tienes pensamientos de morir, de lastimarte o de "desaparecer". No estás solo, esto tiene tratamiento y existe ayuda gratuita.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (590, 190, 2, 'El cansancio y los dolores en el cuerpo que no mejoran también pueden ser señales de depresión — vale la pena hablar de lo que sientes por dentro, no solo del cuerpo.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (191, 36, 3, 'Cuidados diarios');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (591, 191, 0, 'Conversa con alguien de confianza y con el equipo de la UBS. Hablar de lo que sientes es parte del tratamiento — no lo guardes todo para ti.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (592, 191, 1, 'Toma el medicamento, cuando esté prescrito, todos los días y en el horario correcto. Puede tardar algunas semanas en hacer efecto — no lo suspendas al sentirte mejor, sin hablar con el profesional.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (593, 191, 2, 'Cuida lo básico: procura dormir en horarios regulares, aliméntate, mueve el cuerpo (una caminata ya ayuda) y evita el alcohol y otras drogas, que empeoran el cuadro.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (594, 191, 3, 'Busca apoyo y pertenencia: grupos, comunidad, fe, amigos. La red de apoyo marca la diferencia — pero no sustituye el tratamiento.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (595, 191, 4, 'Ten paciencia contigo mismo(a): la mejoría llega poco a poco, con altibajos. Esto es normal y no significa que estés fallando.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (192, 36, 4, 'Dónde buscar ayuda en el SUS');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (596, 192, 0, 'La Unidad Básica de Salud (UBS) es la puerta de entrada: el equipo acoge, evalúa y ofrece seguimiento. El CAPS (Centro de Atención Psicosocial) es el servicio especializado en salud mental — también es gratuito y atiende sin necesidad de derivación.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (597, 192, 1, 'En crisis, pensamientos de muerte o riesgo de lastimarte, acude de inmediato a urgencias, al CAPS 24 h o llama al 192 (SAMU). El CVV atiende 24 h, gratis, por el teléfono 188 y por el chat.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (598, 192, 2, 'Usa la página "Red SUS" de esta plataforma para encontrar las unidades y los servicios de salud mental más cercanos a ti en el Distrito Federal.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (45, 'depressao', 'es', 0, 'Asociación Brasileña de Psiquiatría (ABP)', 'Directrices nacionales para el diagnóstico y el manejo de la depresión — referencia clínica y apoyo técnico de contenido.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (46, 'depressao', 'es', 1, 'Ministerio de Salud de Brasil — PCDT y líneas de cuidado en salud mental', 'Protocolo Clínico y Directrices Terapéuticas de Depresión y organización de la Red de Atención Psicosocial (RAPS).');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (47, 'depressao', 'es', 2, 'OMS / DSM-5-TR / CIE-11', 'Criterios diagnósticos y directrices internacionales para los trastornos depresivos.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (48, 'depressao', 'es', 3, 'JAMA Psychiatry / estudios de disparidad racial', 'Evidencia de subdiagnóstico y menor acceso a tratamiento adecuado para personas negras con depresión.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (37, 'asma', 'pt', 'medico', 'Fisiopatologia da asma, classificação de controle e gravidade, diagnóstico funcional, tratamento por etapas e evidência sobre disparidades raciais em mortalidade e acesso ao cuidado contínuo.', 'https://sspark.genspark.ai/i/Xg1kmnIK4FSMzzip?width=2560', 'Pessoa utilizando inalador (bombinha) para controle da asma, com via aérea ilustrada ao fundo', 'Imagem placeholder (CC/PD) — substituir por material próprio se necessário', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (193, 37, 0, 'O que é — fisiopatologia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (599, 193, 0, 'A asma é uma doença inflamatória crônica das vias aéreas, caracterizada por hiperresponsividade brônquica, obstrução variável ao fluxo aéreo e sintomas recorrentes (sibilância, dispneia, aperto torácico e tosse), que variam ao longo do tempo e em intensidade.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (600, 193, 1, 'A inflamação envolve predominantemente eosinófilos e linfócitos Th2 (asma alérgica), com subtipos não-Th2 (neutrofílica, mista) em parte dos pacientes. Remodelamento das vias aéreas, exposição a alérgenos, infecções virais, poluição do ar, tabagismo e fatores ocupacionais atuam como gatilhos e moduladores.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (601, 193, 2, 'Determinantes sociais são centrais: exposição desproporcional a poluição, moradia insalubre (mofo, umidade, pragas), violência urbana e estresse crônico contribuem tanto para a maior prevalência quanto para a maior gravidade. O racismo estrutural, ao concentrar esses fatores em territórios negros e periféricos, atua como determinante ambiental mensurável.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (194, 37, 1, 'Por que importa — epidemiologia e recorte racial');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (602, 194, 0, 'Crianças negras apresentam taxa de mortalidade por asma cerca de 7 vezes maior que crianças brancas, associada a maior exposição ambiental, subdiagnóstico e menor acesso a tratamento contínuo (corticoide inalatório de manutenção).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (603, 194, 1, 'A asma na população negra tende a ser mais grave, com mais exacerbações, mais idas à emergência e mais hospitalizações evitáveis — um marcador de falha no cuidado primário continuado, e não apenas de biologia. A mortalidade por asma é, em grande parte, evitável com o tratamento adequado.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (604, 194, 2, 'A disparidade combina exposição ambiental desproporcional (poluição, moradia, território), acesso desigual a especialistas e a medicamentos de controle, e menor educação em saúde sobre o uso correto dos dispositivos inalatórios.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (195, 37, 2, 'Diagnóstico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (605, 195, 0, 'O diagnóstico é clínico, apoiado por demonstração de variabilidade do fluxo aéreo: espirometria com prova broncodilatadora (aumento do VEF1 ≥ 12% e ≥ 200 mL), variabilidade do PFE, ou testes de broncoprovocação quando a espirometria é normal e a suspeita persiste.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (606, 195, 1, 'Avaliar controle (GINA) e gravidade, além de fatores de risco para exacerbações: uso excessivo de SABA (broncodilatador de resgate), exacerbação prévia grave, má adesão, técnica inalatória inadequada, exposição a tabaco e comorbidades (rinite alérgica, obesidade, refluxo).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (607, 195, 2, 'Diagnóstico diferencial: DPOC (especialmente em fumantes), bronquiolite, disfunção de cordas vocais, insuficiência cardíaca e tosse por outras causas. A atopia e a história familiar são frequentes, mas não obrigatórias.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (196, 37, 3, 'Tratamento e condutas');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (608, 196, 0, 'O pilar do tratamento é o corticoide inalatório (CI) de manutenção — mesmo em asma leve — para controlar a inflamação e prevenir exacerbações, combinado com broncodilatador de resgate conforme necessidade. O esquema segue a abordagem por etapas do GINA, escalonando ou reduzindo conforme o controle.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (609, 196, 1, 'Educação em saúde, verificação da técnica inalatória (essencial e frequentemente negligenciada), plano de ação escrito para crises, controle de gatilhos e tratamento de comorbidades são parte indissociável do manejo. A via de resgate com corticoide inalatório (MART/SMART) reduz exacerbações em pacientes elegíveis.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (610, 196, 2, 'Ponto crítico de equidade: o subtratamento com CI de manutenção e o uso excessivo de SABA (alívio) refletem acesso desigual e educação insuficiente, não "asma leve". Garantir CI gratuito, dispositivos adequados e plano de ação escrito para crianças negras é medida de equidade e de prevenção de mortes evitáveis.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (197, 37, 4, 'Quando referenciar / sinais de alarme clínico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (611, 197, 0, 'Encaminhamento urgente/emergência: crise grave com incapacidade de falar frases completas, uso de musculatura acessória, cianose, sonolência/confusão, saturação baixa, PFE < 50% do previsto — atendimento hospitalar imediato com oxigênio, broncodilatador e corticoide sistêmico.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (612, 197, 1, 'Encaminhamento à pneumologia: asma não controlada apesar de tratamento otimizado, exacerbações recorrentes, dúvida diagnóstica, necessidade de investigação de comorbidades ou de fenotipagem, e uso de doses elevadas de CI.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (613, 197, 2, 'Sinais de alarme para a família/profissional: histórico de internação em UTI, exacerbação grave prévia, uso de múltiplos frascos de resgate por mês e despertares noturnos frequentes — todos indicam risco elevado e exigem revisão do tratamento.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (198, 37, 5, 'Fontes e diretrizes');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (614, 198, 0, 'Sociedade Brasileira de Pneumologia e Tisiologia (SBPT) — diretrizes brasileiras para o manejo da asma.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (615, 198, 1, 'Global Initiative for Asthma (GINA) — estratégia global baseada em evidência para diagnóstico e manejo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (616, 198, 2, 'Ministério da Saúde — Protocolo Clínico e Diretrizes Terapêuticas de Asma e componentes do cuidado na Atenção Básica.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (617, 198, 3, 'Literatura sobre disparidades raciais em asma (CDC, NIH) — evidência de maior mortalidade e exposição ambiental em crianças negras.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (38, 'asma', 'pt', 'enfermeiro', 'Reconhecimento da crise asmática e da classificação de risco, orientação sobre o uso correto dos inaladores, educação para o autocontrole e acompanhamento contínuo na Atenção Básica.', 'https://sspark.genspark.ai/i/Xg1kmnIK4FSMzzip?width=2560', 'Pessoa utilizando inalador (bombinha) para controle da asma, com via aérea ilustrada ao fundo', 'Imagem placeholder (CC/PD) — substituir por material próprio se necessário', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (199, 38, 0, 'O que é');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (618, 199, 0, 'A asma é uma doença crônica das vias aéreas (os "caninhos" do pulmão). Elas ficam inflamadas e sensíveis, e, quando algo irrita, estreitam e dificultam a passagem do ar. Isso causa chiado, falta de ar, aperto no peito e tosse.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (619, 199, 1, 'A asma não tem cura, mas tem controle muito bom: com a medicação de manutenção e o uso correto dos inaladores, a pessoa pode viver sem crises e sem limitações.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (200, 38, 1, 'Sinais que a equipe deve reconhecer');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (620, 200, 0, 'Sinais de crise: chiado no peito, tosse (às vezes seca, pior à noite), falta de ar, aperto no peito, dificuldade para dormir e cansaço aos esforços. Crises noturnas e uso frequente da "bombinha" de resgate indicam asma não controlada.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (621, 200, 1, 'Sinais de crise grave (emergência): não conseguir falar frases completas, usar a musculatura entre as costelas para respirar, lábios/pontas dos dedos arroxeados, sonolência, confusão ou agitação — atendimento imediato.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (622, 200, 2, 'Prestar atenção à frequência do uso do broncodilatador de alívio: se a pessoa usa muitas vezes por semana ou acorda à noite por causa da asma, o controle está inadequado e o tratamento de manutenção precisa ser revisto.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (201, 38, 2, 'Classificação de risco e manejo na unidade');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (623, 201, 0, 'Na crise, classifique a gravidade: nível de consciência, capacidade de falar, uso de musculatura acessória, frequência respiratória, saturação de oxigênio e pico de fluxo expiratório (PFE). Crises leves/moderadas podem ser manejadas com broncodilatador e reavaliação; crises graves exigem acionamento imediato e encaminhamento.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (624, 201, 1, 'Técnica inalatória é decisiva: a maioria das "falhas de tratamento" é, na verdade, técnica incorreta. Demonstre e observe o uso do inalador dosimetrado (com espaçador, quando indicado) a cada consulta — não presuma que a pessoa sabe usar.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (625, 201, 2, 'Verifique e registre: adesão ao corticoide inalatório, disponibilidade do medicamento na farmácia, técnica inalatória, plano de ação escrito, controle dos gatilhos (poeira, mofo, fumaça, animais) e vacinação (influenza e COVID-19).');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (202, 38, 3, 'Quem fica atento — grupos de risco');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (626, 202, 0, 'Grupos que exigem atenção redobrada: crianças negras (maior mortalidade e exposição ambiental), crianças e adolescentes, pessoas com rinite alérgica, obesidade ou refluxo, fumantes e ex-fumantes, gestantes e pessoas que vivem em áreas com maior poluição ou moradia insalubre.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (627, 202, 1, 'Pessoas com histórico de exacerbação grave, internação prévia ou uso excessivo de resgate precisam de acompanhamento mais próximo e revisão do tratamento.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (628, 202, 2, 'Atenção ao ambiente: condições de moradia (mofo, umidade, pragas, aglomeração) e poluição do território são determinantes de gravidade — perguntar sobre elas faz parte da avaliação.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (203, 38, 4, 'Cuidado continuado e orientação ao paciente/família');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (629, 203, 0, 'Explique a diferença entre a "bombinha" de alívio (resgate) e a de manutenção (corticoide inalatório): a de manutenção precisa ser usada todos os dias, mesmo sem sintomas, para prevenir crises. Esse é o ponto que mais muda o desfecho.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (630, 203, 1, 'Ensine e pratique a técnica inalatória, entregue/revise um plano de ação escrito (o que fazer quando piora), oriente sobre como reconhecer os sinais de alerta e quando procurar atendimento imediato. Oriente a manter a vacinação em dia e a reduzir gatilhos em casa.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (631, 203, 2, 'Chamada anti-racista: crianças negras morrem de asma em proporção muito maior, muitas vezes por falta de acesso ao corticoide inalatório de manutenção e por subvalorização dos sintomas. Não minimize a queixa respiratória de uma criança negra ("é só uma tosse") nem presuma falta de adesão sem verificar acesso ao medicamento, técnica inalatória e condições de moradia. É um viés a ser combatido ativamente na prática clínica.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (39, 'asma', 'pt', 'usuario', 'O que é asma, por que é mais grave em crianças negras, sinais de alerta, cuidados do dia a dia e onde buscar ajuda gratuita no SUS.', 'https://sspark.genspark.ai/i/Xg1kmnIK4FSMzzip?width=2560', 'Pessoa utilizando inalador (bombinha) para controle da asma, com via aérea ilustrada ao fundo', 'Imagem placeholder (CC/PD) — substituir por material próprio se necessário', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (204, 39, 0, 'O que é');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (632, 204, 0, 'Asma é uma doença dos "caninhos" do pulmão (as vias aéreas). Eles ficam inflamados e sensíveis e, quando algo irrita, estreitam e deixam o ar passar com dificuldade. Isso provoca chiado, falta de ar, aperto no peito e tosse.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (633, 204, 1, 'A asma não tem cura, mas tem controle. Com o remédio de manutenção todos os dias e o uso correto da "bombinha", é possível viver sem crises e sem limitações.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (205, 39, 1, 'Por que isso importa');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (634, 205, 0, 'Crianças negras têm muito mais risco de morrer de asma do que crianças brancas. Isso não acontece por acaso: tem relação com morar em lugares mais poluídos, com casas com mofo e umidade, e com menos acesso ao remédio de manutenção e a um acompanhamento de qualidade.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (635, 205, 1, 'A boa notícia: as mortes por asma são, em grande parte, evitáveis. Com tratamento contínuo, educação sobre a doença e uso correto dos inaladores, dá para controlar muito bem.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (206, 39, 2, 'Sinais de alerta — fique atento(a)');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (636, 206, 0, 'Procure a UBS se você ou sua criança tiverem, com frequência: chiado no peito, tosse (principalmente à noite), falta de ar, aperto no peito ou acordar de madrugada por causa da respiração.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (637, 206, 1, 'Atenção ao uso da "bombinha de alívio": se ela é usada muitas vezes por semana ou à noite, a asma não está controlada — procure a equipe para ajustar o tratamento.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (638, 206, 2, 'Vá imediatamente à UPA/pronto-socorro se houver: não conseguir falar frases completas, esforço muito grande para respirar (afundando as costelas), lábios ou dedos arroxeados, sonolência ou confusão. Isso é uma crise grave.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (207, 39, 3, 'Cuidados do dia a dia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (639, 207, 0, 'Use o remédio de manutenção (a bombinha de corticoide) todos os dias, mesmo quando estiver se sentindo bem — ele é o que evita as crises. A bombinha de alívio é só para quando os sintomas aparecem.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (640, 207, 1, 'Aprenda a usar o inalador do jeito certo — com espaçador, quando indicado — e confirme a técnica na UBS. Usar a bombinha de forma errada é uma das principais causas de a asma ficar descontrolada.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (641, 207, 2, 'Reduza os gatilhos em casa: evite mofo e umidade, areje os ambientes, troque roupas de cama com frequência, evite fumaça (cigarro, incenso, vela) e mantenha a casa livre de poeira e pragas.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (642, 207, 3, 'Mantenha as vacinas em dia (gripe e COVID-19), que reduzem crises, e tenha sempre um plano de ação por escrito: saiba o que fazer e quando procurar ajuda quando a asma piorar.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (643, 207, 4, 'Não aceite "asma é assim mesmo". Com o tratamento certo, a maioria das pessoas pode dormir bem, brincar, estudar e fazer atividade física sem crises.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (208, 39, 4, 'Onde buscar ajuda no SUS');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (644, 208, 0, 'A Unidade Básica de Saúde (UBS) é o lugar certo para acompanhar a asma e retirar os medicamentos (inclusive o corticoide inalatório de manutenção), que são gratuitos no SUS.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (645, 208, 1, 'Em crise grave (não consegue falar, muito esforço para respirar, lábios arroxeados, sonolência), procure a UPA ou o pronto-socorro imediatamente ou ligue 192 (SAMU).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (646, 208, 2, 'Use a página "Rede SUS" desta plataforma para encontrar as unidades de saúde mais próximas de você no Distrito Federal.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (49, 'asma', 'pt', 0, 'SBPT', 'Sociedade Brasileira de Pneumologia e Tisiologia — diretrizes brasileiras para o manejo da asma.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (50, 'asma', 'pt', 1, 'Global Initiative for Asthma (GINA)', 'Estratégia global baseada em evidência para diagnóstico, classificação e tratamento por etapas da asma.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (51, 'asma', 'pt', 2, 'Ministério da Saúde — PCDT Asma', 'Protocolo Clínico e Diretrizes Terapêuticas vigente e organização do cuidado na Atenção Básica.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (52, 'asma', 'pt', 3, 'CDC / NIH — disparidades raciais', 'Evidência de mortalidade desproporcional por asma em crianças negras e de maior exposição ambiental.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (40, 'asma', 'es', 'medico', 'Fisiopatología del asma, clasificación de control y gravedad, diagnóstico funcional, tratamiento por etapas y evidencia sobre disparidades raciales en mortalidad y acceso al cuidado continuo.', 'https://sspark.genspark.ai/i/Xg1kmnIK4FSMzzip?width=2560', 'Persona utilizando un inhalador para el control del asma, con la vía aérea ilustrada al fondo', 'Imagen de relleno (CC/PD) — sustituir por material propio si es necesario', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (209, 40, 0, 'Qué es — fisiopatología');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (647, 209, 0, 'El asma es una enfermedad inflamatoria crónica de las vías respiratorias, caracterizada por hiperreactividad bronquial, obstrucción variable al flujo aéreo y síntomas recurrentes (sibilancias, disnea, opresión torácica y tos), que varían a lo largo del tiempo y en intensidad.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (648, 209, 1, 'La inflamación involucra predominantemente eosinófilos y linfocitos Th2 (asma alérgica), con subtipos no-Th2 (neutrofílica, mixta) en parte de los pacientes. El remodelado de las vías respiratorias, la exposición a alérgenos, las infecciones virales, la contaminación del aire, el tabaquismo y los factores ocupacionales actúan como desencadenantes y moduladores.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (649, 209, 2, 'Los determinantes sociales son centrales: la exposición desproporcionada a la contaminación, la vivienda insalubre (moho, humedad, plagas), la violencia urbana y el estrés crónico contribuyen tanto a la mayor prevalencia como a la mayor gravedad. El racismo estructural, al concentrar estos factores en territorios negros y periféricos, actúa como un determinante ambiental mensurable.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (210, 40, 1, 'Por qué importa — epidemiología y enfoque racial');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (650, 210, 0, 'Los niños negros presentan una tasa de mortalidad por asma cerca de 7 veces mayor que los niños blancos, asociada a mayor exposición ambiental, subdiagnóstico y menor acceso al tratamiento continuo (corticoide inhalado de mantenimiento).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (651, 210, 1, 'El asma en la población negra tiende a ser más grave, con más exacerbaciones, más visitas a urgencias y más hospitalizaciones evitables — un marcador de falla en el cuidado primario continuo, y no solo de biología. La mortalidad por asma es, en gran parte, evitable con el tratamiento adecuado.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (652, 210, 2, 'La disparidad combina exposición ambiental desproporcionada (contaminación, vivienda, territorio), acceso desigual a especialistas y a medicamentos de control, y menor educación en salud sobre el uso correcto de los dispositivos inhaladores.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (211, 40, 2, 'Diagnóstico');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (653, 211, 0, 'El diagnóstico es clínico, apoyado en la demostración de variabilidad del flujo aéreo: espirometría con prueba broncodilatadora (aumento del VEF1 ≥ 12% y ≥ 200 mL), variabilidad del PEF, o pruebas de broncoprovocación cuando la espirometría es normal y la sospecha persiste.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (654, 211, 1, 'Evaluar control (GINA) y gravedad, además de factores de riesgo de exacerbaciones: uso excesivo de SABA (broncodilatador de rescate), exacerbación previa grave, mala adherencia, técnica inhalatoria inadecuada, exposición al tabaco y comorbilidades (rinitis alérgica, obesidad, reflujo).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (655, 211, 2, 'Diagnóstico diferencial: EPOC (especialmente en fumadores), bronquiolitis, disfunción de cuerdas vocales, insuficiencia cardíaca y tos por otras causas. La atopia y el antecedente familiar son frecuentes, pero no obligatorios.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (212, 40, 3, 'Tratamiento y conductas');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (656, 212, 0, 'El pilar del tratamiento es el corticoide inhalado (CI) de mantenimiento — incluso en asma leve — para controlar la inflamación y prevenir exacerbaciones, combinado con broncodilatador de rescate según necesidad. El esquema sigue el abordaje por etapas del GINA, escalonando o reduciendo según el control.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (657, 212, 1, 'La educación en salud, la verificación de la técnica inhalatoria (esencial y frecuentemente descuidada), el plan de acción escrito para crisis, el control de desencadenantes y el tratamiento de comorbilidades son parte indisociable del manejo. La vía de rescate con corticoide inhalado (MART/SMART) reduce exacerbaciones en pacientes elegibles.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (658, 212, 2, 'Punto crítico de equidad: el subtratamiento con CI de mantenimiento y el uso excesivo de SABA (alivio) reflejan acceso desigual y educación insuficiente, no "asma leve". Garantizar CI gratuito, dispositivos adecuados y plan de acción escrito para niños negros es una medida de equidad y de prevención de muertes evitables.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (213, 40, 4, 'Cuándo derivar / señales de alarma clínica');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (659, 213, 0, 'Derivación urgente/emergencia: crisis grave con incapacidad de hablar frases completas, uso de musculatura accesoria, cianosis, somnolencia/confusión, saturación baja, PEF < 50% del previsto — atención hospitalaria inmediata con oxígeno, broncodilatador y corticoide sistémico.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (660, 213, 1, 'Derivación a neumología: asma no controlada a pesar de tratamiento optimizado, exacerbaciones recurrentes, duda diagnóstica, necesidad de investigación de comorbilidades o de fenotipificación, y uso de dosis elevadas de CI.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (661, 213, 2, 'Señales de alarma para la familia/profesional: antecedente de internación en UCI, exacerbación grave previa, uso de múltiples frascos de rescate por mes y despertares nocturnos frecuentes — todos indican riesgo elevado y exigen revisión del tratamiento.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (214, 40, 5, 'Fuentes y directrices');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (662, 214, 0, 'Sociedad Brasileña de Neumología y Tisiología (SBPT) — directrices brasileñas para el manejo del asma.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (663, 214, 1, 'Global Initiative for Asthma (GINA) — estrategia global basada en evidencia para diagnóstico y manejo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (664, 214, 2, 'Ministerio de Salud de Brasil — Protocolo Clínico y Directrices Terapéuticas de Asma y componentes del cuidado en la Atención Primaria.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (665, 214, 3, 'Literatura sobre disparidades raciales en asma (CDC, NIH) — evidencia de mayor mortalidad y exposición ambiental en niños negros.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (41, 'asma', 'es', 'enfermeiro', 'Reconocimiento de la crisis asmática y de la clasificación de riesgo, orientación sobre el uso correcto de los inhaladores, educación para el autocontrol y seguimiento continuo en la Atención Primaria.', 'https://sspark.genspark.ai/i/Xg1kmnIK4FSMzzip?width=2560', 'Persona utilizando un inhalador para el control del asma, con la vía aérea ilustrada al fondo', 'Imagen de relleno (CC/PD) — sustituir por material propio si es necesario', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (215, 41, 0, 'Qué es');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (666, 215, 0, 'El asma es una enfermedad crónica de las vías respiratorias (los "tubitos" del pulmón). Se inflaman y se vuelven sensibles y, cuando algo los irrita, se estrechan y dificultan el paso del aire. Esto causa sibilancias (silbido), falta de aire, opresión en el pecho y tos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (667, 215, 1, 'El asma no tiene cura, pero tiene muy buen control: con la medicación de mantenimiento y el uso correcto de los inhaladores, la persona puede vivir sin crisis y sin limitaciones.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (216, 41, 1, 'Señales que el equipo debe reconocer');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (668, 216, 0, 'Señales de crisis: silbido en el pecho, tos (a veces seca, peor de noche), falta de aire, opresión en el pecho, dificultad para dormir y cansancio a los esfuerzos. Las crisis nocturnas y el uso frecuente del inhalador de rescate indican asma no controlada.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (669, 216, 1, 'Señales de crisis grave (emergencia): no lograr hablar frases completas, usar la musculatura entre las costillas para respirar, labios/puntas de los dedos amoratados, somnolencia, confusión o agitación — atención inmediata.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (670, 216, 2, 'Prestar atención a la frecuencia de uso del broncodilatador de alivio: si la persona lo usa muchas veces por semana o se despierta de noche por el asma, el control es inadecuado y el tratamiento de mantenimiento debe revisarse.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (217, 41, 2, 'Clasificación de riesgo y manejo en la unidad');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (671, 217, 0, 'En la crisis, clasifique la gravedad: nivel de conciencia, capacidad de hablar, uso de musculatura accesoria, frecuencia respiratoria, saturación de oxígeno y flujo espiratorio máximo (PEF). Las crisis leves/moderadas pueden manejarse con broncodilatador y reevaluación; las crisis graves exigen activación inmediata y derivación.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (672, 217, 1, 'La técnica inhalatoria es decisiva: la mayoría de las "fallas de tratamiento" son, en realidad, técnica incorrecta. Demuestre y observe el uso del inhalador dosificador (con espaciador, cuando esté indicado) en cada consulta — no presuma que la persona sabe usarlo.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (673, 217, 2, 'Verifique y registre: adherencia al corticoide inhalado, disponibilidad del medicamento en la farmacia, técnica inhalatoria, plan de acción escrito, control de los desencadenantes (polvo, moho, humo, animales) y vacunación (influenza y COVID-19).');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (218, 41, 3, 'Quién debe estar atento — grupos de riesgo');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (674, 218, 0, 'Grupos que exigen atención redoblada: niños negros (mayor mortalidad y exposición ambiental), niños y adolescentes, personas con rinitis alérgica, obesidad o reflujo, fumadores y exfumadores, gestantes y personas que viven en áreas con mayor contaminación o vivienda insalubre.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (675, 218, 1, 'Las personas con antecedente de exacerbación grave, internación previa o uso excesivo de rescate necesitan un seguimiento más cercano y revisión del tratamiento.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (676, 218, 2, 'Atención al ambiente: las condiciones de vivienda (moho, humedad, plagas, hacinamiento) y la contaminación del territorio son determinantes de gravedad — preguntar sobre ellas forma parte de la evaluación.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (219, 41, 4, 'Cuidado continuo y orientación al paciente/familia');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (677, 219, 0, 'Explique la diferencia entre el inhalador de alivio (rescate) y el de mantenimiento (corticoide inhalado): el de mantenimiento debe usarse todos los días, incluso sin síntomas, para prevenir crisis. Este es el punto que más cambia el desenlace.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (678, 219, 1, 'Enseñe y practique la técnica inhalatoria, entregue/revise un plan de acción escrito (qué hacer cuando empeora), oriente sobre cómo reconocer las señales de alerta y cuándo buscar atención inmediata. Oriente a mantener la vacunación al día y a reducir los desencadenantes en casa.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (679, 219, 2, 'Llamado antirracista: los niños negros mueren de asma en una proporción mucho mayor, muchas veces por falta de acceso al corticoide inhalado de mantenimiento y por la subvaloración de los síntomas. No minimice la queja respiratoria de un niño negro ("es solo una tos") ni presuma falta de adherencia sin verificar el acceso al medicamento, la técnica inhalatoria y las condiciones de vivienda. Es un sesgo que debe combatirse activamente en la práctica clínica.');
INSERT OR REPLACE INTO disease_content (id, disease_id, locale_id, audience, summary, hero_image_url, hero_image_alt, hero_image_credit, hero_is_placeholder) VALUES (42, 'asma', 'es', 'usuario', 'Qué es el asma, por qué es más grave en los niños negros, señales de alerta, cuidados diarios y dónde buscar ayuda gratuita en el SUS.', 'https://sspark.genspark.ai/i/Xg1kmnIK4FSMzzip?width=2560', 'Persona utilizando un inhalador para el control del asma, con la vía aérea ilustrada al fondo', 'Imagen de relleno (CC/PD) — sustituir por material propio si es necesario', 1);
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (220, 42, 0, 'Qué es');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (680, 220, 0, 'El asma es una enfermedad de los "tubitos" del pulmón (las vías respiratorias). Se inflaman y se vuelven sensibles y, cuando algo los irrita, se estrechan y dejan pasar el aire con dificultad. Esto provoca silbido, falta de aire, opresión en el pecho y tos.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (681, 220, 1, 'El asma no tiene cura, pero tiene control. Con el medicamento de mantenimiento todos los días y el uso correcto del inhalador, es posible vivir sin crisis y sin limitaciones.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (221, 42, 1, 'Por qué importa');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (682, 221, 0, 'Los niños negros tienen mucho más riesgo de morir de asma que los niños blancos. Esto no ocurre por casualidad: tiene relación con vivir en lugares más contaminados, con casas con moho y humedad, y con menos acceso al medicamento de mantenimiento y a un seguimiento de calidad.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (683, 221, 1, 'La buena noticia: las muertes por asma son, en gran parte, evitables. Con tratamiento continuo, educación sobre la enfermedad y uso correcto de los inhaladores, se puede controlar muy bien.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (222, 42, 2, 'Señales de alerta — mantente atento(a)');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (684, 222, 0, 'Acude a la UBS si tú o tu niño tienen, con frecuencia: silbido en el pecho, tos (sobre todo de noche), falta de aire, opresión en el pecho o despertarse de madrugada por la respiración.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (685, 222, 1, 'Atención al uso del inhalador de alivio: si se usa muchas veces por semana o de noche, el asma no está controlada — acude al equipo para ajustar el tratamiento.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (686, 222, 2, 'Acude de inmediato a urgencias si hay: no lograr hablar frases completas, esfuerzo muy grande para respirar (hundiendo las costillas), labios o dedos amoratados, somnolencia o confusión. Esto es una crisis grave.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (223, 42, 3, 'Cuidados diarios');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (687, 223, 0, 'Usa el medicamento de mantenimiento (el inhalador con corticoide) todos los días, aunque te sientas bien — es lo que evita las crisis. El inhalador de alivio es solo para cuando aparecen los síntomas.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (688, 223, 1, 'Aprende a usar el inhalador de la manera correcta — con espaciador, cuando esté indicado — y confirma la técnica en la UBS. Usar el inhalador de forma incorrecta es una de las principales causas de que el asma se descontrole.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (689, 223, 2, 'Reduce los desencadenantes en casa: evita moho y humedad, ventila los ambientes, cambia la ropa de cama con frecuencia, evita el humo (cigarrillo, incienso, vela) y mantén la casa libre de polvo y plagas.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (690, 223, 3, 'Mantén las vacunas al día (gripe y COVID-19), que reducen las crisis, y ten siempre un plan de acción escrito: sabe qué hacer y cuándo buscar ayuda cuando el asma empeore.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (691, 223, 4, 'No aceptes "el asma es así". Con el tratamiento correcto, la mayoría de las personas puede dormir bien, jugar, estudiar y hacer actividad física sin crisis.');
INSERT OR REPLACE INTO disease_sections (id, content_id, position, heading) VALUES (224, 42, 4, 'Dónde buscar ayuda en el SUS');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (692, 224, 0, 'La Unidad Básica de Salud (UBS) es el lugar correcto para el seguimiento del asma y para retirar los medicamentos (incluido el corticoide inhalado de mantenimiento), que son gratuitos en el SUS.');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (693, 224, 1, 'En crisis grave (no logra hablar, mucho esfuerzo para respirar, labios amoratados, somnolencia), acude de inmediato a urgencias o llama al 192 (SAMU).');
INSERT OR REPLACE INTO disease_paragraphs (id, section_id, position, body) VALUES (694, 224, 2, 'Usa la página "Red SUS" de esta plataforma para encontrar las unidades de salud más cercanas a ti en el Distrito Federal.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (53, 'asma', 'es', 0, 'SBPT', 'Sociedad Brasileña de Neumología y Tisiología — directrices brasileñas para el manejo del asma.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (54, 'asma', 'es', 1, 'Global Initiative for Asthma (GINA)', 'Estrategia global basada en evidencia para diagnóstico, clasificación y tratamiento por etapas del asma.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (55, 'asma', 'es', 2, 'Ministerio de Salud de Brasil — PCDT Asma', 'Protocolo Clínico y Directrices Terapéuticas vigente y organización del cuidado en la Atención Primaria.');
INSERT OR REPLACE INTO disease_sources (id, disease_id, locale_id, position, label, detail) VALUES (56, 'asma', 'es', 3, 'CDC / NIH — disparidades raciales', 'Evidencia de mortalidad desproporcionada por asma en niños negros y de mayor exposición ambiental.');
